window.__DICT_CHUNKS__=window.__DICT_CHUNKS__||{};window.__DICT_CHUNKS__["W"]={"7586":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /weɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive always + adverb/preposition, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to walk through water that is not deep ► see thesaurus at walk</div></div>","7587":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wæɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(past tense and past participle wagged, present participle wagging)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> if a dog wags its tail, or if its tail wags, the dog moves its tail many times from one side to the other</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to move your finger or head from side to side, especially to show disapproval:</div><ul class=\"examples\"><li><em>‘You naughty girl!’ Mom said, wagging her finger at me.</em></li></ul></div>","7588":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /weɪdʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[singular]</span> (also wages<span class=\"gram\">[plural]</span>) money you earn that is paid according to the number of hours, days, or weeks that you work → salary:</div><ul class=\"examples\"><li><em>He earns a good wage.</em></li><li><strong><em>wage increase<strong> (also</strong>wage rise<em>)British English</em></strong>: The wage increases will come into effect in June.</em></li><li><strong><em>daily/weekly etc wage</strong>: a weekly wage of $250</em></li><li><strong><em>wage levels/rates</strong> (=fixed amounts of money paid for particular jobs)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>a living wage</strong> money you earn for work that is enough to pay for the basic things that you need to live:</div><ul class=\"examples\"><li><em>The church no longer paid a living wage.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>wage freeze</strong> an action taken by a company, government etc to stop wages increasing</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>wage claim</strong> the amount of money asked for by workers as an increase in wages</div></div>","7589":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wag‧on</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwæɡən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a strong vehicle with four wheels, used for carrying heavy loads and usually pulled by horses → cart</div><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> a large open container pulled by a train, used for carrying goods SYN freight car<em>American English</em></div><div class=\"sense\"><span class=\"snum\">3</span> <strong>be/go on the wagon</strong> <em>informal</em> to not drink alcohol anymore</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>fall off the wagon</strong> <em>informal</em> to start drinking alcohol again after you have stopped</div></div>","7590":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /weɪst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the narrow part in the middle of the human body:</div><ul class=\"examples\"><li><em>The skirt was too big around the waist.</em></li><li><strong><em>from the waist up/down</strong> (=in the top or bottom half of your body): Lota was paralysed from the waist down.</em></li><li><strong><em>stripped to the waist</strong> (=not wearing any clothes on the top half of your body)</em></li><li><strong><em>slim-waisted/narrow-waisted/thick-waisted</strong> (=having a thin, thick etc waist)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[usually singular]</span> the part of a piece of clothing that goes around this part of your body</div></div>","7591":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /weɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[not go/start something]</strong> <span class=\"gram\">[intransitive]</span> to stay somewhere or not do something until something else happens, someone arrives etc: GRAMMAR• You wait for something or someone: · I waited for the next bus. ✗Don’t say: I waited the next bus.• You wait for someone to do something, or for something to happen: · She waited for him to finish speaking. ✗Don’t say: She waited him to finish speaking.</div><ul class=\"examples\"><li><em>Hurry up! Everyone’s waiting.</em></li><li><em>Would you mind waiting outside?</em></li><li><strong><em>wait for</strong>: a queue of people waiting for a bus / Wait for me!</em></li><li><strong><em>wait for somebody/something to do something</strong>: She paused, waiting for Myles to say something. / I sat waiting patiently for the wedding to end.</em></li><li><strong><em>wait until/till</strong>: I’ll wait till you come back.</em></li><li><strong><em>wait (for) three hours/two weeks etc</strong>: Can you wait for five minutes? / We’ve been waiting ages.</em></li><li><strong><em>wait to do something</strong>: Are you waiting to use the phone?</em></li><li><strong><em>keep somebody waiting</strong> (=make someone wait, especially by arriving late): I’m sorry to have kept you waiting.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[something has not happened]</strong> <span class=\"gram\">[intransitive]</span> if you are waiting for something that you expect or hope will happen or arrive, it has not happened or arrived yet:</div><ul class=\"examples\"><li><em>‘Have you heard about the job?’ ‘No, I’m still waiting.’</em></li><li><strong><em>wait for</strong>: I’m still waiting for my results.</em></li><li><strong><em>wait for somebody/something to do something</strong>: I’m waiting for him to realize how stupid he’s been.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>wait a minute/second/moment etc</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to ask someone not to leave or start doing something immediately:</div><ul class=\"examples\"><li><em>Wait a second, I’ll get my coat and come with you.</em></li><li><em>Wait a moment, just let me think.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to interrupt someone, especially because you do not agree with what they are saying:</div><ul class=\"examples\"><li><em>Wait a minute! That’s not what we agreed!</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> used when you suddenly think of, remember, or notice something:</div><ul class=\"examples\"><li><em>Wait a minute, I’ve got a better idea.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>somebody can’t wait/can hardly wait</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to emphasize that someone is very excited about something and is eager for it to happen:</div><ul class=\"examples\"><li><em>We’re going to Australia on Saturday – I can’t wait!</em></li><li><strong><em>can’t wait to do something</strong>: I can’t wait to tell Gloria the good news. / Laura could hardly wait to see the twins again.</em></li><li><strong><em>wait for</strong>: I can’t wait for the summer.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used humorously to say that something seems likely to be very boring:</div><ul class=\"examples\"><li><em>A lecture on transformational grammar? I can hardly wait!</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>something can/can’t wait</strong> if something can wait, it is not very urgent. If something can’t wait, it is very urgent:</div><ul class=\"examples\"><li><em>Go home. The report can wait till tomorrow.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>wait and see</strong> <em>spoken</em> used to say that someone should be patient because they will find out about something later:</div><ul class=\"examples\"><li><em>‘What’s for dinner?’ ‘Wait and see.’</em></li><li><em>We will just have to wait and see how things develop.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>wait until/till...</strong> <em>spoken</em> used when you are excited about telling or showing someone something:</div><ul class=\"examples\"><li><em>Wait till you see Gaby’s new house!</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>be waiting (for somebody)</strong> if something is waiting for you, it is ready for you to use, collect etc:</div><ul class=\"examples\"><li><em>There’ll be a rental car waiting for you at the airport.</em></li><li><em>Come round at eight and I’ll have dinner waiting.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>wait your turn</strong> to stay calm until it is your turn to do something, instead of trying to move ahead of other people:</div><ul class=\"examples\"><li><em>I’ve got two hands and there are three of you. So you’ll have to wait your turn!</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>something is (well) worth waiting for</strong> <em>spoken</em> used to say that something is very good, even though it takes a long time to come:</div><ul class=\"examples\"><li><em>Their new album was worth waiting for.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>(just) you wait</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>British English</em> used to warn or threaten someone:</div><ul class=\"examples\"><li><em>I’ll get you back for what you’ve done, just you wait.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to tell someone you are sure something will happen:</div><ul class=\"examples\"><li><em>It’ll be a huge success. Just you wait.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>what are you waiting for?</strong> <em>spoken</em> used to tell someone to do something immediately:</div><ul class=\"examples\"><li><em>Well, what are you waiting for? Go and apologize.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>what are we waiting for?</strong> <em>spoken</em> used to say in a cheerful way that you think everyone should start doing something immediately:</div><ul class=\"examples\"><li><em>What are we waiting for? Let’s go eat.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>wait for it</strong> <em>British English</em> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used just before you tell someone something that is funny or surprising:</div><ul class=\"examples\"><li><em>His name was – wait for it – Mr Bacon.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to tell someone not to do something until the correct time because they seem very impatient to do it now</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>be waiting in the wings</strong> to be ready to do something if it is necessary or if a suitable time comes:</div><ul class=\"examples\"><li><em>Other firms are waiting in the wings, ready to step in and make an offer should the current deal fall through.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>wait tables</strong> <em>American English</em> to work in a restaurant serving food and drink to people at their tables:</div><ul class=\"examples\"><li><em>I spent the summer waiting tables.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>(play) a/the waiting game</strong> if you play a waiting game, you try to gain an advantage for yourself in a particular situation by deliberately doing nothing until you have seen what other people do</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[singular]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a period of time in which you wait for something to happen, someone to arrive etc</div><ul class=\"examples\"><li><strong><em>wait for</strong>: The average wait for an appointment at the clinic was eight weeks.</em></li><li><strong><em>long/three-hour/two-week etc wait</strong>: There was an hour wait before the next train departed.</em></li><li><em>They’ll have a long wait.</em></li></ul></div></div>","7592":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wait‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈweɪtə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a man who serves food and drink at the tables in a restaurant</div></div>","7593":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wait‧ress</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈweɪtrɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a woman who serves food and drink at the tables in a restaurant</div></div>","7594":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /weɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span><span class=\"meta-item\">(past tense woke /wəʊk $ woʊk/, past participle woken /ˈwəʊkən $ ˈwoʊ-/)</span></div><div class=\"entry-body\"><div class=\"sense\">to stop sleeping, or to make someone stop sleeping:</div><ul class=\"examples\"><li><em>When she woke, the sun was streaming through the windows.</em></li><li><em>Try not to wake the baby.</em></li><li><strong><em>wake to</strong>: Nancy woke to the sound of birds outside her window (=she heard birds singing when she woke).</em></li></ul></div>","7595":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɔːk $ wɒːk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to move forward by putting one foot in front of the other:</div><ul class=\"examples\"><li><em>‘How did you get here?’ ‘We walked.’</em></li><li><em>Doctors said he’d never walk again.</em></li><li><strong><em>walk into/down/up etc</strong>: Carrie walked into the room and sat down in her chair. / He loved walking in the hills.</em></li><li><strong><em>walk a mile/200 metres/a short distance etc</strong>: We must have walked ten miles today. / I walked all the way to San Rafael.</em></li><li><strong><em>within (easy) walking distance (of something)</strong> (=near enough to be able to walk to): There are plenty of bars and restaurants within walking distance of the hotel.</em></li><li><strong><em>walking pace</strong> (=the speed that you normally walk at)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to walk somewhere with someone, especially in order to make sure that they are safe or to be polite:</div><ul class=\"examples\"><li><em>It’s late – I’ll walk you home.</em></li><li><strong><em>walk somebody to something</strong>: Schools are urging parents to walk their children to school. / She walked me to the front gate.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to take a dog for a walk for exercise:</div><ul class=\"examples\"><li><em>Grandma’s out walking the dog.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive]</span> <em>British English</em> <em>informal</em> if something has walked, it has disappeared and you think someone may have taken it:</div><ul class=\"examples\"><li><em>My pen seems to have walked.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>walk free</strong> (also walk<em>American English</em>) to leave a court of law without being punished or sent to prison:</div><ul class=\"examples\"><li><em>Ferguson walked free after the charges were dropped.</em></li><li><em>If more evidence isn’t found, Harris will walk.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>walk it</strong> <em>British English</em> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to make a journey by walking:</div><ul class=\"examples\"><li><em>If the last bus has gone, we’ll have to walk it.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to succeed or win something easily</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>be walking on air</strong> to be feeling extremely happy</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>walk the streets</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to walk around the streets in a town or city:</div><ul class=\"examples\"><li><em>It was not safe to walk the streets at night.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>old-fashioned</em> to be a prostitute</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>walk the beat</strong> when a police officer walks the beat, they walk around an area of a town or city in order to make sure nobody is committing a crime</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>walk tall</strong> to be proud and confident because you know that you have not done anything wrong</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>walk somebody off their feet</strong> <em>British English,</em> <strong>walk somebody’s legs off</strong> <em>American English</em> <em>informal</em> to make someone tired by making them walk too far</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>walk the walk</strong> to do the things that people expect or think are necessary in a particular situation: → talk the talk at talk1(18)</div><ul class=\"examples\"><li><em>People are motivated by leaders who actually walk the walk.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>walk the plank</strong> to be forced to walk along a board laid over the side of a ship until you fall off into the sea, used as a punishment in the past</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>walk on eggshells</strong> (also walk on eggs<em>American English</em>) to be very careful about how you behave with someone because they are easily upset or made angry</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a journey that you make by walking, especially for exercise or enjoyment:</div><ul class=\"examples\"><li><em>It’s a long walk. Maybe we should get the bus.</em></li><li><strong><em>walk to/through/across etc</strong>: a walk through the castle grounds</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a particular journey that you make by walking, especially one that goes through an interesting or attractive area:</div><ul class=\"examples\"><li><em>He says he’s going on a long walk tomorrow.</em></li><li><em>Have you ever done the Three Peaks walk?</em></li><li><strong><em>coastal/hill etc walk</strong>: There is a stunning 10-mile coastal walk from St Andrews to Crail.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> an organized event when people walk for pleasure:</div><ul class=\"examples\"><li><em>Let’s all go on the beach walk.</em></li><li><em>The local tourist office organises a number of guided walks.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[singular]</span> the way someone walks <em>SYN gait</em>:</div><ul class=\"examples\"><li><em>You can often recognize people by their walk.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[singular]</span> when you walk rather than run:</div><ul class=\"examples\"><li><em>Breathless, she slowed to a walk.</em></li></ul></div></div>","7596":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> walk‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɔːkə $ ˈwɒːkər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>especially British English</em> someone who walks for pleasure or exercise → hiker:</div><ul class=\"examples\"><li><em>The area is popular with walkers.</em></li><li><em>climbers and hill-walkers</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>a fast/slow etc walker</strong> someone who walks fast, slowly etc</div><div class=\"sense\"><span class=\"snum\">3</span> <em>especially American English</em> a metal frame on wheels that old or sick people use to help them walk SYN zimmer frame<em>British English</em></div><div class=\"sense\"><span class=\"snum\">4</span> a frame on wheels that a baby can sit in and move around using its legs, before it can walk SYN baby walker<em>British English</em></div></div>","7597":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɔːl $ wɒːl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[around an area]</strong> an upright flat structure made of stone or brick, that divides one area from another or surrounds an area → fence</div><ul class=\"examples\"><li><strong><em>stone/brick/concrete wall</strong>: The estate is surrounded by high stone walls.</em></li><li><strong><em>city/garden etc wall</strong>: the ancient city walls</em></li><li><em>the Great Wall of China</em></li><li><em>We climbed over the wall into the orchard.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[in a building]</strong> one of the sides of a room or building</div><ul class=\"examples\"><li><strong><em>on the wall</strong>: I put some pictures up on the walls.</em></li><li><em>Bob leaned against the wall.</em></li><li><strong><em>bedroom/kitchen etc wall</strong>: We decided to paint the bathroom walls blue.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[body]</strong> the side of something hollow, especially within the body:</div><ul class=\"examples\"><li><em>The walls of the blood vessels had been damaged.</em></li><li><em>cell walls</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>wall of fire/water etc</strong> a tall mass of something such as fire or water, that stops anything from getting past:</div><ul class=\"examples\"><li><em>The boat was hit by a wall of water.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>wall of silence/secrecy</strong> a situation in which nobody will tell you what you want to know:</div><ul class=\"examples\"><li><em>The police investigation was met with a wall of silence.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[Internet]</strong> an area on a website such as Facebook where other people can leave messages and comments about you</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>up the wall</strong> <em>spoken</em> very angry or annoyed:</div><ul class=\"examples\"><li><em>That noise is driving me up the wall (=making me annoyed).</em></li><li><strong><em>go up the wall<em>British English</em></strong>: I’ve got to be on time or Sarah will go up the wall.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>off the wall</strong> <em>informal</em> very strange or unusual, often in an amusing way:</div><ul class=\"examples\"><li><em>Some of Krista’s ideas are a little off the wall.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>go to the wall</strong> <em>informal</em> if a company goes to the wall, it fails, especially because of financial difficulties:</div><ul class=\"examples\"><li><em>Many small investors will go to the wall.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>these four walls</strong> <em>spoken</em> the room that you are in, especially considered as a private place:</div><ul class=\"examples\"><li><em>I don’t want anything repeated outside these four walls.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>be/come up against a (brick) wall</strong> to reach a point where you cannot make progress, especially because something or someone is stopping you:</div><ul class=\"examples\"><li><em>We seem to have come up against a brick wall in this investigation.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>be climbing/crawling (up) the walls</strong> <em>informal</em> to be feeling extremely anxious, unhappy, or annoyed, especially because you are waiting for something or are in a situation which you cannot get away from:</div><ul class=\"examples\"><li><em>The kids soon had him climbing the walls.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>walls have ears</strong> used to warn people to be careful what they say, because other people, especially enemies, could be listening</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>hit the wall</strong> <em>informal</em> to reach the point when you are most physically tired when doing a sport</div></div>","7598":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wal‧let</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɒlɪt $ ˈwɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a small flat case, often made of leather, that you carry in your pocket, for holding paper money, bank cards etc SYN billfold<em>American English</em> → purse</div><ul class=\"examples\"><li><strong><em>in your wallet</strong>: I’ve only got about £10 in my wallet.</em></li><li><em>He took a credit card out of his wallet.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> a case for documents, often made of leather or plastic</div></div>","7599":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wall‧pa‧per</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɔːlˌpeɪpə $ ˈwɒːlˌpeɪpər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> paper that you stick onto the walls of a room in order to decorate it</div><div class=\"sense\"><span class=\"snum\">2</span> the colour, pattern, or picture which you have as the background on the screen of a computer → desktop</div></div>","7600":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wan‧der</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɒndə $ ˈwɑːndər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[without direction]</strong> <span class=\"gram\">[intransitive, transitive]</span> to walk slowly across or around an area, usually without a clear direction or purpose ► see thesaurus at walk</div><ul class=\"examples\"><li><strong><em>wander in/through/around etc</strong>: I’ll wander around the mall for half an hour. / She wandered aimlessly about the house. / Ana wandered off to get a drink.</em></li><li><em>He was found wandering the streets of New York.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[move away]</strong> <span class=\"gram\">[intransitive]</span> (also wander off) to walk away from where you are supposed to stay:</div><ul class=\"examples\"><li><em>Don’t let any of the kids wander off.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[mind/thoughts]</strong> <span class=\"gram\">[intransitive]</span> if your mind, thoughts etc wander, you no longer pay attention to something, especially because you are bored or worried:</div><ul class=\"examples\"><li><em>Mrs Snell’s mind wandered and the voices went on and on.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[conversation]</strong> <span class=\"gram\">[intransitive]</span> to start to talk about something not related to the main subject that you were talking about before</div><ul class=\"examples\"><li><strong><em>wander from/off</strong>: Pauline started to wander from the point.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>somebody’s mind is wandering</strong> used to say that someone has become unable to think clearly, especially because they are old</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[eyes]</strong> <span class=\"gram\">[intransitive]</span> if your eyes or your gaze wander, you look around slowly at different things or at all parts of something:</div><ul class=\"examples\"><li><em>His gaze wandered round the room.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[road/river]</strong> <span class=\"gram\">[intransitive]</span> if a road or a river wanders somewhere, it does not go straight but in curves <em>SYN meander</em></div><ul class=\"examples\"><li><strong><em>wander through/across/along</strong>: The Missouri River wanders across several states.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[hands]</strong> <span class=\"gram\">[intransitive]</span> if a man’s hands wander, he touches the body of a woman he is with, especially where she does not want him to:</div><ul class=\"examples\"><li><em>Be careful, he’s got wandering hands.</em></li></ul></div>","7601":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɒnt $ wɒːnt, wɑːnt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[desire]</strong> <span class=\"gram\">[transitive]</span> to have a desire for something:</div><ul class=\"examples\"><li><em>I really want a drink.</em></li><li><em>What do you want for your birthday?</em></li><li><em>She’d always wanted to go to Thailand.</em></li><li><em>I don’t want Linda to hear about this.</em></li><li><em>He didn’t want the holiday to end.</em></li><li><em>You can order whatever you want.</em></li><li><em>This shampoo is mild enough to use every day if you want.</em></li><li><em>If she doesn’t get what she wants, she’s not happy.</em></li><li><em>He wanted that job so badly he was willing to kill for it.</em></li><li><em>They desperately wanted a son.</em></li><li><em>What I want to know is when we’re going to get paid.</em></li><li><em>All I want is the chance to prove myself.</em></li><li><em>Oh thank you, it’s just what I’ve always wanted.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[need]</strong> <span class=\"gram\">[transitive]</span> used to say that you need something or to ask someone firmly to do something for you:</div><ul class=\"examples\"><li><em>Do you still want these magazines, or can I throw them out?</em></li><li><strong><em>want something done</strong>: I want that letter typed today.</em></li><li><strong><em>want somebody to do something</strong>: I want you to find out what they’re planning.</em></li><li><strong><em>make you want to cry/throw up etc</strong> (=give you a strong feeling that you must do something): It always makes me want to sneeze.</em></li><li><em>What do you want with a tool kit (=what do you need it for)?</em></li><li><strong><em>want doing<em>British English</em></strong> </em>informal<em> (=need to be done): The carpet really wants cleaning.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[offer]</strong> <span class=\"gram\">[transitive]</span> used when offering or suggesting something to someone:</div><ul class=\"examples\"><li><em>Do you want a drink?</em></li><li><em>Do you want me to come with you?</em></li><li><em>Want a game of chess?</em></li><li><em>Who wants a cup of coffee (=used to offer something to a group of people)?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[should]</strong> <span class=\"gram\">[transitive]</span> <em>spoken especially</em> <em>British English</em> used to say that something is sensible or that someone should do it, especially when giving advice</div><ul class=\"examples\"><li><strong><em>may/might want to do something</strong>: You might want to install anti-virus software.</em></li><li><strong><em>wouldn’t want to do something</strong> (=used to say something would not be a good idea): I wouldn’t want to come here at night.</em></li><li><strong><em>want to do something</strong>: You want to see a doctor about that cough. / You don’t want to leave that – it’ll get wet.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>what do you want?</strong> used to ask, often in a slightly rude way, what someone wants you to give them, do for them etc:</div><ul class=\"examples\"><li><em>What do you want now? I’m busy.</em></li><li><em>What do you want – chocolate or vanilla?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[ask for somebody]</strong> <span class=\"gram\">[transitive]</span> to ask for someone to come and talk to you, or to come to a particular place:</div><ul class=\"examples\"><li><em>You’re wanted on the phone.</em></li><li><em>Christine wants you in her office now.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[lack]</strong> <span class=\"gram\">[intransitive, transitive]</span> <em>formal</em> to suffer because you do not have something:</div><ul class=\"examples\"><li><em>In many poorer countries, people still want basic food and shelter.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>if you want</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to offer to do something:</div><ul class=\"examples\"><li><em>I’ll come with you if you want.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to invite someone to do something or to give them permission:</div><ul class=\"examples\"><li><em>Join in if you want.</em></li><li><em>You can stay if you want to.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> used when someone suggests doing something, to say that you will do it, although you do not especially want to:</div><ul class=\"examples\"><li><em>‘Hey, shall we go to the beach?’ ‘If you want.’</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>who wants...?</strong> used to say that you do not like something or do not think that it is worth doing:</div><ul class=\"examples\"><li><em>Who wants to go to a noisy disco anyway?</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>I just wanted to say/know etc</strong> used to politely say something, ask about something etc:</div><ul class=\"examples\"><li><em>I just wanted to check that the meeting is still on next week.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>I don’t want to sound/be..., but...</strong> used to be polite when you are going to tell someone something that may upset them:</div><ul class=\"examples\"><li><em>I don’t want to sound rude, but I think you’ve had too much to drink.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[sex]</strong> <span class=\"gram\">[transitive]</span> <em>informal</em> if you want someone, you want to have sex with them</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>for (the) want of something</strong> used to say that you do not have or cannot find what you need in a particular situation:</div><ul class=\"examples\"><li><em>The gallery closed down for want of funding.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>for want of a better word/phrase etc</strong> used to say that you cannot find an exact word or phrase to describe something:</div><ul class=\"examples\"><li><em>They should behave, for want of a better word, decently.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>not for want of (doing) something</strong> used to say that even though something did not happen or succeed, it was not because you did not try hard enough or have what you needed:</div><ul class=\"examples\"><li><em>Well, if he doesn’t get the job it won’t be for want of trying!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>for want of anything better (to do)</strong> if you do something for want of anything better, you do it only because there is nothing else you want to do</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[lack]</strong> <span class=\"gram\">[countable, uncountable]</span> <em>formal</em> something that you need but do not have:</div><ul class=\"examples\"><li><em>a disgraceful want of proper care</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[no food/money etc]</strong> <span class=\"gram\">[uncountable]</span> a situation in which you do not have enough food, money, clothes etc:</div><ul class=\"examples\"><li><em>the chronic want and deprivation in the townships</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>be in want of something</strong> <em>formal</em> to need something:</div><ul class=\"examples\"><li><em>The house is sadly in want of repair.</em></li></ul></div></div>","7602":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> want‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɒntɪd $ ˈwɒːn-, ˈwɑːn-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who is wanted is being looked for by the police</div><ul class=\"examples\"><li><strong><em>wanted for</strong>: He is wanted for the murder of a teenage girl.</em></li><li><em>one of the most wanted men in China</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone, especially a child, who is wanted is loved and cared for</div></div>","7603":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɔː $ wɔːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> when there is fighting between two or more countries or between opposing groups within a country, involving large numbers of soldiers and weapons <em>OPP peace</em>:</div><ul class=\"examples\"><li><em>the Vietnam War</em></li><li><em>He served as a pilot during the war.</em></li><li><strong><em>war against/with/between</strong>: the war with Spain</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> a struggle over a long period of time to control something harmful</div><ul class=\"examples\"><li><strong><em>war on/against</strong>: the State’s war on drugs / the war against racism</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> a situation in which a person or group is fighting for power, influence, or control: → price war</div><ul class=\"examples\"><li><em>No one wants to start a trade war here.</em></li><li><em>a ratings war between the major TV networks</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be in the wars</strong> <em>British English</em> <em>spoken</em> used, often humorously, to say that someone has lots of injuries or health problems:</div><ul class=\"examples\"><li><em>You’ve really been in the wars lately, haven’t you?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>this means war</strong> <em>spoken</em> used humorously to say that you are ready to fight or argue about something</div></div>","7604":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɔːd $ wɔːrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a large room in a hospital where people who need medical treatment stay</div><ul class=\"examples\"><li><strong><em>maternity/general/geriatric etc ward</strong> (=a ward for people with a particular medical condition)</em></li><li><strong><em>on/in the ward</strong>: a young nurse&#x27;s first day on the wards / the other patients in the ward</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> one of the small areas that a city has been divided into for the purpose of local elections → constituency</div><div class=\"sense\"><span class=\"snum\">3</span> <em>law</em> someone, especially a child, who is under the legal protection of another person or of a law court:</div><ul class=\"examples\"><li><em>She was made a ward of court.</em></li></ul></div>","7605":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> war‧drobe</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɔːdrəʊb $ ˈwɔːrdroʊb/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> <em>British English</em> a piece of furniture like a large cupboard that you hang clothes in → closet:</div><ul class=\"examples\"><li><em>Can you hang these in the wardrobe, please?</em></li><li><strong><em>fitted/built-in wardrobes</strong> (=wardrobes built against a wall or fitted between two walls)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> the clothes that someone has: ► see thesaurus at clothes</div><ul class=\"examples\"><li><em>You can win a complete new wardrobe.</em></li><li><strong><em>winter/summer etc wardrobe</strong> (=the clothes you have for a particular time of year)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[singular]</span> (also wardrobe department) a department in a theatre, television company etc that deals with the clothes worn by actors</div></div>","7606":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ware‧house</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈweəhaʊs $ ˈwer-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a large building for storing large quantities of goods</div></div>","7607":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> war‧fare</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɔːfeə $ ˈwɔːrfer/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the activity of fighting in a war – used especially when talking about particular methods of fighting: ► see thesaurus at war</div><ul class=\"examples\"><li><em>the realities of modern warfare</em></li><li><strong><em>chemical/nuclear/germ etc warfare</em></strong></li><li><strong><em>trench/jungle/mountain etc warfare</em></strong></li><li><strong><em>guerrilla warfare</strong> (=fighting by small groups of fighters in mountains, forests etc)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a continuous and often violent struggle or argument between different groups</div><ul class=\"examples\"><li><strong><em>class/gang/internecine etc warfare</strong>: the problems of drugs and gang warfare</em></li></ul></div>","7608":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɔːm $ wɔːrm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[be warm]</strong> slightly hot, especially in a pleasant way <em>OPP cool</em> → warmth: ► see thesaurus at hot</div><ul class=\"examples\"><li><em>The house was lovely and warm.</em></li><li><em>I hope we get some warm weather soon.</em></li><li><em>I’ve put your dinner in the oven to keep it warm.</em></li><li><em>warm water</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[feel warm]</strong> if you are warm, your body is at a comfortable temperature:</div><ul class=\"examples\"><li><em>Are you warm enough?</em></li><li><strong><em>keep/stay warm</strong> (=wear enough clothes not to feel cold): Make sure you keep warm!</em></li><li><em>You’ll be as warm as toast in that sleeping bag.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[clothes/buildings]</strong> clothes or buildings that are warm can keep in heat or keep out cold:</div><ul class=\"examples\"><li><em>Here, put on your nice warm coat.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[friendly]</strong> friendly or making someone feel comfortable and relaxed: ► see thesaurus at friendly</div><ul class=\"examples\"><li><em>a warm, reassuring smile</em></li><li><em>Please give a warm welcome to our special guest.</em></li><li><em>a warm glow of satisfaction</em></li><li><em>The Hungarian people are warm and friendly.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[colour]</strong> warm colours contain the colours red, yellow, and orange, which make you feel comfortable and happy <em>OPP cool</em></div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[correct]</strong> <span class=\"gram\">[not before noun]</span> used especially in games to say that someone is near to guessing the correct answer or finding a hidden object <em>OPP cold</em>:</div><ul class=\"examples\"><li><em>You’re getting warmer.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to make someone or something warm or warmer, or to become warm or warmer:</div><ul class=\"examples\"><li><em>They gathered round the fire to warm their hands.</em></li><li><strong><em>warm yourself</strong>: Warm yourself by the fire.</em></li></ul></div></div>","7609":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> warm‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɔːmli $ ˈwɔːrm-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in a friendly way <em>OPP coldly</em>:</div><ul class=\"examples\"><li><em>Terry greeted the visitor warmly.</em></li><li><em>We were warmly welcomed by the villagers.</em></li><li><em>Jack smiled warmly.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in a way that makes something or someone warm:</div><ul class=\"examples\"><li><em>Pat wrapped the baby up warmly.</em></li><li><em>Make sure that the children are dressed warmly.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> in a way that shows that you like something very much:</div><ul class=\"examples\"><li><em>His speech was warmly received.</em></li></ul></div>","7610":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɔːmθ $ wɔːrmθ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the heat something produces, or when you feel warm</div><ul class=\"examples\"><li><strong><em>warmth of</strong>: the warmth of the summer sun</em></li><li><strong><em>for warmth</strong>: The children huddled closely together for warmth.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> friendliness and happiness</div><ul class=\"examples\"><li><strong><em>warmth of</strong>: the warmth of her smile</em></li></ul></div>","7611":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɔːn $ wɔːrn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to tell someone that something bad or dangerous may happen, so that they can avoid it or prevent it:</div><ul class=\"examples\"><li><em>‘Be careful, the rocks are slippery,’ Alex warned.</em></li><li><strong><em>warn somebody about something</strong>: Travellers to Africa are being warned about the danger of HIV infection.</em></li><li><strong><em>warn (somebody) of something</strong>: Salmon farmers are warning of the severe crisis facing the industry.</em></li><li><strong><em>warn somebody (not) to do something</strong>: I warned you not to walk home alone. / Motorists are being warned to avoid the centre of London this weekend.</em></li><li><strong><em>warn somebody (that)</strong>: We warned them that there was a bull in the field.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to tell someone about something before it happens so that they are not worried or surprised by it RegisterIn everyday English, people often use the expression let someone know rather than warn someone:· Let me know if you’re not going to finish on time.</div><ul class=\"examples\"><li><strong><em>warn somebody (that)</strong>: Warn her you’re going to be back late.</em></li></ul></div>","7612":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> warn‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɔːnɪŋ $ ˈwɔːrn-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> something, especially a statement, that tells you that something bad, dangerous, or annoying might happen so that you can be ready or avoid it</div><ul class=\"examples\"><li><strong><em>warning of</strong>: a warning of floods</em></li><li><strong><em>warning about</strong>: warnings about the dangers of smoking</em></li><li><strong><em>warning against</strong>: This experience should serve as a warning against complacency.</em></li><li><strong><em>warning to</strong>: a warning to pregnant women not to drink alcohol</em></li><li><em>a warning that grey squirrels are threatening the existence of red squirrels</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a statement telling someone that if they continue to behave in an unsatisfactory way, they will be punished:</div><ul class=\"examples\"><li><em>The Surrey team were given a warning last year for repeated offences.</em></li><li><em>I’m giving you a final warning – don’t be late again.</em></li><li><strong><em>written/verbal warning</em></strong></li></ul></div>","7613":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> war‧rant</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɒrənt $ ˈwɔː-, ˈwɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a legal document that is signed by a judge, allowing the police to take a particular action → death warrant, search warrant</div><ul class=\"examples\"><li><strong><em>warrant for</strong>: The magistrate issued a warrant for his arrest.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> an official document giving someone the right to do something, for example buy shares in a company:</div><ul class=\"examples\"><li><em>The company issued warrants for 300,000 shares.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>no warrant for (doing) something</strong> <em>formal</em> no good reason for doing something:</div><ul class=\"examples\"><li><em>There is no warrant for copying other people’s work.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to need or deserve:</div><ul class=\"examples\"><li><em>This tiny crowd does not warrant such a large police presence.</em></li><li><strong><em>warrant attention/consideration etc</strong>: Another area that warrants attention is that of funding for universities.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to promise that something is true</div><ul class=\"examples\"><li><strong><em>warrant that</strong>: The Author hereby warrants that the Publisher is the owner of the copyright.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>I’ll warrant (you)</strong> <em>old-fashioned</em> used to tell someone that you are sure about something</div><ul class=\"examples\"><li><strong><em>warrant (that)</strong>: I’ll warrant we won’t see him again.</em></li></ul></div></div>","7614":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> war‧ran‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɒrənti $ ˈwɔː-, ˈwɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural warranties)</span></div><div class=\"entry-body\"><div class=\"sense\">a written agreement in which a company selling something promises to repair it if it breaks within a particular period of time</div><ul class=\"examples\"><li><strong><em>under warranty</strong>: The car is still under warranty.</em></li><li><em>a three-year warranty</em></li></ul></div>","7615":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> war‧ri‧or</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɒriə $ ˈwɔːriər, ˈwɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a soldier or fighter who is brave and experienced – used about people in the past:</div><ul class=\"examples\"><li><em>a noble warrior</em></li></ul></div>","7616":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> war‧time</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɔːtaɪm $ ˈwɔːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the period of time when a country is fighting a war <em>OPP peacetime</em></div><ul class=\"examples\"><li><strong><em>in/during wartime</strong>: Even in wartime some people held concerts.</em></li></ul></div>","7617":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> war‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈweəri $ ˈweri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">someone who is wary is careful because they think something might be dangerous or harmful</div><ul class=\"examples\"><li><strong><em>be wary of (doing) something</strong>: I’m a bit wary of driving in this fog.</em></li><li><strong><em>wary of</strong>: We must teach children to be wary of strangers.</em></li><li><em>Keep a wary eye on the weather before you set sail.</em></li><li><em>She had a wary expression on her face.</em></li></ul></div>","7618":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɒʃ $ wɒːʃ, wɑːʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[wash something]</strong> <span class=\"gram\">[transitive]</span> to clean something using water and a type of soap: ► see thesaurus at clean</div><ul class=\"examples\"><li><em>This shirt needs washing.</em></li><li><em>It’s your turn to wash the dishes.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[wash yourself]</strong> <span class=\"gram\">[intransitive, transitive]</span> to clean your body with soap and water: RegisterIn everyday English, people usually say that someone has a wash (BrE) or washes up (AmE) rather than washes.</div><ul class=\"examples\"><li><em>Amy washed and went to bed.</em></li><li><em>She had a hot bath and washed her hair.</em></li><li><em>I’m just going to wash my hands.</em></li><li><strong><em>wash yourself</strong>: When a cat has finished eating, it often washes itself.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[flow]</strong> <span class=\"gram\">[intransitive, transitive always + adverb/preposition]</span> if a river, sea etc washes somewhere, or if something carried by the river or sea is washed somewhere, it flows or moves there:</div><ul class=\"examples\"><li><em>The waves washed against the shore.</em></li><li><em>The sea washed over her.</em></li><li><em>The young man was washed overboard (=pushed from a boat into the sea by the force of the water) in the storm.</em></li><li><em>The body was washed ashore (=brought to the shore by waves).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>something doesn’t/won’t wash (with somebody)</strong> <em>spoken</em> used to say that you do not believe or accept someone’s explanation, reason, attitude etc:</div><ul class=\"examples\"><li><em>I’m sorry but all his charm just doesn’t wash with me.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>wash your hands of something</strong> to refuse to be responsible for something anymore:</div><ul class=\"examples\"><li><em>I’ve washed my hands of the whole affair.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>wash your mouth out!</strong> <em>spoken</em> <em>old-fashioned</em> used to tell someone who has just sworn or said something rude that they should not have spoken that way</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>wash well</strong> to be easy to clean using soap and water:</div><ul class=\"examples\"><li><em>Silk doesn’t wash well.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[act of cleaning]</strong> <span class=\"gram\">[countable usually singular]</span> an act of cleaning something using soap and water:</div><ul class=\"examples\"><li><em>Those jeans need a good wash (=a thorough wash).</em></li><li><em>I’ll just have a quick wash before we go out.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[clothes]</strong> <span class=\"gram\">[singular, uncountable]</span> clothes that are to be washed, are being washed, or have just been washed:</div><ul class=\"examples\"><li><em>You’d better put that shirt in the wash.</em></li><li><em>Do you need me to put another wash on?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[skin]</strong> <span class=\"gram\">[countable]</span> a liquid used to clean your skin:</div><ul class=\"examples\"><li><em>an anti-bacterial facial wash</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[boat]</strong> <strong>the wash</strong> the movement of water caused by a passing boat:</div><ul class=\"examples\"><li><em>the wash of a large motorboat</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[colour]</strong> <span class=\"gram\">[countable]</span> a very thin transparent layer of paint or colour</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[area of land]</strong> <strong>the wash</strong> an area of land that is sometimes covered by the sea</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>it will all come out in the wash</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to tell someone not to worry about a problem because it will be solved in the future</div><div class=\"subsense\"><span class=\"subnum\">b)</span> used to say that the truth about something will be known in the end</div></div></div>","7619":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wash‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɒʃɪŋ $ ˈwɒː-, ˈwɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[singular, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>British English</em> clothes that need to be washed, are being washed, or have just been washed SYN wash<em>American English</em>:</div><ul class=\"examples\"><li><em>I really must do the washing (=wash the dirty clothes).</em></li><li><em>Could you put the washing out (=hang it on a washing line) for me?</em></li></ul></div>","7620":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈwashing maˌchine</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a machine for washing clothes</div></div>","7621":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈwashing ˌpowder</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>British English</em> soap in the form of a powder used for washing clothes</div></div>","7622":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌwashing-ˈup</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the washing of plates, dishes, knives etc:</div><ul class=\"examples\"><li><em>It’s your turn to do the washing-up, Sam.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the dirty pans, plates, dishes, knives etc that have to be washed SYN dishes<em>American English</em>:</div><ul class=\"examples\"><li><em>a pile of washing-up</em></li></ul></div>","7623":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌwashing-ˈup ˌliquid</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a liquid soap for washing plates, knives etc</div></div>","7624":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɒsp $ wɑːsp, wɒːsp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a thin black and yellow flying insect that can sting you</div></div>","7625":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /weɪst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[bad use]</strong> <span class=\"gram\">[singular, uncountable]</span> when something such as money or skills are not used in a way that is effective, useful, or sensible</div><ul class=\"examples\"><li><strong><em>waste of</strong>: Being unemployed is such a waste of your talents. / Many believe that state aid is a waste of taxpayers’ money.</em></li><li><em>What a waste of all that good work!</em></li><li><em>excessive waste in state spending</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>go to waste</strong> if something goes to waste, it is not used:</div><ul class=\"examples\"><li><em>Don’t let all this food go to waste.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be a waste of time/money/effort etc</strong> to be not worth the time, money etc that you use because there is little or no result:</div><ul class=\"examples\"><li><em>We should never have gone – it was a total waste of time.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[unwanted materials]</strong> <span class=\"gram\">[uncountable]</span> unwanted materials or substances that are left after you have used something: → nuclear waste, toxic waste</div><ul class=\"examples\"><li><em>The emphasis now is on recycling waste.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>a waste of space</strong> <em>spoken</em> someone who has no good qualities</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[land]</strong> <strong>wastes</strong> <span class=\"gram\">[plural]</span> <em>literary</em> a large area of land where there are very few people, plants, or animals</div><ul class=\"examples\"><li><strong><em>waste of</strong>: the icy wastes of Antarctica</em></li><li><strong><em>icy/frozen/snowy etc wastes</em></strong></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[not use sensibly]</strong> to use more money, time, energy etc than is useful or sensible:</div><ul class=\"examples\"><li><em>Leaving the heating on all the time wastes electricity.</em></li><li><strong><em>waste something on somebody/something</strong>: Don’t waste your money on that junk!</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[not use fully]</strong> to not make full use of someone or something: GRAMMAR Waste is usually passive in this meaning.</div><ul class=\"examples\"><li><em>Hannah is wasted in that clerical job.</em></li><li><em>His talents were being wasted as a lawyer.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be wasted on somebody</strong> if something is wasted on someone, they do not understand how good or useful it is:</div><ul class=\"examples\"><li><em>Her good advice was wasted on the children.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>waste your breath</strong> <em>spoken</em> to say something that has no effect:</div><ul class=\"examples\"><li><em>Don’t try to reason with Paul – you’re wasting your breath.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>waste no time (in) doing something</strong> to do something as quickly as you can because it will help you:</div><ul class=\"examples\"><li><em>He wasted no time in introducing himself.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>waste not, want not</strong> <em>spoken</em> used to say that if you use what you have carefully, you will still have some of it if you need it later</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[harm somebody]</strong> <em>American English</em> <em>informal</em> to kill someone, severely injure them, or defeat them</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> waste materials, substances etc are unwanted because the good part of them has been removed</div><div class=\"sense\"><span class=\"snum\">2</span> waste land is empty or not looked after by anyone</div></div></div>","7626":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> waste‧ful</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈweɪstfəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">using more of something than you should, especially money, time, or effort <em>OPP economical</em>:</div><ul class=\"examples\"><li><em>a wasteful use of resources</em></li><li><strong><em>wasteful of</strong>: The software is very wasteful of memory.</em></li></ul></div>","7627":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> waste‧pa‧per bas‧ket</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌweɪstˈpeɪpə ˌbɑːskət, ˈweɪstˌpeɪpə- $ ˈweɪstˌpeɪpər ˌbæ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a small container for holding paper, cans etc that are not wanted SYN wastebasket<em>American English</em></div></div>","7628":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɒtʃ $ wɑːtʃ, wɒːtʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[look]</strong> <span class=\"gram\">[intransitive, transitive]</span> to look at someone or something for a period of time, paying attention to what is happening:</div><ul class=\"examples\"><li><em>Do you mind if I watch?</em></li><li><em>We sat and watched the sunset.</em></li><li><strong><em>watch carefully/closely/intently etc</strong>: He watched helplessly as Paula fell into the icy water. / Watch carefully. You may learn something.</em></li><li><strong><em>watch (somebody/something) with interest/amusement/delight etc</strong>: Harriet watched him with interest.</em></li><li><strong><em>watch somebody/something do/doing something</strong>: I watched him go, then went home. / Ruth could not bear to watch her parents arguing.</em></li><li><strong><em>watch to do something</strong>: I watched to see how he’d react.</em></li><li><strong><em>watch television/a film etc</strong>: The debate was watched by 97 million viewers.</em></li><li><em>Most parents don’t know what their kids are watching on TV.</em></li><li><strong><em>watch what/how/when etc</strong>: It’s useful to watch how other pilots handle the glider.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[be careful]</strong> <span class=\"gram\">[transitive]</span> to act carefully in order to avoid an accident or unwanted situation</div><ul class=\"examples\"><li><strong><em>watch (that)</strong>: Watch he doesn’t run into the road.</em></li><li><em>She’s a student and has to watch her budget closely.</em></li><li><em>Watch your head on the shelf.</em></li><li><strong><em>watch what/how/where etc</strong>: Silly old fool! Why doesn’t he watch where he’s going? / Watch what you’re doing! It’s spilling everywhere!</em></li><li><em>Watch yourself (=be careful) in Madrid; there are some rough areas.</em></li><li><strong><em>watch what you say/your tongue/your language/your mouth etc</strong> (=be careful not to hurt or offend people by what you say): Employees should watch what they say in personal emails.</em></li><li><strong><em>watch your weight/watch what you eat</strong> (=be careful not to get fat): He may be a former athlete, but he still has to watch his weight.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[pay attention]</strong> <span class=\"gram\">[transitive]</span> to pay attention to a situation that interests or worries you to see how it develops</div><ul class=\"examples\"><li><strong><em>watch closely/carefully</strong>: American companies are watching Japanese developments closely.</em></li><li><em>The government will watch the progress of these schemes with interest.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[care for]</strong> <span class=\"gram\">[transitive]</span> to stay with someone or something so that nothing bad happens to them:</div><ul class=\"examples\"><li><em>She watches the kids for us occasionally.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[secretly]</strong> <span class=\"gram\">[transitive]</span> to secretly watch a person or place:</div><ul class=\"examples\"><li><em>I feel like I’m being watched.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>watch your step</strong> <em>informal</em> to be careful, especially about making someone angry:</div><ul class=\"examples\"><li><em>He soon saw he’d have to watch his step with some of these guys.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>watch your back</strong> <em>informal</em> to be careful because other people may try to harm you</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>watch the clock</strong> <em>informal</em> to keep looking at the time because you are worried or bored:</div><ul class=\"examples\"><li><em>anxious mums watching the clock</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>watch the time</strong> to make sure you know what time it is to avoid being late</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>watch it</strong> <em>spoken</em> used to warn someone to be careful:</div><ul class=\"examples\"><li><em>Watch it, there’s a car.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>watch this space</strong> <em>informal</em> used to tell people to pay attention in the future because things are going to develop further – used especially in newspapers</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>one to watch</strong> someone or something that people should pay attention to because they are interesting or exciting:</div><ul class=\"examples\"><li><em>In the tournament so far, Italy’s Stefania Croce looks like the one to watch.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>watch the world go by</strong> to relax outside by just looking at the people around you:</div><ul class=\"examples\"><li><em>lingering in a pavement café, watching the world go by</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>you watch</strong> <em>informal</em> used to tell someone that you know what will happen:</div><ul class=\"examples\"><li><em>He’ll win this time, you watch.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a small clock that you wear on your wrist or keep in your pocket:</div><ul class=\"examples\"><li><em>My watch has stopped.</em></li><li><strong><em>look at/glance at/consult your watch</strong>: She glanced nervously at her watch.</em></li><li><em>How do you keep track of time if you don’t wear a watch?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular, uncountable]</span> when you watch someone or something carefully, or pay careful attention to them, so that you are ready to act if necessary:</div><ul class=\"examples\"><li><em>The police arrived to keep watch on the mouth of the tunnel.</em></li><li><strong><em>watch on/over</strong>: He maintained a 24-hour watch over his son.</em></li><li><em>Security forces kept a close watch on our activities.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>keep a watch out for somebody/something</strong> (also be on the watch for somebody/something) to be looking and waiting for something that might happen or someone you might see, especially so that you can avoid danger, trouble etc:</div><ul class=\"examples\"><li><em>Be on the watch for anything suspicious.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> a group of people whose job is to guard or protect someone or something: → neighbourhood watch</div><ul class=\"examples\"><li><em>We were arrested and held until the arrival of the night watch (=people responsible for keeping the streets safe at night, especially in past times).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable, uncountable]</span> a period of time when it is someone’s duty to stay somewhere and look for signs of danger:</div><ul class=\"examples\"><li><em>The first watch is from now until midnight.</em></li><li><strong><em>on watch</strong>: Who’s on watch tonight?</em></li></ul></div></div>","7629":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wa‧ter</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɔːtə $ ˈwɒːtər, ˈwɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[liquid]</strong> the clear liquid without colour, smell, or taste that falls as rain and that is used for drinking, washing etc:</div><ul class=\"examples\"><li><em>There’s water all over the bathroom floor.</em></li><li><em>Does anyone want a drink of water?</em></li><li><em>a glass of sparkling mineral water</em></li><li><em>All rooms have hot and cold running water.</em></li><li><em>Pour boiling water over the rice and let it soak.</em></li><li><em>a fresh water spring</em></li><li><em>When dealing with a burst pipe, always turn off the water first.</em></li><li><em>contamination of the local water supply</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[area of water]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> an area of water such as the sea, a lake etc</div><ul class=\"examples\"><li><strong><em>shallow/deep water</em></strong></li><li><em>Rangoon is surrounded on three sides by water.</em></li><li><em>Denzil dived into the water.</em></li><li><em>He stepped down to the water’s edge.</em></li><li><strong><em>by water</strong> (=by boat): The temple can only be reached by water.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the surface of a lake, river etc → underwater</div><ul class=\"examples\"><li><strong><em>on the water</strong>: something floating on the water</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>waters</strong> <span class=\"gram\">[plural]</span> a large area of water, especially an ocean that is near or belongs to a particular country:</div><ul class=\"examples\"><li><em>the coastal waters of Alaska</em></li><li><strong><em>Korean/Mexican/Pacific etc waters</strong>: The ship drifted into Turkish territorial waters.</em></li><li><em>a species found in inland waters (=not the sea, but rivers, lakes etc)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>high/low water</strong> the highest or lowest level of the sea and some rivers <em>SYN tide</em></div><div class=\"sense\"><span class=\"snum\">5</span> <strong>uncharted/troubled/murky waters</strong> <em>formal</em> a situation that is difficult, dangerous, or unfamiliar:</div><ul class=\"examples\"><li><em>the uncharted waters of the 21st century</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be (all) water under the bridge</strong> <em>informal</em> used to say that what happened in the past should be forgotten</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>like water</strong> if you use something or spend money like water, you use or spend large amounts of it when you should try to save it – used to show disapproval:</div><ul class=\"examples\"><li><em>Some of the companies were spending money like water.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>like water off a duck’s back</strong> <em>informal</em> if criticism, warnings etc are like water off a duck’s back, they have no effect on the person you are saying them to</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>somebody’s waters break</strong> when a pregnant woman’s waters break, liquid comes from her body just before her baby is born</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>water on the brain/knee</strong> <em>old-fashioned</em> <em>informal</em> liquid around the brain or knee as the result of a disease</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>take the waters</strong> <em>old-fashioned</em> to wash yourself in or drink special water that is thought to make you healthy</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>make/pass water</strong> <em>formal</em> to urinate</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[plant/land]</strong> <span class=\"gram\">[transitive]</span> if you water plants or the ground they are growing in, you pour water on them:</div><ul class=\"examples\"><li><em>Will you water my houseplants while I’m away?</em></li><li><em>The garden needs watering daily.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>your eyes water</strong> if your eyes water, tears come out of them: → mouth-watering, → make your mouth water at mouth1(11)</div><ul class=\"examples\"><li><em>Chopping onions makes my eyes water.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[animal]</strong> <span class=\"gram\">[transitive]</span> to give an animal water to drink:</div><ul class=\"examples\"><li><em>Have the horses been fed and watered?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[river]</strong> <span class=\"gram\">[transitive]</span> <em>technical</em> if an area is watered by a river, the river flows through it and provides it with water: GRAMMAR Water is usually passive in this meaning.</div><ul class=\"examples\"><li><em>Colombia is watered by several rivers.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[weaken]</strong> <span class=\"gram\">[transitive]</span> (also water down) to add water to a drink to make it less strong</div></div></div>","7630":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wa‧ter‧fall</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɔːtəfɔːl $ ˈwɒːtərfɒːl, ˈwɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a place where water from a river or stream falls down over a cliff or rock</div></div>","7631":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɒt $ wɑːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a unit for measuring electrical power:</div><ul class=\"examples\"><li><em>a 100–watt bulb</em></li></ul></div>","7632":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /weɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[sea]</strong> <span class=\"gram\">[countable]</span> a line of raised water that moves across the surface of the sea: → tidal wave</div><ul class=\"examples\"><li><em>Dee watched the waves breaking on the shore.</em></li><li><em>The ship tipped over, and finally vanished beneath the waves.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[increase]</strong> <span class=\"gram\">[countable usually singular]</span> a sudden increase in a particular type of behaviour, activity, or feeling:</div><ul class=\"examples\"><li><em>There was a wave of public protest.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[people and things]</strong> <span class=\"gram\">[countable]</span> a sudden increase in the number of people or things arriving at the same time</div><ul class=\"examples\"><li><strong><em>wave of</strong>: a new wave of immigrants / They faced wave after wave of fresh troops.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[light and sound]</strong> <span class=\"gram\">[countable]</span> the form in which some types of energy such as light and sound travel → long wave, medium wave, short wave</div><ul class=\"examples\"><li><strong><em>sound/light/radio wave</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[signal]</strong> <span class=\"gram\">[countable usually singular]</span> a movement in which you raise your arm and move your hand from side to side:</div><ul class=\"examples\"><li><em>He dismissed her with a wave of the hand.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[feeling/activity]</strong> <span class=\"gram\">[countable]</span> a feeling or activity that happens again and again in a series:</div><ul class=\"examples\"><li><em>The pain swept over him in waves.</em></li><li><em>Wave after wave of aircraft passed overhead.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[hair]</strong> <span class=\"gram\">[countable usually plural]</span> a loose curl in your hair</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>make waves</strong> <em>informal</em> to cause problems, especially when you should not:</div><ul class=\"examples\"><li><em>With so many jobs already cut, he didn’t want to make waves.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>new wave</strong> a new style of music, art, film etc that is very different and unusual:</div><ul class=\"examples\"><li><em>new wave music</em></li><li><strong><em>wave of</strong>: the new wave of Black feminist theorists</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[crowd]</strong> <span class=\"gram\">[countable usually singular]</span> <em>American English</em> an occasion when many people who are watching an event stand up, move their arms up and down, and sit down again one after another in a continuous movement that looks like a wave moving on the sea SYN Mexican wave<em>British English</em></div><div class=\"sense\"><span class=\"snum\">11</span> <strong>the waves</strong> <em>literary</em> the sea</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[hand]</strong> <span class=\"gram\">[intransitive, transitive]</span> to raise your arm and move your hand from side to side in order to make someone notice you</div><ul class=\"examples\"><li><strong><em>wave to/at</strong>: She turned to wave to the approaching soldiers. / Enid waved at us and we waved back.</em></li><li><strong><em>wave (somebody) goodbye</strong> (=say goodbye to someone by waving to them): The nurses came out to wave Grandad goodbye.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[move]</strong> <span class=\"gram\">[intransitive, transitive]</span> if you wave something, or if it waves, it moves from side to side:</div><ul class=\"examples\"><li><em>The starter waved a green flag to indicate that the race would begin.</em></li><li><em>a tree waving in the breeze</em></li><li><em>He waved a hand in the air to attract her attention.</em></li><li><strong><em>wave something under/at etc somebody/something</strong>: Trudie waved a $50 bill under his nose.</em></li><li><strong><em>wave something around/about</strong>: The stranger spoke rapidly, waving his arms around.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[signal]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to show someone which way to go by waving your hand in that direction</div><ul class=\"examples\"><li><strong><em>wave somebody through/on/away etc</strong>: The border guards waved us through. / Peter waved them back to their seats.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>wave something goodbye/wave goodbye to something</strong> <em>informal</em> to be forced to accept that something you want will not happen:</div><ul class=\"examples\"><li><em>If you’re not careful, you can wave goodbye to any pay rise this year.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>wave a magic wand</strong> to make a bad situation better, even though this is impossible:</div><ul class=\"examples\"><li><em>I can’t wave a magic wand and change what happened.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[hair]</strong> <span class=\"gram\">[intransitive, transitive]</span> if hair waves, or if it is waved, it forms loose curls</div></div></div>","7633":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wave‧length</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈweɪvleŋθ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the size of a radio wave used to broadcast a radio signal</div><div class=\"sense\"><span class=\"snum\">2</span> <em>technical</em> the distance between two points on energy waves such as sound or light</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>be on the same/a different wavelength</strong> <em>informal</em> to have the same or different opinions and feelings as someone else:</div><ul class=\"examples\"><li><em>Dad is just on a different wavelength from me.</em></li></ul></div>","7634":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wæks/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a solid substance made of fat or oil and used to make candles, polish etc: → beeswax</div><ul class=\"examples\"><li><em>wax crayons</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a natural sticky substance in your ears</div></div>","7635":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /weɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[method]</strong> <span class=\"gram\">[countable]</span> a method that you use to do or achieve something: ► see thesaurus at method</div><ul class=\"examples\"><li><em>There are several different ways we can tackle this problem.</em></li><li><strong><em>way of doing something</strong>: Evening classes are one way of meeting new people. / There’s no way of knowing if the treatment will work.</em></li><li><strong><em>way to do something</strong>: What’s the best way to learn a language?</em></li><li><strong><em>in the same way/in various ways</strong>: Make the drink with boiling water in the same way as tea. / Animals communicate in various ways.</em></li><li><strong><em>(in) the right/wrong way</strong>: I think you’re going about this the wrong way.</em></li><li><strong><em>ways and means</strong> (=methods of doing something, especially ones that are secret or not yet decided): There are ways and means of raising the money that we need.</em></li><li><strong><em>way out/out of/around</strong>: One way around the problem (=method of dealing with it) is recycling. / There seems to be no way out of the current economic crisis.</em></li><li><strong><em>way into television/publishing/finance etc</strong> (=a method of getting involved in a particular activity or type of work): companies eager for a way into business in Europe</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[manner]</strong> <span class=\"gram\">[countable]</span> the manner or style in which someone does something or in which something happens:</div><ul class=\"examples\"><li><em>Look at the way he’s dressed!</em></li><li><strong><em>in a... way</strong>: ‘Hello,’ he said in a friendly way. / Maria got up and took a shower in a leisurely way.</em></li><li><strong><em>(in) this/that way</strong>: I find it easier to work in this way (=like this). / Sorry, I didn’t know you felt that way (=had that feeling or opinion).</em></li><li><em>The drugs didn’t seem to affect Anna in the same way.</em></li><li><strong><em>that’s no way to do something</strong> (=used to tell someone that they should not be doing something in a particular manner): That’s no way to speak to your father!</em></li><li><strong><em>in more ways than one</strong> (=in a number of ways): The changes will benefit the company in more ways than one.</em></li><li><strong><em>in somebody’s (own) way</strong> (=in a personal way that other people may not recognize): I’m sure he does love you, in his own way.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[direction/how to go somewhere]</strong> <span class=\"gram\">[countable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a road, path, direction etc that you take in order to get to a particular place</div><ul class=\"examples\"><li><strong><em>the way to/from/out etc</strong>: Which is the quickest way to the sea from here? / There are several ways through the woods.</em></li><li><strong><em>ask/tell/show somebody the way</strong>: Could you tell me the way to the station?</em></li><li><em>Does anyone know the way from here?</em></li><li><em>I was afraid of losing my way in the dark.</em></li><li><em>Can you find your way back to the car park?</em></li><li><strong><em>the way out</strong> (=the door, path etc which you can use to leave a building or area): Which is the way out?</em></li><li><strong><em>the way in</strong> (=the door, path etc which you can use to enter a building or area): She looked all around, but she couldn’t seem to find the way in.</em></li><li><strong><em>on somebody’s way</strong> (=in the same direction as someone is going): Want a lift? It’s on my way.</em></li><li><strong><em>out of somebody’s way</strong> (=not in the same direction as someone is going): I live miles out of your way.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a particular direction from where you are now:</div><ul class=\"examples\"><li><em>Which way is north?</em></li><li><em>Walk this way.</em></li><li><em>A big Mercedes was coming the other way (=from the opposite direction).</em></li><li><em>He left the house, looking carefully both ways.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[part of something that is true]</strong> <span class=\"gram\">[countable]</span> used to say that there is a fact or a feature of something that makes a statement or description true</div><ul class=\"examples\"><li><strong><em>in a/one way</strong>: In one way you’re right, I suppose.</em></li><li><strong><em>in some/many ways</strong>: Working at home makes sense, in many ways.</em></li><li><em>Ben is a perfectly normal child in every way.</em></li><li><em>He never got mad at me. He was great in that way.</em></li><li><strong><em>in no way</strong> (=used to emphasize that something is not true): This should in no way be seen as a defeat.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[distance/time]</strong> <span class=\"gram\">[singular]</span> a distance or a length of time, especially a long one:</div><ul class=\"examples\"><li><em>I was still a long way from home.</em></li><li><strong><em>some way/quite a way</strong> (=quite a long distance): She had to park some way from the restaurant.</em></li><li><strong><em>a long way off/away/ahead etc</strong> (=far away in distance or in time): A peace settlement now seems a long way off.</em></li><li><em>I don’t want to go all that way and not see him.</em></li><li><strong><em>all the way down/across/through etc (something)</strong> (=the full distance or length of something): Did you really swim all the way across? / I was awake all through the night.</em></li><li><strong><em>a (long) ways<em>American English</em></strong>: That’s quite a ways from here, isn’t it?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[the space in front of you]</strong> <span class=\"gram\">[countable usually singular]</span> if someone or something is in the way, they are blocking the space in front of you, and you cannot move forward</div><ul class=\"examples\"><li><strong><em>be in the way/be in somebody’s way</strong> (=be blocking a road, someone’s path etc so that they cannot move forward easily): There was a big truck in the way. / Sorry, am I in your way?</em></li><li><em>A policeman yelled at the crowds to get out of the way.</em></li><li><em>The way ahead was blocked.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>make way (for something/somebody)</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to move to the side so that there is space for someone or something to pass:</div><ul class=\"examples\"><li><em>The crowd stepped aside to make way for the procession.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to make it possible for something newer or better to be built, organized etc:</div><ul class=\"examples\"><li><em>Several houses were demolished to make way for a new road.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>out of the way</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> (also out of somebody’s way) if someone or something is out of the way, they are somewhere where they are not likely to cause a problem, need attention, be annoying etc</div><ul class=\"examples\"><li><strong><em>move/put/push etc something out of the way</strong>: Why don’t you tie your hair back, out of the way?</em></li><li><em>If Uncle Tom had been drinking, I kept out of his way.</em></li><li><em>When Mac was safely out of the way, Peter came round.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if a particular matter, job etc is out of the way, it has been done or dealt with:</div><ul class=\"examples\"><li><em>I’d rather get the interview out of the way in the morning.</em></li><li><em>As soon as the contract’s out of the way, we can start.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> a place that is out of the way is far from any towns</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>on the/your/its way</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> arriving or happening soon:</div><ul class=\"examples\"><li><em>There’s a letter on its way to you.</em></li><li><em>More changes are on the way.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> travelling towards a particular place:</div><ul class=\"examples\"><li><em>She should be on the way here by now.</em></li><li><strong><em>way to</strong>: The ships were already on their way to the gulf</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> while going from one place to another</div><ul class=\"examples\"><li><strong><em>way to/out/home etc</strong>: I ran out of gas on my way to the airport. / Guess who I bumped into on the way home.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">d)</span> (also along the way) while moving from one situation or part of your life to another:</div><ul class=\"examples\"><li><em>Don’s had to change jobs several times along the way.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">e)</span> if someone has a baby on the way, they are pregnant</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>be/get under way</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to have started to happen or be done:</div><ul class=\"examples\"><li><em>Plans are well under way for a new shopping centre.</em></li><li><em>The tournament got under way on Friday.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to have started to move or travel somewhere:</div><ul class=\"examples\"><li><em>Our train was already under way.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>make your way</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to go towards something, especially when this is difficult or takes a long time</div><ul class=\"examples\"><li><strong><em>way to/through/towards etc</strong>: The team slowly made their way back to base.</em></li><li><strong><em>make your own way (home/to something etc)</strong> (=go somewhere without the help or company of other people): Don’t worry. I can make my own way to the beach.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to gradually become successful in a particular job, activity, profession etc:</div><ul class=\"examples\"><li><em>young people who are making their way in industry</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>push/grope/inch etc your way somewhere</strong> to get somewhere by using force or moving carefully:</div><ul class=\"examples\"><li><em>She elbowed her way to the front of the queue.</em></li><li><em>He drank some water, then groped his way back to the bedroom.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>give way</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to be replaced by something else</div><ul class=\"examples\"><li><strong><em>way to</strong>: Stone has given way to glass and concrete. / My anger gave way to depression.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to agree to do what someone else wants, instead of what you want, especially after a lot of discussion or argument:</div><ul class=\"examples\"><li><em>Despite growing pressure, the Minister of State refused to give way.</em></li><li><strong><em>way to</strong>: Maria seemed to despise him for giving way to her.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> to break because of too much weight or pressure:</div><ul class=\"examples\"><li><em>The floor’s rotten and likely to give way.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">d)</span> <em>British English</em> to stop or slow down when you are driving, in order to allow other vehicles to go first SYN yield<em>American English</em>:</div><ul class=\"examples\"><li><em>In Britain, give way to cars coming from the right.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>clear/pave/open/prepare etc the way (for something)</strong> to make it possible for something to happen or develop later:</div><ul class=\"examples\"><li><em>a study that paved the way for further research</em></li><li><em>The Queen’s death opened the way for him to return.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>a/the way forward</strong> an action, plan etc that seems a good idea because it is likely to lead to success:</div><ul class=\"examples\"><li><em>A way forward lies in developing more economic links.</em></li><li><strong><em>way for</strong>: This treatment may be the way forward for many inherited disorders.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>[state/condition]</strong> <span class=\"gram\">[singular]</span> a particular state or condition:</div><ul class=\"examples\"><li><em>My family was in a bad way financially.</em></li><li><em>The chicken’s nice and crispy – just the way I like it.</em></li><li><em>It’s worth thinking how you can improve the way things are.</em></li><li><strong><em>somebody was born/made that way</strong> (=used to say that someone’s character is not likely to change): He’ll always be mean – he was born that way.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>[fact/event]</strong> <span class=\"gram\">[singular]</span> used to refer to something that happens:</div><ul class=\"examples\"><li><em>I hate the way you always give in to him.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>[behaviour]</strong> <span class=\"gram\">[countable]</span> someone’s typical style of behaving, especially when it seems different or unusual → see the error of your ways at error(6), → be set in your ways at set3(6)</div><ul class=\"examples\"><li><strong><em>be (just) somebody’s way</strong>: Don’t worry if she’s quiet – that’s just her way.</em></li><li><em>Esther quickly changed the subject, as was her way.</em></li><li><strong><em>strange/funny/odd etc ways</strong>: We all have our funny little ways.</em></li><li><strong><em>change/mend your ways</strong> (=stop behaving badly)</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>[development/progress]</strong> <span class=\"gram\">[singular]</span> used in expressions about developing and improving:</div><ul class=\"examples\"><li><em>The team has a long way to go (=needs to develop or improve a lot) before it can match that performance.</em></li><li><em>Microwave ovens have come a long way (=have developed or improved a lot) since they first appeared in our kitchens.</em></li><li><em>Jen is now well on the way to recovery (=she has improved and will be well soon).</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>go some way towards doing something</strong> also <strong>go a long way towards doing something</strong> to help a little or a lot to make something happen:</div><ul class=\"examples\"><li><em>ideas that go some way towards reducing environmental problems</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>[choices/possibilities]</strong> <span class=\"gram\">[countable]</span> used when talking about two choices someone could make, or two possibilities that could happen:</div><ul class=\"examples\"><li><em>I’m not sure which way he’ll decide.</em></li><li><em>The election could go either way (=both results are equally possible).</em></li><li><em>Make your mind up one way or the other.</em></li><li><strong><em>either way</strong> (=used to say that something will be the same, whichever of two things happens): Either way, it’s going to be expensive.</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>within two feet/ten years etc either way</strong> no more than two feet etc more or less than a particular amount:</div><ul class=\"examples\"><li><em>Your answer must be within a centimetre either way.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>(in) one way or another/one way or the other</strong> used to say that someone does or will do something somehow, although you are not sure how:</div><ul class=\"examples\"><li><em>One way or the other he always seems to win.</em></li><li><em>We’ll find the money, one way or another.</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>way around/round/up</strong> a particular order or position that something should be in:</div><ul class=\"examples\"><li><em>Which way around does this skirt go?</em></li><li><strong><em>the other way around/round/up</strong> (=in the opposite order or position): The picture should be the other way up. / Art reflects life, or is it the other way around (=is it ‘life reflects art’)?</em></li><li><strong><em>the right/wrong way around/round/up</strong>: Are the batteries in the wrong way round?</em></li></ul><div class=\"sense\"><span class=\"snum\">25</span> <strong>by way of something</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> (also in the way of something) as a form or means of something:</div><ul class=\"examples\"><li><em>I’d like to say something by way of introduction.</em></li><li><strong><em>little in the way of something</strong> (also<strong>not much/enough in the way of something)</strong> (=not much of something): The town has little in the way of leisure facilities.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if you travel by way of a place, you go through it <em>SYN via</em>:</div><ul class=\"examples\"><li><em>We went by way of London.</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> <strong>get in the way of something</strong> to prevent someone from doing something, or prevent something from happening:</div><ul class=\"examples\"><li><em>Your social life must not get in the way of your studies.</em></li></ul><div class=\"sense\"><span class=\"snum\">27</span> <strong>go out of your way to do something</strong> to do something with more effort than is usual or expected:</div><ul class=\"examples\"><li><em>She went out of her way to make me feel welcome.</em></li></ul><div class=\"sense\"><span class=\"snum\">28</span> <strong>get/have your (own) way</strong> to do what you want to, even though someone else wants something different:</div><ul class=\"examples\"><li><em>Don’t let the children always get their own way.</em></li></ul><div class=\"sense\"><span class=\"snum\">29</span> <strong>go your own way</strong> to do what you want, make your own decisions etc:</div><ul class=\"examples\"><li><em>At 18, most young people are ready to go their own way.</em></li></ul><div class=\"sense\"><span class=\"snum\">30</span> <strong>go somebody’s way</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if an event goes your way, it happens in the way you want:</div><ul class=\"examples\"><li><em>The government are hopeful that the vote will go their way.</em></li><li><strong><em>everything/nothing goes somebody’s way</strong> (=used to talk about events in general)</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>literary</em> to continue a journey, or to leave and do what you want to do next:</div><ul class=\"examples\"><li><em>She said goodbye and went her way.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> to travel in the same direction as someone:</div><ul class=\"examples\"><li><em>I can take you – I’m going your way.</em></li></ul><div class=\"sense\"><span class=\"snum\">31</span> <strong>come somebody’s way</strong> if something comes your way, you get or experience it, especially by chance:</div><ul class=\"examples\"><li><em>Luck had come her way at the very last moment.</em></li></ul><div class=\"sense\"><span class=\"snum\">32</span> <strong>in a big/small way</strong> used to talk about the degree to which something happens, or how important it is:</div><ul class=\"examples\"><li><em>The business was a success, in a small way.</em></li></ul><div class=\"sense\"><span class=\"snum\">33</span> <strong>by a long way</strong> by a large amount:</div><ul class=\"examples\"><li><em>He was the best in the group by a long way.</em></li></ul><div class=\"sense\"><span class=\"snum\">34</span> <strong>talk/buy etc your way into/past etc something/somebody</strong> to get where you want or achieve something you want by saying or doing something:</div><ul class=\"examples\"><li><em>Caroline managed to talk her way past the guard.</em></li></ul><div class=\"sense\"><span class=\"snum\">35</span> <strong>work/munch/smoke etc your way through something</strong> to deal with, eat, smoke etc a large amount of things:</div><ul class=\"examples\"><li><em>He worked his way through the pile of documents.</em></li><li><em>She had munched her way through a packet of biscuits.</em></li></ul><div class=\"sense\"><span class=\"snum\">36</span> <strong>be on the/your way out</strong> to be becoming less popular, important, powerful etc:</div><ul class=\"examples\"><li><em>Is the royal family on the way out?</em></li></ul><div class=\"sense\"><span class=\"snum\">37</span> <strong>across/over the way</strong> on the opposite side of the street:</div><ul class=\"examples\"><li><em>They live across the way from us at number 23.</em></li></ul><div class=\"sense\"><span class=\"snum\">38</span> <strong>have a way of doing something</strong> used to say that something often or usually happens:</div><ul class=\"examples\"><li><em>Cheer up – these problems have a way of working out.</em></li></ul><div class=\"sense\"><span class=\"snum\">39</span> <strong>get into the way of doing something</strong> <em>British English</em> to start to do something regularly:</div><ul class=\"examples\"><li><em>He’d got into the way of smoking first thing in the morning.</em></li></ul><div class=\"sense\"><span class=\"snum\">40</span> <strong>not in any way, shape, or form</strong> used to emphasize that something is not true:</div><ul class=\"examples\"><li><em>I am not responsible for his actions in any way, shape, or form.</em></li></ul><div class=\"sense\"><span class=\"snum\">41</span> <strong>split something two/three etc ways</strong> (also divide something two/three etc ways) to divide something into two, three etc equal parts:</div><ul class=\"examples\"><li><em>We’ll split the cost between us five ways.</em></li></ul><div class=\"sense\"><span class=\"snum\">42</span> <strong>have a way with somebody/something</strong> to be especially good at dealing with people or things of a particular type:</div><ul class=\"examples\"><li><em>David seems to have a way with children.</em></li><li><em>She’s always had a way with words (=been good at using words effectively).</em></li></ul><div class=\"sense\"><span class=\"snum\">43</span> <strong>the way of the world</strong> how things always happen or are done, especially when this is not easy to change:</div><ul class=\"examples\"><li><em>In those days these policies favoured men. That was the way of the world.</em></li></ul><div class=\"sense\"><span class=\"snum\">44</span> <strong>every which way</strong> <em>informal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> in all directions:</div><ul class=\"examples\"><li><em>Bullets were flying every which way.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>British English</em> every possible method:</div><ul class=\"examples\"><li><em>I tried every which way to avoid it.</em></li></ul><div class=\"sense\"><span class=\"snum\">45</span> <strong>Way</strong> used in the names of roads:</div><ul class=\"examples\"><li><em>Church Way</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> very far</div><ul class=\"examples\"><li><strong><em>way ahead/behind/out etc</strong>: The other cyclists were way behind. / She lives way out of town.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> by a large amount</div><ul class=\"examples\"><li><strong><em>way above/below/past etc</strong>: Her IQ is way above average.</em></li><li><strong><em>way out</strong>: Your guess was way out (=completely incorrect), he’s actually thirty-eight.</em></li><li><strong><em>way back</strong>: We first met way back (=a long time ago) in the seventies.</em></li><li><strong><em>way heavier/smarter/bigger etc</strong> (=much heavier etc): The tickets were way more expensive than I thought.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>American English</em> <em>informal</em> very:</div><ul class=\"examples\"><li><em>I think she’s way cool, man.</em></li></ul></div></div>","7636":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌway of ˈlife</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural ways of life)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the behaviour, habits, customs etc that are typical of a particular society or person:</div><ul class=\"examples\"><li><em>The tribe’s traditional way of life is under threat.</em></li><li><strong><em>the American/British etc way of life</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a job or interest that is so important that it affects everything you do:</div><ul class=\"examples\"><li><em>For Mark, travelling has become a way of life.</em></li></ul></div>","7637":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wi; strong wiː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[used as the subject of a verb]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used by the person speaking or writing to refer to himself or herself and one or more other people:</div><ul class=\"examples\"><li><em>‘Did you go into the supermarket?’ ‘No, we didn’t.’</em></li><li><em>Shall we stop for a coffee?</em></li><li><em>So we all travelled down to Brighton together.</em></li><li><em>We declare our support for a government of national unity.</em></li><li><em>We Italians are proud of our history.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used by a writer or speaker to include themselves and their readers or listeners:</div><ul class=\"examples\"><li><em>As we saw in Chapter 4, slavery was not the only cause of the Civil War.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> people in general:</div><ul class=\"examples\"><li><em>We live on a complex planet.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>formal</em> used by a king or queen to refer to himself or herself</div><div class=\"sense\"><span class=\"snum\">5</span> <em>spoken</em> sometimes used to mean ‘you’ when speaking to children or people who are ill:</div><ul class=\"examples\"><li><em>How are we feeling today, Mr Robson?</em></li></ul></div>","7638":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wiːk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[physical]</strong> not physically strong:</div><ul class=\"examples\"><li><em>The illness left her feeling weak.</em></li><li><em>Poor light produces weak plants.</em></li><li><strong><em>be too weak to do something</strong>: She’s too weak to feed herself.</em></li><li><strong><em>weak with/from</strong>: Nina was weak with hunger. / The animal was weak from loss of blood.</em></li><li><strong><em>weak heart/lungs etc</strong>: My grandfather had a weak heart.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[likely to break]</strong> unable to support much weight:</div><ul class=\"examples\"><li><em>a weak bridge</em></li><li><strong><em>too weak to do something</strong>: The branch was too weak to support his weight.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[character]</strong> easily influenced by other people – used to show disapproval:</div><ul class=\"examples\"><li><em>a weak indecisive man</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[without power]</strong> not having much power or influence</div><ul class=\"examples\"><li><strong><em>weak leader/ruler/king etc</strong>: a weak and ineffective president</em></li><li><em>The party was left weak and divided.</em></li><li><em>The country is in a weak position economically.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[without interest]</strong> without the power to interest or amuse people:</div><ul class=\"examples\"><li><em>The play is well acted but the plot is weak.</em></li><li><em>a weak joke</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[without energy]</strong> done without energy or confidence:</div><ul class=\"examples\"><li><em>He managed a weak smile.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[not good at doing something]</strong> not good at a particular skill or subject, or in a particular area of activity or knowledge</div><ul class=\"examples\"><li><strong><em>weak in</strong>: New Zealand was weak in defence.</em></li><li><strong><em>weak on</strong>: She speaks quite fluently but she’s weak on grammar.</em></li><li><em>Be honest about your weak points (=your faults or the things you do not do well).</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[money]</strong> not financially successful</div><ul class=\"examples\"><li><strong><em>weak currency/economy etc</strong>: The pound was weak against the dollar.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[argument/idea]</strong> not likely to make people believe that something is true or right:</div><ul class=\"examples\"><li><em>She’s washing her hair? That sounds like a weak excuse!</em></li><li><em>There are some weak points in her argument.</em></li><li><em>The defence lawyer clearly knew that his case was weak.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[drink]</strong> weak tea, beer etc contains a lot of water and has little taste <em>OPP strong</em></div><div class=\"sense\"><span class=\"snum\">11</span> <strong>[light/sound]</strong> difficult to see or hear <em>SYN faint</em>:</div><ul class=\"examples\"><li><em>a weak radio signal</em></li><li><em>He had only a weak light to see by.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>weak points/spots</strong> the parts of something that can easily be attacked or criticized:</div><ul class=\"examples\"><li><em>Check your house for weak spots where a thief could enter.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>weak at the knees</strong> feeling strange because of strong emotions:</div><ul class=\"examples\"><li><em>His smile made her go weak at the knees.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>weak moment</strong> a time when you can be persuaded more easily than usual:</div><ul class=\"examples\"><li><em>Dave caught me at a weak moment and I lent him £10.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>the weak/weakest link</strong> the person or thing in a situation that is less strong, skilful etc than the others:</div><ul class=\"examples\"><li><em>Goalkeeper Gouter proved to be the weakest link.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>weak verb</strong> <em>technical</em> a verb that forms regular past tenses <em>OPP strong verb</em></div><div class=\"sense\"><span class=\"snum\">17</span> <strong>weak consonant/syllable</strong> one that is not emphasized</div></div>","7639":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> weak‧en</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwiːkən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make someone or something less powerful or less important, or to become less powerful <em>OPP strengthen</em>:</div><ul class=\"examples\"><li><em>Over the last two years the president’s position has weakened.</em></li><li><em>Changes in policy have weakened the power of the trade unions.</em></li><li><em>The absence of this witness has weakened the case against the accused.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make someone lose their physical strength, or to become physically weak:</div><ul class=\"examples\"><li><em>Julia was weakened by her long illness.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to make someone less determined, or to become less determined:</div><ul class=\"examples\"><li><em>Such policies weaken the resolve of potential troublemakers.</em></li><li><em>When she begged him to let her stay, he weakened.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> to make a building, structure etc less strong, or to become less strong:</div><ul class=\"examples\"><li><em>The earthquake in Cairo weakened a number of structures.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> if a particular country’s money or a company’s share prices weaken, or if they are weakened, their value is reduced</div><ul class=\"examples\"><li><strong><em>weaken against</strong>: The pound has weakened against the dollar.</em></li></ul></div>","7640":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> weak‧ness</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwiːknəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[fault]</strong> <span class=\"gram\">[countable]</span> a fault in someone’s character or in a system, organization, design etc: ► see thesaurus at fault</div><ul class=\"examples\"><li><em>The legislation has a fundamental weakness.</em></li><li><em>The plan has strengths and weaknesses.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[lack of power]</strong> <span class=\"gram\">[uncountable]</span> lack of strength, power, or influence</div><ul class=\"examples\"><li><strong><em>weakness in</strong>: weakness in the economy</em></li><li><strong><em>weakness of</strong>: the growing weakness of local government</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[body]</strong> <span class=\"gram\">[uncountable]</span> the state of being physically weak:</div><ul class=\"examples\"><li><em>muscular weakness</em></li><li><strong><em>weakness in</strong>: weakness in the right arm</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[character]</strong> <span class=\"gram\">[uncountable]</span> lack of determination shown in someone’s behaviour:</div><ul class=\"examples\"><li><em>He couldn’t explain his weakness in giving in to her demands.</em></li><li><em>I dared not cry or show any sign of weakness.</em></li><li><strong><em>weakness of</strong>: his weakness of character</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[money]</strong> <span class=\"gram\">[uncountable]</span> the condition of not being worth a lot of money</div><ul class=\"examples\"><li><strong><em>weakness of</strong>: the weakness of the pound against the dollar</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>a weakness for something</strong> if you have a weakness for something, you like it very much even though it may not be good for you:</div><ul class=\"examples\"><li><em>I have a real weakness for fashionable clothes.</em></li></ul></div>","7641":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /welθ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> a large amount of money, property etc that a person or country owns:</div><ul class=\"examples\"><li><em>The country’s wealth comes from its oil.</em></li><li><em>the distribution of wealth (=the way wealth is divided among the people of a country or society)</em></li><li><em>The purpose of industry is to create wealth.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>a wealth of something</strong> a lot of something useful or good:</div><ul class=\"examples\"><li><em>There is a wealth of information available about pregnancy and birth.</em></li></ul></div>","7642":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wealth‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwelθi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(comparative wealthier, superlative wealthiest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> having a lot of money, possessions etc <em>SYN rich</em> ► see thesaurus at rich</div><ul class=\"examples\"><li><strong><em>very/extremely/immensely/fabulously etc wealthy</strong>: He left as a poor, working class boy and returned as a wealthy man.</em></li><li><em>the wealthy nations of the world</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the wealthy</strong> <span class=\"gram\">[plural]</span> people who have a lot of money, possessions etc</div></div>","7643":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> weap‧on</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwepən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> something that you use to fight with or attack someone with, such as a knife, bomb, or gun:</div><ul class=\"examples\"><li><em>They all had sticks which they planned to use as weapons.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an action, piece of information, piece of equipment etc that you can use to win or be successful in doing something:</div><ul class=\"examples\"><li><em>a new weapon in the fight against AIDS</em></li><li><em>Right now, she felt the need of every weapon in her armoury (=weapon that she had), including surprise.</em></li></ul></div>","7644":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /weə $ wer/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense wore /wɔː $ wɔːr/, past participle worn /wɔːn $ wɔːrn/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[on your body]</strong> <span class=\"gram\">[transitive]</span> to have something such as clothes, shoes, or jewellery on your body: ► see thesaurus at dress RegisterIn everyday English, people often say that someone has something on rather than is wearing something:· She had on a black silk dress.</div><ul class=\"examples\"><li><em>Susanna was wearing a black silk dress.</em></li><li><em>He wore glasses for reading.</em></li><li><strong><em>wear a seat belt</strong> (=have it around yourself)</em></li><li><strong><em>wear black/white/red etc</strong>: Usually I wear black, grey, or brown.</em></li><li><strong><em>wear something to a party/a dance/an interview etc</strong>: I’m wearing a scarlet dress to the party.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[hair]</strong> <span class=\"gram\">[transitive]</span> to have your hair or beard in a particular style or shape:</div><ul class=\"examples\"><li><em>She wore her hair loose.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[damage]</strong> <span class=\"gram\">[intransitive, transitive]</span> to become thinner or weaker after continuous use, or to make something do this:</div><ul class=\"examples\"><li><em>The cushions are starting to wear a little.</em></li><li><em>His jeans have worn thin at the knees.</em></li><li><em>You’ve worn a hole in your sock.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>wear well</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to remain in good condition after a period of time:</div><ul class=\"examples\"><li><em>The tyres on the car seem to be wearing well.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if someone is wearing well, they look younger than they really are:</div><ul class=\"examples\"><li><em>He must have been around his mid-forties at least, but he’d worn well.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[expression]</strong> <span class=\"gram\">[transitive]</span> to have a particular expression on your face</div><ul class=\"examples\"><li><strong><em>wear a smile/frown/grin etc</strong>: His face wore a welcoming smile.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>something is wearing thin</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if something is wearing thin, you are bored with it because it is not interesting anymore, or has become annoying:</div><ul class=\"examples\"><li><em>The film begins well but the joke wears thin after about ten minutes.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if your patience is wearing thin, you have very little left, because of a delay or problem</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>wear the trousers</strong> <em>British English</em>, wear the pants<em>American English</em> <em>informal</em> to be the person in a family who makes the decisions</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>wear your heart on your sleeve</strong> <em>informal</em> to show your true feelings openly</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the clothes worn for a particular occasion or activity, or by a particular group of people → footwear, menswear ► see thesaurus at clothes</div><ul class=\"examples\"><li><strong><em>evening/casual/leisure etc wear</strong>: a new range of casual wear / bridal wear</em></li><li><em>the children’s wear department</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> damage caused by continuous use over a long period:</div><ul class=\"examples\"><li><em>Replace your trainers when they start to show signs of wear.</em></li><li><em>Check the equipment for wear and tear.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the amount of use an object, piece of clothing etc has had, or the use you can expect to get from it:</div><ul class=\"examples\"><li><em>The dress stood up to the wear small children give their clothes.</em></li><li><em>You’ll get years of wear out of that coat.</em></li></ul></div></div>","7645":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wear‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪəri $ ˈwɪr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> very tired or bored, especially because you have been doing something for a long time: ► see thesaurus at tired RegisterIn everyday English, people usually say tired rather than weary:· They were tired after their journey.</div><ul class=\"examples\"><li><em>She found Rachel in the kitchen, looking old and weary.</em></li><li><em>She sat down with a weary sigh.</em></li><li><strong><em>weary of (doing) something</strong>: He was weary of the constant battle between them.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>especially literary</em> very tiring:</div><ul class=\"examples\"><li><em>a long and weary march</em></li></ul></div>","7646":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> weath‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈweðə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[singular, uncountable]</span> the temperature and other conditions such as sun, rain, and wind: GRAMMAR• You often say the weather: · The weather seems to be getting worse.• You also often use weather with an adjective such as good or bad: · We had good weather all week.· Games are sometimes cancelled because of bad weather.• Don’t use weather with ‘a’. ✗Don’t say: We had a good weather.Grammar guide ‒ NOUNS</div><ul class=\"examples\"><li><em>What’s the weather like today?</em></li><li><em>The weather turned bitterly cold.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the weather</strong> <em>informal</em> a description on radio or television, in newspapers etc of what the weather will be like in the near future <em>SYN the weather forecast</em>:</div><ul class=\"examples\"><li><em>I always watch the weather after the news.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in all weathers</strong> in all types of weather, even when it is very hot or cold:</div><ul class=\"examples\"><li><em>There are homeless people sleeping on the streets in all weathers.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>under the weather</strong> <em>informal</em> slightly ill:</div><ul class=\"examples\"><li><em>You look a bit under the weather.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>keep a weather eye on something</strong> to watch a situation carefully so that you notice anything unusual or unpleasant:</div><ul class=\"examples\"><li><em>Keep a weather eye on your finances.</em></li></ul></div>","7647":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wiːv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(past tense wove /wəʊv $ woʊv/, past participle woven /ˈwəʊvən $ ˈwoʊ-/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[cloth etc]</strong> <span class=\"gram\">[intransitive, transitive]</span> to make cloth, a carpet, a basket etc by crossing threads or thin pieces under and over each other by hand or on a loom:</div><ul class=\"examples\"><li><em>hand-woven scarves</em></li><li><em>Only a few of the women still weave.</em></li><li><em>traditional basket weaving</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[story]</strong> <span class=\"gram\">[transitive]</span> to put many different ideas, subjects, stories etc together and connect them smoothly:</div><ul class=\"examples\"><li><em>She weaves a complicated plot of romance and intrigue.</em></li><li><strong><em>weave something together</strong>: the complex patterns which evolve when individuals’ lives are woven together</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>weave your magic/weave a spell</strong> to attract or interest someone very much</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[move]</strong> (past tense and past participle weaved) <span class=\"gram\">[intransitive always + adverb/preposition, transitive]</span> to move somewhere by turning and changing direction a lot:</div><ul class=\"examples\"><li><em>cyclists weaving in and out of the traffic</em></li><li><strong><em>weave your way through/to etc something</strong>: Lori spotted them as they weaved their way through the tables.</em></li></ul></div>","7648":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /web/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[singular]</span> <strong>the Web</strong> the system on the Internet that allows you to find and use information that is held on computers all over the world <em>SYN the World Wide Web</em> GRAMMAR Don’t say: in the Web/on Web</div><ul class=\"examples\"><li><strong><em>on the Web</strong>: a guide to the best education-related sites on the Web</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a net of thin threads made by a spider to catch insects: → cobweb</div><ul class=\"examples\"><li><em>He watched a spider spinning its web.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable usually singular]</span> a closely related set of things that can be very complicated</div><ul class=\"examples\"><li><strong><em>a web of intrigue/deceit/deception/lies etc</em></strong></li><li><em>a tangled web of relationships</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> a piece of skin that connects the toes of ducks and some other birds, and helps them to swim well</div></div>","7649":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> web‧page</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwebpeɪdʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">all the information that you can see in one part of a website</div></div>","7650":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> web‧site</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwebsaɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a place on the Internet where you can find information about something, especially a particular organization:</div><ul class=\"examples\"><li><em>For more information on weight loss and healthy eating, visit our website.</em></li><li><strong><em>on a website</strong>: Responses will be posted (=put) on the website.</em></li></ul></div>","7651":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wed‧ding</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwedɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a marriage ceremony, especially one with a religious service:</div><ul class=\"examples\"><li><em>She’s busy planning her daughter’s wedding.</em></li><li><em>When is the wedding?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>(hear the sound of) wedding bells</strong> <em>spoken</em> used to say that you think it is likely that two people will get married</div></div>","7652":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wedʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a piece of wood, metal etc that has one thick edge and one pointed edge and is used especially for keeping a door open or for splitting wood</div><div class=\"sense\"><span class=\"snum\">2</span> a piece of food shaped like a wedge:</div><ul class=\"examples\"><li><em>Garnish with lemon wedges.</em></li><li><strong><em>wedge of</strong>: a wedge of cheese</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>wedges</strong> <span class=\"gram\">[plural]</span> wedge heels</div></div>","7653":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> Wednes‧day</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwenzdi, -deɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the day between Tuesday and Thursday</div><ul class=\"examples\"><li><strong><em>on Wednesday</strong>: The sale starts on Wednesday.</em></li><li><em>We can go Wednesday. </em>American English**</li><li><strong><em>Wednesday morning/afternoon etc</strong>: I saw Vicky on Wednesday evening.</em></li><li><strong><em>last Wednesday</strong>: They left last Wednesday.</em></li><li><strong><em>this Wednesday</strong>: Come down this Wednesday.</em></li><li><strong><em>next Wednesday</strong> (=Wednesday of next week): I can let you know next Wednesday.</em></li><li><strong><em>a Wednesday</strong> (=one of the Wednesdays in the year): ‘Are you free on the 19th?’ ‘Is that a Wednesday?’</em></li></ul></div>","7654":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wiːd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a wild plant growing where it is not wanted that prevents crops or garden flowers from growing properly:</div><ul class=\"examples\"><li><em>the constant battle against weeds</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> a plant without flowers that grows on water in a large green floating mass → seaweed</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> <em>British English</em> <em>informal</em> someone who is weak:</div><ul class=\"examples\"><li><em>Nigel’s such a weed, isn’t he?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>like weeds</strong> in large numbers:</div><ul class=\"examples\"><li><em>Cars clogged the roads like weeds.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>the weed</strong> <em>informal</em> cigarettes or tobacco</div><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[uncountable]</span> cannabis</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>(widow’s) weeds</strong> <em>old use</em> black clothes worn by a woman whose husband has died</div></div>","7655":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wiːk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a period of seven days and nights, usually measured in Britain from Monday to Sunday and in the US from Sunday to Saturday</div><ul class=\"examples\"><li><strong><em>once/twice/three times etc a week</strong>: Letters were delivered twice a week only.</em></li><li><em>I can’t see you this week.</em></li><li><strong><em>last/next week</strong> (=the week before or after this one): See you next week.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> any period of seven days and nights</div><ul class=\"examples\"><li><strong><em>for a week/two weeks etc</strong>: I’ve been living here for six weeks.</em></li><li><strong><em>in a week/two weeks etc</strong> (=one, two etc weeks from now): If he hasn’t phoned in a week, I’ll phone him.</em></li><li><em>It will cost you an estimated £10 per week to feed one dog.</em></li><li><em>The training program lasts three weeks.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the part of the week when you go to work, usually from Monday to Friday <em>SYN working week</em>:</div><ul class=\"examples\"><li><em>a 35-hour week</em></li><li><strong><em>during the week</strong>: I don’t see her during the week.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>Monday week/Tuesday week etc</strong> <em>British English</em> a week after the day that is mentioned:</div><ul class=\"examples\"><li><em>We’re off to Spain Sunday week.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>a week on Monday etc</strong> <em>British English</em>, a week from Monday etc<em>American English</em> a week after the day that is mentioned:</div><ul class=\"examples\"><li><em>The Reids are coming for dinner a week from Sunday.</em></li><li><em>Keith’s coming home two weeks on Saturday (=two weeks after next Saturday).</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>week after week</strong> (also week in week out) continuously for many weeks:</div><ul class=\"examples\"><li><em>We do the same things week in week out.</em></li></ul></div>","7656":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> week‧end</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌwiːkˈend◂ ˈwiːkend $ ˈwiːkend/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">Saturday and Sunday, especially considered as time when you do not work:</div><ul class=\"examples\"><li><em>Are you doing anything nice this weekend?</em></li><li><strong><em>last/next weekend</strong> (=the weekend before or after this one)</em></li><li><strong><em>at the weekend<em>British English,</em></strong> <strong>on the weekend</em>American English</strong><em>: I never work at the weekend. / What are you doing on the weekend?</em></li><li><strong><em>at weekends<em>British English,</em></strong> <strong>on weekends</em>American English</strong><em>: I only see him at weekends.</em></li><li><em>Tony has been unwell over the weekend (=during the weekend).</em></li><li><em>We’re going to Paris for a long weekend (=Saturday and Sunday, and also Friday or Monday, or both).</em></li><li><strong><em>weekend cottage/cabin etc</strong> (=a place in the country where you spend your weekends)</em></li></ul></div>","7657":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> week‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwiːkli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">happening or done every week:</div><ul class=\"examples\"><li><em>a weekly current affairs programme</em></li><li><em>twice-weekly flights</em></li></ul></div>","7658":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wiːp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle wept /wept/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> <em>formal</em> or <em>literary</em> to cry, especially because you feel very sad: ► see thesaurus at cry RegisterIn everyday English, people usually say cry rather than weep:· She was crying all the way through the movie.</div><ul class=\"examples\"><li><em>James broke down and wept.</em></li><li><strong><em>weep for</strong>: She wept for the loss of her mother.</em></li><li><em>He wept bitterly (=cried a lot) when it was time for us to leave.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>I could have wept</strong> <em>spoken</em> used to say that you felt very disappointed about something:</div><ul class=\"examples\"><li><em>I could have wept thinking what I’d missed.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> if a wound weeps, liquid comes out of it</div></div>","7659":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /weɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[be a particular weight]</strong> <span class=\"gram\">[linking verb]</span> to have a particular weight: GRAMMAR: Linking verbsWeigh is a linking verb in this meaning. It links the subject of the sentence with a noun, often an amount: · The package weighed several kilos.</div><ul class=\"examples\"><li><em>The young birds weigh only a few grams.</em></li><li><em>Do you know how much it weighs?</em></li><li><em>What (=how much) do you weigh?</em></li><li><em>The box was full of books and weighed a ton (=was very heavy).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[measure weight]</strong> <span class=\"gram\">[transitive]</span> to use a machine to discover how much something or someone weighs:</div><ul class=\"examples\"><li><em>He weighed some potatoes on the scales.</em></li><li><strong><em>weigh yourself</strong>: Have you weighed yourself lately?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[consider/compare]</strong> (also weigh up) <span class=\"gram\">[transitive]</span> to consider something carefully so that you can make a decision about it:</div><ul class=\"examples\"><li><em>It is my job to weigh the evidence.</em></li><li><strong><em>weigh something against something</strong>: We have to weigh the benefits of the scheme against the costs.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[influence]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> <em>formal</em> to influence someone’s opinion and the decision that they make</div><ul class=\"examples\"><li><strong><em>weigh against</strong>: This unfortunate experience will weigh heavily against further investment in the area.</em></li><li><strong><em>weigh in somebody&#x27;s/something’s favour</strong>: These facts will weigh in your favour.</em></li><li><strong><em>weigh with</strong>: Her evidence weighed strongly with the judge.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>weigh your words</strong> to think very carefully about what you say because you do not want to say the wrong thing:</div><ul class=\"examples\"><li><em>He was weighing his words carefully.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>weigh anchor</strong> to raise an anchor and sail away</div></div>","7660":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /weɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[amount somebody/something weighs]</strong> <span class=\"gram\">[countable, uncountable]</span> how heavy something is when you measure it:</div><ul class=\"examples\"><li><em>The average weight of a baby at birth is just over seven pounds.</em></li><li><strong><em>in weight</strong>: fish that are over two kilos in weight</em></li><li><strong><em>by weight</strong>: Fruit and vegetables are sold by weight.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[how fat]</strong> <span class=\"gram\">[uncountable]</span> how heavy and fat someone is: → overweight, underweight</div><ul class=\"examples\"><li><em>You shouldn’t worry about your weight.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[heaviness]</strong> <span class=\"gram\">[uncountable]</span> the fact that something is heavy:</div><ul class=\"examples\"><li><em>The weight of her boots made it hard for Sue to run.</em></li><li><em>I didn’t know if the bridge would support our weight.</em></li><li><strong><em>under the weight of something</strong>: Karen staggered along under the weight of her backpack.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[heavy thing]</strong> <span class=\"gram\">[countable]</span> something that is heavy:</div><ul class=\"examples\"><li><em>I can’t lift heavy weights because of my bad back.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[worry]</strong> <span class=\"gram\">[singular]</span> something that causes you a lot of worry because you have to deal with it</div><ul class=\"examples\"><li><strong><em>weight of</strong>: She felt a great weight of responsibility. / families who are crumbling under the weight of increasing debt</em></li><li><em>Selling the house is a weight off my mind (=something that no longer causes a lot of worry).</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[importance]</strong> <span class=\"gram\">[uncountable]</span> if something has weight, it is important and influences people:</div><ul class=\"examples\"><li><em>She knew that her opinion carried very little weight.</em></li><li><strong><em>give/add weight to something</strong>: This scandal adds more weight to their arguments.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[amount]</strong> <strong>weight of something</strong> a large amount of something:</div><ul class=\"examples\"><li><em>The weight of evidence is that unemployment leads to all sorts of health problems.</em></li><li><em>The weight of public opinion is behind the teachers.</em></li><li><em>They won the battle by sheer weight of numbers (=very large numbers of people).</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[for measuring quantities]</strong> <span class=\"gram\">[countable]</span> a piece of metal that weighs an exact amount and is balanced against something else to measure how much the other thing weighs</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>[for sport]</strong> <span class=\"gram\">[countable]</span> a piece of metal that weighs an exact amount and is lifted by people as a sport: → weightlifting</div><ul class=\"examples\"><li><em>I’ve been lifting weights since I was 18.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>throw your weight about/around</strong> <em>informal</em> to use your position of authority to tell people what to do in an unpleasant and unreasonable way</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>throw your weight behind somebody/something</strong> to use all your power and influence to support someone or something:</div><ul class=\"examples\"><li><em>The US has thrown its weight behind the new leader.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>pull your weight</strong> to do your full share of work:</div><ul class=\"examples\"><li><em>He accused me of not pulling my weight.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>take the weight off your feet</strong> <em>informal</em> used to tell someone to sit down:</div><ul class=\"examples\"><li><em>Come in, take the weight off your feet.</em></li></ul></div>","7661":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɪəd $ wɪrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\"><em>informal</em> very strange and unusual, and difficult to understand or explain: ► see thesaurus at strange</div><ul class=\"examples\"><li><em>A really weird thing happened last night.</em></li><li><em>He’s a weird bloke.</em></li><li><em>They sell all sorts of weird and wonderful (=very strange) products.</em></li></ul></div>","7662":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">interjection</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ˈwelkəm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1</span></div><div class=\"entry-body\"><div class=\"sense\">used to greet someone who has just arrived</div><ul class=\"examples\"><li><strong><em>welcome to</strong>: Welcome to London!</em></li><li><em>Welcome back – it’s good to see you again.</em></li><li><em>Hello, welcome home.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>you’re welcome</strong> <em>spoken</em> a polite way of replying to someone who has just thanked you for something:</div><ul class=\"examples\"><li><em>‘Thanks for the coffee.’ ‘You’re welcome.’</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if someone is welcome in a place, other people are glad that they are there:</div><ul class=\"examples\"><li><em>I had the feeling I wasn’t really welcome.</em></li><li><em>I didn’t feel welcome in the club.</em></li><li><em>Mary made us very welcome.</em></li><li><em>We try to make the new students feel welcome.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> if something is welcome, you enjoy it because you feel that you need it:</div><ul class=\"examples\"><li><em>The weekend was a welcome break from the pressures of work.</em></li><li><em>Six months in Scotland would make a welcome change from London.</em></li><li><em>A cup of tea would be very welcome.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> if something is welcome, you are glad that it has happened:</div><ul class=\"examples\"><li><em>The increase in interest rates is welcome news for investors.</em></li><li><em>This new funding will come as a welcome boost for the industry.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be welcome to something</strong> <em>spoken</em> used to say that someone can have something if they want it, because you certainly do not want it:</div><ul class=\"examples\"><li><em>If you want to take the job you’re welcome to it!</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be welcome to do something</strong> <em>spoken</em> used to invite someone to do something if they would like to:</div><ul class=\"examples\"><li><em>You’re welcome to stay for lunch.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wel‧come</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to say hello in a friendly way to someone who has just arrived <em>SYN greet</em>:</div><ul class=\"examples\"><li><em>I must be there to welcome my guests.</em></li><li><em>They welcomed us warmly.</em></li><li><em>His family welcomed me with open arms (=in a very friendly way).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to be glad to accept something:</div><ul class=\"examples\"><li><em>The college welcomes applications from people of all races.</em></li><li><em>We would welcome any advice or suggestions with open arms.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to be glad that something has happened because you think it is a good idea:</div><ul class=\"examples\"><li><em>Economists have welcomed the decision to raise interest rates.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[singular]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the way in which you greet someone when they arrive at a place</div><ul class=\"examples\"><li><strong><em>warm/friendly welcome</strong>: His colleagues gave him a very warm welcome when he returned to work. / You can be sure of a friendly welcome at all our hotels.</em></li><li><em>The president got a tremendous welcome at the airport.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the way in which people react to an idea, and show that they like it or do not like it:</div><ul class=\"examples\"><li><em>Politicians have given an enthusiastic welcome to the Queen’s speech.</em></li><li><em>The proposals have so far received a cautious welcome from government ministers.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>outstay/overstay your welcome</strong> to stay at someone’s house longer than they want you to</div></div></div>","7663":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wel‧fare</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwelfeə $ -fer/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone’s welfare is their health and happiness:</div><ul class=\"examples\"><li><em>Our only concern is the children’s welfare.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> help that is provided for people who have personal or social problems</div><ul class=\"examples\"><li><strong><em>welfare benefits/services/programmes etc</strong>: the provision of education and welfare services</em></li><li><em>The company’s welfare officer deals with employees’ personal problems.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>American English</em> money that is paid by the government in the US to people who are very poor or unemployed SYN benefit<em>British English</em></div><ul class=\"examples\"><li><strong><em>on welfare</strong>: Most of the people in this neighborhood are on welfare.</em></li></ul></div>","7664":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wel/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(comparative better /ˈbetə $ -ər/, superlative best /best/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[satisfactorily]</strong> in a successful or satisfactory way:</div><ul class=\"examples\"><li><em>Did you sleep well?</em></li><li><em>James reads quite well for his age.</em></li><li><em>All the team played very well today.</em></li><li><em>Simon doesn’t work well under pressure.</em></li><li><em>The festival was very well organized.</em></li><li><em>The concert went very well.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[thoroughly]</strong> in a thorough way:</div><ul class=\"examples\"><li><em>Mix the flour and butter well.</em></li><li><em>I know Birmingham quite well.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[a lot]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a lot, or to a great degree</div><ul class=\"examples\"><li><strong><em>well before/after/above/below etc</strong>: Stand well back from the bonfire. / It was well after 12 o&#x27;clock when they arrived. / The village is well below sea level.</em></li><li><em>The amphitheatre is well worth a visit.</em></li><li><em>I’m well aware of the problems involved.</em></li><li><em>I went out and got well and truly (=completely) drunk.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[+adjective]</span> <em>British English</em> <em>informal</em> very:</div><ul class=\"examples\"><li><em>That was well funny!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>do well</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to be successful, especially in work or business:</div><ul class=\"examples\"><li><em>He’s doing very well at college.</em></li><li><em>Elizabeth’s done well for herself since she moved to London.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if someone who has been ill is doing well, they are becoming healthy again:</div><ul class=\"examples\"><li><em>He had the operation yesterday, and he’s doing very well.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>as well</strong> in addition to something or someone else: RegisterAs well is used mostly in spoken English. In written English, people usually prefer to use also:· Parents are also welcome.</div><ul class=\"examples\"><li><em>Why don’t you come along as well?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>as well as something/somebody</strong> in addition to something or someone else:</div><ul class=\"examples\"><li><em>They own a house in France as well as a villa in Spain.</em></li><li><strong><em>as well as doing something</strong>: The organization gives help and support to people in need, as well as raising money for local charities.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>may/might/could well</strong> used to say that something is likely to happen or is likely to be true:</div><ul class=\"examples\"><li><em>What you say may well be true.</em></li><li><em>You could try the drugstore, but it might well be closed by now.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>may/might/could (just) as well</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>informal</em> used when you do not particularly want to do something but you decide you should do it:</div><ul class=\"examples\"><li><em>I suppose we may as well get started.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to mean that another course of action would have an equally good result:</div><ul class=\"examples\"><li><em>The taxi was so slow we might just as well have gone on the bus.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>can’t very well (do something)</strong> used to say that you cannot do something because it would be unacceptable:</div><ul class=\"examples\"><li><em>I can’t very well tell him we don’t want him at the party!</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>know full/perfectly well</strong> used to say that someone does know something even though they are behaving as if they do not:</div><ul class=\"examples\"><li><em>You know full well what I mean.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>speak/think well of somebody</strong> to talk about someone in an approving way or to have a favourable opinion of them:</div><ul class=\"examples\"><li><em>Sue has always spoken well of you.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>well done!/well played!</strong> <em>spoken</em> used to praise someone when you think they have done something very well</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>well said!</strong> <em>spoken</em> used to say that you agree with what someone has just said, or that you admire them for saying it</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>be well away</strong> <em>British English</em> <em>informal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to be making good progress:</div><ul class=\"examples\"><li><em>If we can get that grant from the local authority, we’ll be well away.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to be very drunk</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>be well in with somebody</strong> <em>informal</em> to have a friendly relationship with someone, especially someone important:</div><ul class=\"examples\"><li><em>She’s very well in with members of the management committee.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>be well out of something</strong> <em>British English</em> <em>spoken</em> to be lucky to no longer be involved in a particular situation</div><div class=\"sense\"><span class=\"snum\">17</span> <strong>be well up in/on something</strong> <em>informal</em> <em>especially British English</em> to know a lot about a particular subject:</div><ul class=\"examples\"><li><em>Geoff’s always been well up on the internet.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>as well somebody might/may</strong> <em>formal</em> used to say that there is a good reason for someone’s feelings or reactions:</div><ul class=\"examples\"><li><em>Marilyn looked guilty, as well she might.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>do well by somebody</strong> <em>informal</em> to treat someone generously</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">interjection</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[emphasizing something]</strong> used to emphasize something you are saying:</div><ul class=\"examples\"><li><em>Well, I think it’s a good idea anyway.</em></li><li><em>Well, I’ve had enough and I’m going home!</em></li><li><em>‘James doesn’t want to come to the cinema with us.’ ‘Well then, let’s go on our own.’</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[pausing]</strong> used to pause or give yourself time to think before saying something:</div><ul class=\"examples\"><li><em>Well, let’s see now, I could meet you on Thursday.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[accepting a situation]</strong> (also oh well) used to show that you accept a situation even though you feel disappointed or annoyed about it:</div><ul class=\"examples\"><li><em>Well, I did my best – I can’t do any more than that.</em></li><li><em>Oh well, we’ll just have to cancel the holiday, I suppose.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[showing surprise]</strong> (also well, well, (well)) used to express surprise or amusement:</div><ul class=\"examples\"><li><em>Well, so Steve got the job?</em></li><li><em>Well, well, well, I didn’t think I’d see you here.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[showing anger]</strong> used to express anger or disapproval:</div><ul class=\"examples\"><li><em>Well, she could at least have phoned to say she wasn’t coming!</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[final remark]</strong> used to show that you are about to finish speaking or doing something:</div><ul class=\"examples\"><li><em>Well, that’s all for today.</em></li><li><em>Well, that’s the last one done.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[expressing doubt]</strong> used to show that you are not sure about something:</div><ul class=\"examples\"><li><em>‘Will you be in on Friday evening?’ ‘Well, it depends.’</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[changing something]</strong> used to slightly change something that you have said:</div><ul class=\"examples\"><li><em>He’s rolling in money! Well, he’s got a lot more than me, anyway.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[agreeing]</strong> <strong>very well</strong> <em>formal</em> used to show that you agree with an idea or accept a suggestion:</div><ul class=\"examples\"><li><em>‘Very well,’ he said. ‘I accept.’</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[continuing a story]</strong> used to continue a story you are telling people, especially in order to make it seem more interesting:</div><ul class=\"examples\"><li><em>You know that couple I was telling you about the other day? Well, last night I saw a police car in front of their house!</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[asking a question]</strong> <strong>Well?</strong> used to ask someone to answer a question you have asked them, when you are angry with them:</div><ul class=\"examples\"><li><em>Well? What have you got to say for yourself?</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\">(comparative better, superlative best)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> healthy: ► see thesaurus at healthy</div><ul class=\"examples\"><li><em>‘How are you?’ ‘Very well, thanks.’</em></li><li><em>I don’t feel very well.</em></li><li><em>You’re looking very well.</em></li><li><em>I hope you get well again soon.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>it’s just as well (that)</strong> <em>spoken</em> used to say that things have happened in a good or fortunate way:</div><ul class=\"examples\"><li><em>It’s just as well I kept some money aside for emergencies.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>it’s/that’s all very well, but...</strong> <em>spoken</em> used to say that something seems to be a good idea, but is not really possible or helpful:</div><ul class=\"examples\"><li><em>It’s all very well the doctors telling me I’ve got to rest, but who’s going to look after my children?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>that’s/it’s all well and good</strong> <em>spoken</em> <em>especially British English</em> used to say that something is good or enjoyable, but it also has some disadvantages:</div><ul class=\"examples\"><li><em>Going off on foreign holidays is all well and good, but you’ve got to get back to reality sometime.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>it might/would be as well</strong> <em>spoken</em> used to give someone advice or make a helpful suggestion:</div><ul class=\"examples\"><li><em>It might be as well to make him rest for a few days.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>all is well/all is not well</strong> <em>formal</em> used to say that a situation is satisfactory or not satisfactory:</div><ul class=\"examples\"><li><em>All is not well with their marriage.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>all’s well that ends well</strong> used to say that a difficult situation has ended with a good result. It is the title of a humorous play by William Shakespeare about the relationship between the two main characters, Helena and Bertram.</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a deep hole in the ground from which people take water:</div><ul class=\"examples\"><li><em>She lowered her bucket into the well.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an oil well</div><div class=\"sense\"><span class=\"snum\">3</span> the space in a tall building where the stairs are</div></div></div>","7665":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌwell-ˈbeing</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a feeling of being comfortable, healthy, and happy</div><ul class=\"examples\"><li><strong><em>well-being of</strong>: We are responsible for the care and well-being of all our patients.</em></li><li><strong><em>a sense/feeling of well-being</strong>: A good meal promotes a feeling of well-being.</em></li><li><strong><em>physical/psychological/material etc well-being</strong>: the physical and emotional well-being of the children</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the well-being of a country is the state in which it is strong and doing well:</div><ul class=\"examples\"><li><em>We are now concerned for the economic well-being of the country.</em></li></ul></div>","7666":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌwell-esˈtablished</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">something that is well-established has existed for a long time and is respected or trusted by people:</div><ul class=\"examples\"><li><em>a well-established law firm</em></li><li><em>a well-established scientific theory</em></li></ul></div>","7667":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌwell-ˈknown</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(comparative better-known, superlative best-known)</span></div><div class=\"entry-body\"><div class=\"sense\">known by a lot of people → notorious ► see thesaurus at famous</div><ul class=\"examples\"><li><strong><em>it is well-known (that)</strong>: It’s a well-known fact that smoking can cause lung cancer.</em></li><li><em>This is probably their best-known song.</em></li><li><em>a well-known TV presenter</em></li><li><strong><em>well-known for</strong>: He was well-known for his extreme political views.</em></li></ul></div>","7668":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /west/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[singular, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the direction towards which the sun goes down, and which is on the left if you are facing north</div><ul class=\"examples\"><li><strong><em>from/towards the west</strong>: A damp wind blew from the west.</em></li><li><strong><em>to the west (of something)</strong>: a village to the west of Brussels</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the west</strong> the western part of a country or area:</div><ul class=\"examples\"><li><em>There’s a slight chance of some sunshine in the west.</em></li><li><strong><em>west of</strong>: the west of the island</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in the west or facing the west:</div><ul class=\"examples\"><li><em>the west door of the church</em></li><li><em>farmers in West Africa</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a west wind comes from the west</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> towards the west:</div><ul class=\"examples\"><li><em>The route then heads west over Gerrick Moor.</em></li><li><strong><em>west of</strong>: The walk starts at Alnham, six miles west of Bridge of Aln.</em></li><li><em>a west-facing window</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>out west</strong> to or in the western part of a country or area, especially the US:</div><ul class=\"examples\"><li><em>The family moved out west to Kansas.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>go west</strong> <em>British English</em> <em>old-fashioned</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to die – used humorously</div><div class=\"subsense\"><span class=\"subnum\">b)</span> to be damaged or ruined – used humorously</div></div></div>","7669":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> west‧ern</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwestən $ -ərn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in or from the west of a country or area:</div><ul class=\"examples\"><li><em>the western end of the bay</em></li><li><em>Western Australia</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> relating to ideas and ways of doing things that come from Europe and the Americas:</div><ul class=\"examples\"><li><em>Western philosophies</em></li></ul></div>","7670":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wet/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\">(comparative wetter, superlative wettest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[water/liquid]</strong> covered in or full of water or another liquid <em>OPP dry</em>:</div><ul class=\"examples\"><li><em>I’ve washed your shirt but it’s still wet.</em></li><li><em>wet grass</em></li><li><strong><em>get (something) wet</strong>: Take an umbrella or you’ll get wet.</em></li><li><strong><em>wet with</strong>: His face was wet with sweat.</em></li><li><em>The man in the boat was wet through (=completely wet).</em></li><li><strong><em>soaking/dripping/sopping wet</strong> (=very wet): The towel was soaking wet.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[weather]</strong> rainy:</div><ul class=\"examples\"><li><em>There’s more wet weather on the way.</em></li><li><em>It’s very wet outside.</em></li><li><em>the wettest summer on record</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[paint/ink etc]</strong> not yet dry:</div><ul class=\"examples\"><li><em>The paint’s still wet.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[person]</strong> <em>British English</em> <em>informal</em> someone who is wet does not have a strong character, or is not willing to do something that you think they should do – used to show disapproval:</div><ul class=\"examples\"><li><em>Don’t be so wet! Just tell them you don’t want to go.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[baby]</strong> if a child or its nappy is wet, the nappy is full of urine</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>somebody is all wet</strong> <em>American English</em> <em>informal</em> someone is completely wrong</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>wet behind the ears</strong> <em>informal</em> very young and without much experience of life</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle wet or wetted, present participle wetting)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make something wet:</div><ul class=\"examples\"><li><em>Wet your hair and apply the shampoo.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make yourself, your clothes, or your bed wet because you pass water from your body by accident</div><ul class=\"examples\"><li><strong><em>wet yourself</strong>: I nearly wet myself I was so scared.</em></li><li><em>Sam’s wet his bed again.</em></li></ul></div></div>","7671":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /weɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a very large animal that lives in the sea and looks like a fish, but is actually a mammal</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>have a whale of a time</strong> <em>informal</em> to enjoy yourself very much</div></div>","7672":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɒt $ wɑːt, wʌt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to ask for information or for someone’s opinion: USAGE: What, whichWhen there are only a small number of possible things or people, you use which, not what: · Which leg did he break?· Which brother do you mean? ✗Don’t say: What leg did he break? | What brother do you mean?</div><ul class=\"examples\"><li><em>What are you doing?</em></li><li><em>What subjects did you enjoy most?</em></li><li><em>What colour is the new carpet?</em></li><li><em>What’s your new boss like?</em></li><li><em>What do you think of my painting?</em></li><li><em>What do you mean, you want to spend Christmas alone?</em></li><li><strong><em>what on earth/in the world/in heaven’s name etc</strong> (=used for emphasis when you are surprised, angry etc): What on earth’s going on?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to introduce a clause about something that is or was not known or not certain:</div><ul class=\"examples\"><li><em>No one knows exactly what happened.</em></li><li><em>It is not clear to what extent these views were shared.</em></li><li><strong><em>what to do/say/expect etc</strong>: They’re discussing what to do next.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the thing which: GRAMMARWhat is not a relative pronoun and should not be used to begin a clause after a noun or pronoun. Use that instead. You say: · There are so many things that can go wrong. ✗Don’t say: There are so many things what can go wrong.</div><ul class=\"examples\"><li><em>Show me what you bought.</em></li><li><em>I believe what he told me.</em></li><li><em>I could get you a job here if that’s what you want.</em></li><li><em>What he did was morally wrong.</em></li><li><em>She gave him what money she had (=all the money she had, although she did not have much).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used at the beginning of a statement to emphasize what you are going to say:</div><ul class=\"examples\"><li><em>What that kid needs is some love and affection.</em></li><li><em>What we’ll do is leave a note for Mum to tell her we won’t be back till late.</em></li><li><em>What matters is the British people and British jobs.</em></li></ul></div>","7673":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">determiner</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> what‧ev‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /wɒtˈevə $ wɑːtˈevər, wʌt-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> any or all of the things that are wanted, needed, or possible:</div><ul class=\"examples\"><li><em>Help yourself to whatever you want.</em></li><li><em>The children were allowed to do whatever they liked.</em></li><li><em>He’ll be ready to accept whatever help he can get.</em></li><li><em>I am willing to pay whatever price you ask.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to say that it is not important what happens, what you do etc because it does not change the situation:</div><ul class=\"examples\"><li><em>Whatever I suggest, he always disagrees.</em></li><li><em>The building must be saved, whatever the cost.</em></li><li><em>If you are unable to attend the interview, for whatever reason, you should inform us immediately.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\">used to emphasize a negative statement <em>SYN whatsoever</em>:</div><ul class=\"examples\"><li><em>She has shown no interest whatever in anything scientific.</em></li><li><em>This is just a stupid argument that has nothing whatever to do with your job.</em></li></ul></div></div>","7674":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> what‧so‧ev‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌwɒtsəʊˈevə $ ˌwɑːtsoʊˈevər, ˌwʌt-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">used to emphasize a negative statement <em>SYN whatever</em>:</div><ul class=\"examples\"><li><em>He’s had no luck whatsoever.</em></li></ul></div>","7675":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wiːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the grain that bread is made from, or the plant that it grows on:</div><ul class=\"examples\"><li><em>a field of wheat</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>separate the wheat from the chaff</strong> to choose the good and useful things or people and get rid of the others</div></div>","7676":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wiːl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[on a vehicle]</strong> one of the round things under a car, bus, bicycle etc that turns when it moves → four-wheel drive</div><ul class=\"examples\"><li><strong><em>front/rear/back wheels</strong>: The car slid sideways, its rear wheels spinning.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[for controlling a vehicle]</strong> <span class=\"gram\">[usually singular]</span> the round piece of equipment that you turn to make a car, ship etc move in a particular direction → steering wheel</div><ul class=\"examples\"><li><strong><em>at/behind the wheel</strong> (=driving a car): The driver must have fallen asleep at the wheel.</em></li><li><em>Shall I take the wheel (=drive instead of someone else)?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[in a machine]</strong> a flat round part in a machine that turns round when the machine operates:</div><ul class=\"examples\"><li><em>a gear wheel</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the wheels of something</strong> the way in which a complicated organization, system etc works:</div><ul class=\"examples\"><li><em>We hope that the next government will do more to keep the wheels of industry turning (=help it to work smoothly and easily).</em></li><li><strong><em>oil/grease the wheels (of something)</strong> (=help something to work more smoothly and easily): The money people spend at Christmas oils the wheels of the economy.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>the wheel of fortune/life/time etc</strong> the way in which things change in life, or in which the same things seem to happen again after a period of time:</div><ul class=\"examples\"><li><em>We are powerless to stop the wheel of history.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>(set of) wheels</strong> <em>spoken</em> a car:</div><ul class=\"examples\"><li><em>Do you like my new wheels?</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>wheels within wheels</strong> <em>spoken</em> used to say that a situation is complicated and difficult to understand because it involves processes and decisions that you know nothing about</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>set the wheels in motion/set the wheels turning</strong> to make a particular process start:</div><ul class=\"examples\"><li><em>It only took one phone call to set the wheels in motion.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>the wheels come off something</strong> used to say that something suddenly stops being successful:</div><ul class=\"examples\"><li><em>Why did the wheels come off his campaign?</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>a/the big wheel</strong> <em>informal</em> an important person:</div><ul class=\"examples\"><li><em>He became a big wheel in the East India Company.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive always + adverb/preposition]</span> ► see thesaurus at push</div><div class=\"subsense\"><span class=\"subnum\">a)</span> to push something that has wheels somewhere:</div><ul class=\"examples\"><li><em>Kate wheeled her bike into the garage.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to move someone or something that is in or on something that has wheels:</div><ul class=\"examples\"><li><em>Two nurses were wheeling him into the operating theatre.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> if birds or planes wheel, they fly around in circles</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> to turn around suddenly</div><ul class=\"examples\"><li><strong><em>wheel around</strong>: She wheeled around and started yelling at us.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>wheel and deal</strong> to do a lot of complicated and sometimes dishonest deals, especially in politics or business</div></div></div>","7677":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wheel‧chair</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwiːltʃeə $ -tʃer/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a chair with wheels, used by people who cannot walk</div><ul class=\"examples\"><li><strong><em>in a wheelchair</strong>: He’ll be in a wheelchair for the rest of his life.</em></li><li><em>Lynn has been confined to a wheelchair (=has had to use a wheelchair) for the last year.</em></li><li><em>special parking for wheelchair users</em></li></ul></div>","7678":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wen/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> at what time:</div><ul class=\"examples\"><li><em>When are we leaving?</em></li><li><em>When did you first meet Dr Darnall?</em></li><li><em>When will the work be finished?</em></li><li><em>I don’t know when I’ll see her again.</em></li><li><strong><em>when to do something</strong>: I’ll tell you when to stop.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> at or during the time that something happens:</div><ul class=\"examples\"><li><em>Leonard was nine when his father died.</em></li><li><em>When the family came here from Russia, they were penniless.</em></li><li><em>When he was in the air force he flew Tornado jets.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> after or as soon as something happens:</div><ul class=\"examples\"><li><em>When the meal was finished, Rachel washed up and made coffee.</em></li><li><em>I’ll phone you again when I get home.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used to mention a type of event or situation when talking about what happens on occasions of that type:</div><ul class=\"examples\"><li><em>When lead is added to petrol, it improves the car’s performance.</em></li><li><em>When mixed with water the powder forms a smooth paste.</em></li><li><em>He always wears glasses except when playing football.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> used to show which particular time or occasion you are talking about:</div><ul class=\"examples\"><li><em>The best moment was when he scored the winning goal.</em></li><li><em>There are times when I hate him.</em></li><li><strong><em>the day/time/afternoon etc when</strong>: She remembered the day when Paula had first arrived.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>by/since when</strong> before or since which time:</div><ul class=\"examples\"><li><em>The baby is due in May, by when the new house should be finished.</em></li><li><em>That was written in 1946, since when the education system has undergone great changes.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>since when...?</strong> <em>spoken</em> used to show that you are very surprised or angry:</div><ul class=\"examples\"><li><em>Since when have you been interested in my feelings?</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> even though something is true:</div><ul class=\"examples\"><li><em>Why does she steal things when she could easily afford to buy them?</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> used to introduce a fact or statement that makes something seem surprising:</div><ul class=\"examples\"><li><em>When you consider that the airline handled 80 million passengers last year, the accident figures are really very small.</em></li></ul></div>","7679":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> when‧ev‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /wenˈevə $ -ˈevər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> every time that a particular thing happens:</div><ul class=\"examples\"><li><em>Larry always blames me whenever anything goes wrong.</em></li><li><em>Whenever I hear that tune, it makes me think of you.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> at any time:</div><ul class=\"examples\"><li><em>Come and visit me whenever you want.</em></li><li><em>a policy of using recycled paper whenever possible</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>spoken</em> used as a reply to say that it does not matter what time something happens:</div><ul class=\"examples\"><li><em>‘I’ll call you tomorrow or the day after.’ ‘Okay. Whenever.’</em></li></ul></div>","7680":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /weə $ wer/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in or to which place:</div><ul class=\"examples\"><li><em>Where are you going?</em></li><li><em>Where do they live?</em></li><li><em>Do you know where my glasses are?</em></li><li><em>Where would you like to sit?</em></li><li><strong><em>where (...) to/from</strong>: Where have you come from? / ‘We’re going on a long journey.’ ‘Where to?’</em></li><li><strong><em>where to do something</strong>: They’re easy to find, if you know where to look.</em></li><li><strong><em>where on earth/in the world etc</strong> (=used for emphasis when you are surprised, angry etc): Where on earth have you been all this time?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to talk about a particular place:</div><ul class=\"examples\"><li><em>She was standing exactly where you are standing now.</em></li><li><em>Stay where you are.</em></li><li><em>This is the place where I hid the key.</em></li><li><em>In 1963 we moved to Boston, where my grandparents lived.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to talk about a particular stage in a process, conversation, story etc:</div><ul class=\"examples\"><li><em>The treatment will continue until the patient reaches the point where he can walk correctly and safely.</em></li><li><em>You are saying that everyone should be equal, and this is where I disagree.</em></li><li><em>Now, where were we? Oh yes, we were talking about John.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used to ask or talk about the origin of something or someone:</div><ul class=\"examples\"><li><em>Where does the word ‘super’ come from?</em></li><li><em>Where does this man get the money to keep two houses?</em></li><li><em>I wonder where he gets these strange ideas.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> used to say that one person, thing, opinion etc is different from another:</div><ul class=\"examples\"><li><em>Where others might have been satisfied, Dawson had higher ambitions.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> in or to any place <em>SYN wherever</em>:</div><ul class=\"examples\"><li><em>You can sit where you like.</em></li><li><em>You’re free to go where you please.</em></li></ul></div>","7681":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> where‧a‧bouts</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌweərəˈbaʊts◂ $ ˈwerəbaʊts/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">used to ask in what general area something or someone is:</div><ul class=\"examples\"><li><em>Whereabouts do you live?</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> where‧a‧bouts</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈweərəbaʊts $ ˈwer-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[plural]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the place or area where someone or something is: ► see thesaurus at place</div><ul class=\"examples\"><li><em>He showed great reluctance to reveal his whereabouts.</em></li><li><strong><em>whereabouts of</strong>: The police want to know the whereabouts of his brother.</em></li></ul></div></div>","7682":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> where‧as</span><span class=\"meta-item\"><strong>IPA:</strong> /weərˈæz $ wer-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>formal</em> used to say that although something is true of one thing, it is not true of another: ► see thesaurus at but</div><ul class=\"examples\"><li><em>The old system was fairly complicated whereas the new system is really very simple.</em></li><li><em>Whereas the city spent over $1 billion on its museums and stadium, it failed to look after its schools.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>law</em> used at the beginning of an official document to mean ‘because of a particular fact’</div></div>","7683":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> where‧by</span><span class=\"meta-item\"><strong>IPA:</strong> /weəˈbaɪ $ wer-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">by means of which or according to which:</div><ul class=\"examples\"><li><em>a proposal whereby EU citizens would be allowed to reside anywhere in the EU</em></li></ul></div>","7684":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wher‧ev‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /weərˈevə $ werˈevər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to or at any place, position, or situation:</div><ul class=\"examples\"><li><em>Children will play wherever they happen to be.</em></li><li><em>Sit wherever you like.</em></li><li><strong><em>... or wherever</strong> (=used to emphasize that you are talking about any place and not a specific place): Dublin people dress more individually than people in London or wherever.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in all places that:</div><ul class=\"examples\"><li><em>She is shadowed by detectives wherever she goes.</em></li><li><em>I feel I ought to be nice to them wherever possible (=at all times when it is possible).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used at the beginning of a question to show surprise:</div><ul class=\"examples\"><li><em>‘Wherever did she find that?’ Daisy wondered.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>wherever that is/may be</strong> used to say that you do not know where a place or town is or have never heard of it:</div><ul class=\"examples\"><li><em>She wants to move to Far Flatley, wherever that is.</em></li></ul></div>","7685":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wheth‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈweðə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used when talking about a choice you have to make or about something that is not certain:</div><ul class=\"examples\"><li><em>Maurice asked me whether I needed any help.</em></li><li><em>There were times when I wondered whether or not we would get there.</em></li><li><strong><em>whether to do something</strong>: She was uncertain whether to stay or leave. / I didn’t know whether to believe him or not.</em></li><li><em>The question arose as to whether this behaviour was unlawful.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to say that something definitely will or will not happen whatever the situation is:</div><ul class=\"examples\"><li><em>It seemed to me that she was in trouble whether Mahoney lived or died.</em></li><li><em>Look, Kate, I’m calling the doctor, whether you like it or not.</em></li><li><em>Poor farmers, whether owners or tenants, will be worst affected.</em></li></ul></div>","7686":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɪtʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to ask or talk about one or more members of a group of people or things, when you are uncertain about it or about them:</div><ul class=\"examples\"><li><em>Which book are you looking for?</em></li><li><em>Which are the most important crops?</em></li><li><em>Miranda was sure it was one of them, but was not sure which.</em></li><li><strong><em>which of</strong>: I don’t know which of us was the more scared.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used after a noun to show what thing or things you mean:</div><ul class=\"examples\"><li><em>Did you see the letter which came today?</em></li><li><em>Now they were driving by the houses which Andy had described.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used, after a comma in writing, to add more information about the thing, situation, or event you have just mentioned:</div><ul class=\"examples\"><li><em>The house, which was completed in 1856, was famous for its huge marble staircase.</em></li><li><em>One of the boys kept laughing, which annoyed Jane intensely.</em></li><li><em>He was educated at the local grammar school, after which he went on to Cambridge.</em></li><li><em>She may have missed the train, in which case (=if this has happened) she won’t arrive for another hour.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>don’t know/can’t tell etc which is which</strong> if you do not know which is which, you cannot see the difference between two very similar people or things:</div><ul class=\"examples\"><li><em>The twins are so alike I can never tell which is which.</em></li></ul></div>","7687":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> which‧ev‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /wɪtʃˈevə $ -ˈevər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to say that it does not matter which thing or person is chosen because the result will be the same:</div><ul class=\"examples\"><li><em>It will be a difficult operation, whichever method you choose.</em></li><li><em>Whichever way you look at it, things are pretty bad.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to refer to the member of a group of people or things that does something, is wanted, is possible etc:</div><ul class=\"examples\"><li><em>Whichever player scores the highest number of points will be the winner.</em></li><li><em>You can either have the double room or the family room, whichever you want.</em></li><li><em>‘Do you want tea or coffee?’ ‘I don’t mind – whichever one you’re making.’</em></li></ul></div>","7688":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">conjunction</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /waɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> during the time that something is happening:</div><ul class=\"examples\"><li><em>They arrived while we were having dinner.</em></li><li><em>While she was asleep, thieves broke in and stole her handbag.</em></li><li><em>She met Andy while working on a production of ‘Carmen’.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> all the time that something is happening: GRAMMAR: Choosing the right tenseYou use the present tense, not ‘will’, with while when you are talking about the future: · I hope to visit the British Museum while I am in London. ✗Don’t say I hope to visit the British Museum while I will be in London.Grammar guide ‒ VERBS</div><ul class=\"examples\"><li><em>Would you look after the children while I do the shopping?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to emphasize the difference between two situations, activities etc: ► see thesaurus at but</div><ul class=\"examples\"><li><em>Schools in the north tend to be better equipped, while those in the south are relatively poor.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> in spite of the fact that <em>SYN although</em>:</div><ul class=\"examples\"><li><em>While never a big eater, he did snack a lot.</em></li><li><em>While there was no conclusive evidence, most people thought he was guilty.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>while I’m/you’re etc at/about it</strong> <em>spoken</em> used to suggest that someone should do something at the same time that they do something else:</div><ul class=\"examples\"><li><em>Print out what you’ve written, and while you’re at it make a copy for me.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>a while</strong> a period of time, especially a short one:</div><ul class=\"examples\"><li><em>It takes a while to recover from the operation.</em></li><li><strong><em>in a while</strong>: Mr Thomas will be with you in a while.</em></li><li><strong><em>for a while</strong>: At last, he could relax for a while.</em></li><li><strong><em>a little/short while</strong>: Wait a little while before deciding.</em></li><li><em>We talked for quite a while (=a fairly long time) on the phone.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>all the while</strong> all the time that something is happening:</div><ul class=\"examples\"><li><em>He examined her thoroughly, talking softly all the while.</em></li><li><em>She continued working, all the while keeping an eye on the clock.</em></li></ul></div></div>","7689":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /waɪlst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">while ► see thesaurus at while</div></div>","7690":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɪp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle whipped, present participle whipping)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to hit someone or something with a whip:</div><ul class=\"examples\"><li><em>He whipped the horse into a canter.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive always + adverb/preposition]</span> to move quickly and violently, or to make something do this:</div><ul class=\"examples\"><li><em>The wind whipped her hair into her eyes.</em></li><li><strong><em>whip across/around/past etc</strong>: Rain whipped across the window pane.</em></li><li><strong><em>whip something about/around</strong>: The branches were being whipped about in the storm.</em></li><li><strong><em>whip round/around</strong>: He whipped round to face them.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive always + adverb/preposition]</span> to move or remove something with a quick sudden movement</div><ul class=\"examples\"><li><strong><em>whip something off/out/back etc</strong>: Annie whipped off her apron and put it into the drawer.</em></li><li><em>He whipped back the sheets.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> to mix cream or the clear part of an egg very hard until it becomes stiff → beat, whisk:</div><ul class=\"examples\"><li><em>Whip the cream until thick.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[transitive]</span> <em>British English</em> <em>informal</em> to steal something</div></div>","7691":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɪsk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to mix liquid, eggs etc very quickly so that air is mixed in, using a fork or a whisk ► see thesaurus at mix</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[always + adverb/preposition]</span> to take someone or something quickly away from a place</div><ul class=\"examples\"><li><strong><em>whisk somebody/something away/off</strong>: The waitress whisked our coffee cups away before we’d had a chance to finish.</em></li></ul></div>","7692":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> whis‧ker</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪskə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[usually plural]</span> one of the long stiff hairs that grow near the mouth of a cat, mouse etc</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[usually plural]</span> one of the hairs that grow on a man’s face</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>win/lose by a whisker</strong> <em>informal</em> to win or lose by a very small amount:</div><ul class=\"examples\"><li><em>Schmidt finished second, losing by a whisker in the final event.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>come within a whisker of (doing) something</strong> to almost succeed or fail at doing something:</div><ul class=\"examples\"><li><em>Doctors say he came within a whisker of dying on the operating table.</em></li></ul></div>","7693":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> whis‧ky</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪski/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural whiskies or whiskeys)</span></div><div class=\"entry-body\"><div class=\"sense\">a strong alcoholic drink made from grain, or a glass of this</div></div>","7694":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> whis‧per</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪspə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to speak or say something very quietly, using your breath rather than your voice: ► see thesaurus at say</div><ul class=\"examples\"><li><em>You don’t have to whisper, no one can hear us.</em></li><li><strong><em>whisper about</strong>: What are you two whispering about over there?</em></li><li><strong><em>whisper something to somebody</strong>: James leaned over to whisper something to Michael.</em></li><li><em>‘I’ve missed you,’ he whispered in her ear.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to say or suggest something privately or secretly</div><ul class=\"examples\"><li><strong><em>whisper that</strong>: Staff were whispering that the company was about to go out of business.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a very quiet voice you make using your breath and no sound</div><ul class=\"examples\"><li><strong><em>in a whisper</strong>: ‘Where are we going?’ he asked in a whisper.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a piece of news or information that has not been officially announced and may or may not be true <em>SYN rumour</em></div><ul class=\"examples\"><li><strong><em>whisper of</strong>: The first whisper of the redundancies came from the newspapers.</em></li><li><strong><em>whisper that</strong>: There are whispers that the actor was seen checking into a hospital last week.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a whisper of something</strong> <em>literary</em> a low soft sound made by something such as the wind</div></div></div>","7695":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> whis‧tle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪsəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[high sound]</strong> <span class=\"gram\">[intransitive, transitive]</span> to make a high or musical sound by blowing air out through your lips:</div><ul class=\"examples\"><li><em>Adam whistled happily on his way to work.</em></li><li><em>I heard this song on the radio and I’ve been whistling it all day.</em></li><li><em>He whistled a tune as he strolled down the corridor.</em></li><li><strong><em>whistle to somebody</strong> (=whistle to get someone’s attention): Dad whistled to us to come home for dinner.</em></li><li><strong><em>whistle at somebody</strong> (=whistle to let someone know that you think they are attractive): Men are always whistling at Heidi on the street.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[use a whistle]</strong> <span class=\"gram\">[intransitive]</span> to make a high sound by blowing into a whistle:</div><ul class=\"examples\"><li><em>The referee whistled and the game began.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[go/move fast]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to move quickly, making a whistling sound:</div><ul class=\"examples\"><li><em>Bullets and shells were whistling overhead.</em></li><li><em>They listened to the wind whistling through the trees.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[steam train/kettle]</strong> <span class=\"gram\">[intransitive]</span> if a steam train or kettle whistles, it makes a high sound when air or steam is forced through a small hole</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[bird]</strong> <span class=\"gram\">[intransitive]</span> if a bird whistles, it makes a high musical sound</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>be whistling in the dark</strong> <em>informal</em> to be trying to show that you are brave when you are afraid, or that you know about something when you do not:</div><ul class=\"examples\"><li><em>Does he know what he’s talking about or is he just whistling in the dark?</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>somebody can whistle for something</strong> <em>British English</em> <em>spoken</em> used to tell someone that there is no chance of them getting what they have asked for</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a small object that produces a high whistling sound when you blow into it:</div><ul class=\"examples\"><li><em>The lifeguard blew his whistle.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a high sound made by blowing a whistle, by blowing air out through your lips, or when air or steam is forced through a small opening:</div><ul class=\"examples\"><li><em>Larsson scored just minutes before the final whistle.</em></li><li><strong><em>low/shrill/high-pitched etc whistle</strong>: Sanders gave a low whistle when he saw the contents of the box.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a piece of equipment on a train or boat that makes a high noise when air is forced through it</div><div class=\"sense\"><span class=\"snum\">4</span> the sound of something moving quickly through the air</div><ul class=\"examples\"><li><strong><em>whistle of</strong>: We could hear the whistle of the jets as they passed overhead.</em></li></ul></div></div>","7696":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /waɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[colour]</strong> having the colour of milk, salt, or snow:</div><ul class=\"examples\"><li><em>a white dress</em></li><li><strong><em>pure/snow white</strong> (=completely white): snow white hair</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[people]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> belonging to the race of people with pale skin → black:</div><ul class=\"examples\"><li><em>young white males</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> relating to white people:</div><ul class=\"examples\"><li><em>a white neighborhood</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[pale]</strong> looking pale, because of illness, strong emotion etc:</div><ul class=\"examples\"><li><em>Are you OK? You’re white as a sheet (=extremely pale).</em></li><li><strong><em>white with anger/fear etc</strong>: Her voice shook, and her face was white with anger.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[coffee]</strong> <span class=\"gram\">[usually before noun]</span> <em>British English</em> white coffee has milk or cream in it</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[wine]</strong> white wine is a pale yellow colour → red</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>a white Christmas</strong> a Christmas when there is snow</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>whiter than white</strong> completely morally good:</div><ul class=\"examples\"><li><em>He said that he had never claimed to be whiter than white.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[colour]</strong> <span class=\"gram\">[uncountable]</span> the colour of milk, salt, and snow</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>[people]</strong> (also White) <span class=\"gram\">[countable]</span> someone who belongs to the race of people with pale skin → black:</div><ul class=\"examples\"><li><em>The mayor is very popular among whites.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[wine]</strong> <span class=\"gram\">[countable, uncountable]</span> wine that is pale yellow in colour:</div><ul class=\"examples\"><li><em>a nice bottle of white</em></li><li><em>California has some of the finest whites in the world.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[eye]</strong> <span class=\"gram\">[countable + of]</span> the white part of your eye</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[egg]</strong> <span class=\"gram\">[countable, uncountable]</span> the part of an egg that surrounds the yolk (=yellow part) and becomes white when cooked</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>whites</strong> <span class=\"gram\">[plural]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> white clothes, sheets etc, which are separated from dark colours when they are washed</div><div class=\"subsense\"><span class=\"subnum\">b)</span> white clothes that are worn for some sports, such as tennis</div></div></div>","7697":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /huː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to ask or talk about which person is involved, or what the name of a person is:</div><ul class=\"examples\"><li><em>Who locked the door?</em></li><li><em>Who do you work for?</em></li><li><em>Who’s that guy with your wife?</em></li><li><em>They never found out who the murderer was.</em></li><li><em>She wondered who had sent the flowers.</em></li><li><strong><em>who to ask/contact/blame etc</strong>: He doesn’t know who to vote for.</em></li><li><strong><em>who on earth/in the world etc</strong> (=used for emphasis when you are surprised, angry etc): Who on earth would live in such a lonely place? / Who the hell are you?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used after a noun to show which person or which people you are talking about:</div><ul class=\"examples\"><li><em>Do you know the people who live over the road?</em></li><li><em>the woman who was driving</em></li><li><em>She was the one who did most of the talking.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used, after a comma in writing, to add more information about a particular person or group of people that you have just mentioned:</div><ul class=\"examples\"><li><em>I discussed it with my brother, who is a lawyer.</em></li><li><em>Alison Jones and her husband David, who live in Hartlepool, are celebrating their golden wedding anniversary.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>informal</em> used to introduce a question that shows you think something is true of everyone or of no one:</div><ul class=\"examples\"><li><em>We have the occasional argument. Who doesn’t (=everyone does)?</em></li><li><em>Who wants to come second (=no one does)?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>who is somebody to do something?</strong> <em>spoken</em> used to say that someone does not have the right or the authority to say or do something:</div><ul class=\"examples\"><li><em>Who is she to order me around?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>who’s who</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if you know who is who within a particular organization or group, you know what each person’s name is and what job they do or what position they have:</div><ul class=\"examples\"><li><em>I’m just getting to know who’s who in the department.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>a who’s who of something</strong> a list of the important people within a particular organization or group – often used to emphasize that many important people are involved in something:</div><ul class=\"examples\"><li><em>The list of competitors reads like a who’s who of international tennis players.</em></li></ul></div>","7698":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> who‧ev‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /huːˈevə $ -ˈevər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to say that it does not matter who does something, is in a particular place etc:</div><ul class=\"examples\"><li><em>I’ll take whoever wants to go.</em></li><li><em>When you’re done with the book, just give it to Kristin or Shelley or whoever.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to talk about a specific person or people, although you do not know who they are:</div><ul class=\"examples\"><li><em>Whoever is responsible for this will be punished.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>whoever he/she is</strong> (also whoever he/she may be) used to say that you do not know who someone is:</div><ul class=\"examples\"><li><em>You’ve got a message from Tony Gower, whoever he is.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used to mean ‘who’ at the beginning of a question to show surprise or anger:</div><ul class=\"examples\"><li><em>Whoever would do a thing like that to an old woman?</em></li></ul></div>","7699":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /həʊl $ hoʊl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[only before noun]</span> all of something <em>SYN entire</em>:</div><ul class=\"examples\"><li><em>You have your whole life ahead of you!</em></li><li><em>His whole attitude bugs me.</em></li><li><em>We ate the whole cake in about ten minutes.</em></li><li><em>The whole thing (=everything about the situation) just makes me sick.</em></li><li><em>We just sat around and watched TV the whole time (=the only thing we did was watch television).</em></li><li><em>I don’t believe she’s telling us the whole story (=all the facts).</em></li><li><em>It was months before the whole truth came out.</em></li><li><strong><em>the whole school/country/village etc</strong> (=all the people in a school, country etc): The whole town came out for the parade.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>whole lot</strong> <em>informal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <strong>a whole lot</strong> very much:</div><ul class=\"examples\"><li><em>I’m feeling a whole lot better.</em></li><li><em>I don’t cook a whole lot anymore.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>a whole lot (of something)</strong> a large quantity or number:</div><ul class=\"examples\"><li><em>We’re going to have a whole lot of problems if we don’t finish this by tomorrow.</em></li><li><em>You can find a nice house in this neighborhood, and you don’t have to spend a whole lot.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> <strong>the whole lot</strong> <em>especially British English</em> all of something:</div><ul class=\"examples\"><li><em>She gave me the whole lot for 20 pounds.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a whole range/series/variety etc (of something)</strong> used to emphasize that there are a lot of things of a similar type:</div><ul class=\"examples\"><li><em>There are a whole range of sizes to choose from.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> complete and not divided or broken into parts:</div><ul class=\"examples\"><li><em>Place a whole onion inside the chicken.</em></li><li><em>a snake swallowing a mouse whole (=swallowing it without chewing)</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>the whole point (of something)</strong> used to emphasize the purpose for doing something, especially when you believe this is unclear or has been forgotten:</div><ul class=\"examples\"><li><em>I thought the whole point of the meeting was to decide which offer to accept.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>in the whole (wide) world</strong> <em>informal</em> an expression meaning ‘anywhere’ or ‘at all’ – used to emphasize a statement:</div><ul class=\"examples\"><li><em>I have the best job in the whole wide world.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>go the whole hog</strong> (also go whole hog<em>American English</em>) <em>informal</em> to do something as completely or as well as you can, without any limits:</div><ul class=\"examples\"><li><em>I’m gonna go whole hog and have a live band at the barbecue.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>the whole nine yards</strong> <em>American English</em> <em>spoken</em> including everything that is typical of or possible in an activity, situation, set of things etc:</div><ul class=\"examples\"><li><em>Our new apartment complex has a tennis court, swimming pool, playground – the whole nine yards.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>the whole of something</strong> all of something, especially something that is not a physical object:</div><ul class=\"examples\"><li><em>The whole of the morning was wasted trying to find the documents.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>on the whole</strong> used to say that something is generally true:</div><ul class=\"examples\"><li><em>On the whole, I thought the film was pretty good.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>as a whole</strong> used to say that all the parts of something are being considered together:</div><ul class=\"examples\"><li><em>This project will be of great benefit to the region as a whole.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable usually singular]</span> something that consists of a number of parts, but is considered as a single unit:</div><ul class=\"examples\"><li><em>Two halves make a whole.</em></li></ul></div></div>","7700":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> whole‧sale</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈhəʊlseɪl $ ˈhoʊl-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the business of selling goods in large quantities at low prices to other businesses, rather than to the general public → retail</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> relating to the business of selling goods in large quantities at low prices to other businesses, rather than to the general public → retail:</div><ul class=\"examples\"><li><em>wholesale prices</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[usually before noun]</span> affecting almost everything or everyone, and often done without any concern for the results:</div><ul class=\"examples\"><li><em>the capture and wholesale destruction of a city</em></li><li><em>This company will not be successful until there are wholesale changes.</em></li></ul></div></div>","7701":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> whol‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈhəʊl-li $ ˈhoʊl-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">completely:</div><ul class=\"examples\"><li><em>a wholly satisfactory solution</em></li><li><em>The report claimed that the disaster was wholly unavoidable.</em></li></ul></div>","7702":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /huːm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W1</span></div><div class=\"entry-body\"><div class=\"sense\">the object form of ‘who’, used especially in formal speech or writing: RegisterIn everyday spoken or written English, people usually use who rather than whom:· Who did you send it to?Whom is usually used only in the phrases one of whom, none of whom, some of whom etc.</div><ul class=\"examples\"><li><em>Desperate for money, she called her sister, whom she hadn’t spoken to in 20 years.</em></li><li><em>She brought with her three friends, none of whom I had ever met before.</em></li></ul></div>","7703":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wʊps/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> said when someone has fallen, dropped something, or made a small mistake:</div><ul class=\"examples\"><li><em>Whoops! I nearly dropped it.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>whoops-a-daisy</strong> said when someone, usually a child, falls down</div></div>","7704":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /huːz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to ask which person or people a particular thing belongs to:</div><ul class=\"examples\"><li><em>Whose is this?</em></li><li><em>Whose keys are those?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to show the relationship between a person or thing and something that belongs to that person or thing:</div><ul class=\"examples\"><li><em>That’s the man whose house has burned down.</em></li><li><em>Solar energy is an idea whose time has come.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to give additional information about a person or thing:</div><ul class=\"examples\"><li><em>Jurors, whose identities will be kept secret, will be paid $40 a day.</em></li></ul></div>","7705":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /waɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to ask or talk about the reason for something:</div><ul class=\"examples\"><li><em>Why are you crying?</em></li><li><em>Why do we have to take all these tests?</em></li><li><em>‘She wants to meet you.’ ‘Why?’</em></li><li><em>‘I won’t be able to come into work tomorrow.’ ‘Why not?’</em></li><li><em>I have no idea why the television isn’t working.</em></li><li><em>Simon loves you – that’s why he wants to be with you.</em></li><li><em>He’s angry with me and I don’t know why.</em></li><li><em>There’s no reason why we shouldn’t be friends.</em></li><li><strong><em>why on earth/why ever etc</strong> (=used for emphasis when you are surprised, angry etc): Why on earth didn’t you ask me to help? / ‘I don’t want us to be seen together.’ ‘Why ever not?’</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to introduce a question that shows you do not think it is necessary to do something:</div><ul class=\"examples\"><li><em>Why worry? You can’t do anything about it.</em></li><li><em>Why waste time going to the bank when you can do it all over the Internet?</em></li></ul></div>","7706":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ˈwaɪ faɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">(wireless fidelity) a way of connecting computers or other electronic machines to a network by using radio signals rather than wires</div></div>","7707":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wick‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪkɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> behaving in a way that is morally wrong <em>SYN evil</em>: ► see thesaurus at unkind</div><ul class=\"examples\"><li><em>the wicked stepmother in ‘Hansel and Gretel’</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>informal</em> behaving badly in a way that is amusing:</div><ul class=\"examples\"><li><em>Carl had a wicked grin on his face as he crept up behind Ellen.</em></li><li><em>Tara hasn’t lost her wicked sense of humour.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>spoken</em> <em>informal</em> very good:</div><ul class=\"examples\"><li><em>That’s a wicked bike!</em></li></ul></div>","7708":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /waɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[distance]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> measuring a large distance from one side to the other <em>SYN broad</em> <em>OPP narrow</em>:</div><ul class=\"examples\"><li><em>a wide tree-lined road</em></li><li><em>a hat with a wide brim</em></li><li><strong><em>wide smile/grin</strong>: As he ran toward me, his face broke into a wide grin.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> measuring a particular distance from one side to the other:</div><ul class=\"examples\"><li><em>How wide is the door?</em></li><li><em>The boat was nearly as wide as the canal.</em></li><li><strong><em>five metres/two miles etc wide</strong>: The river is more than fifty yards wide.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[variety]</strong> <span class=\"gram\">[usually before noun]</span> including or involving a large variety of different people, things, or situations:</div><ul class=\"examples\"><li><em>a man with a wide experience of foreign affairs</em></li><li><em>Our aim is to bring classical music to a wider audience.</em></li><li><strong><em>a wide range/variety/choice etc (of something)</strong>: This year’s festival includes a wide range of entertainers. / holidays to a wide choice of destinations</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[in many places]</strong> <span class=\"gram\">[usually before noun]</span> happening among many people or in many places:</div><ul class=\"examples\"><li><em>The radio and newspapers gave the trial wide coverage.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>a wide variation/difference/gap etc</strong> a large and noticeable difference:</div><ul class=\"examples\"><li><em>the ever-wider gap between the richest and poorest countries</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>the wider context/issues/picture etc</strong> the more general features of a situation, rather than the specific details:</div><ul class=\"examples\"><li><em>We hope that by the end of the course students will be able to see their subject in a wider context.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[eyes]</strong> <em>literary</em> wide eyes are fully open, especially when someone is very surprised, excited, or frightened:</div><ul class=\"examples\"><li><em>Her eyes grew wide in anticipation.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>give somebody/something a wide berth</strong> to avoid someone or something</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>[not hit something]</strong> not hitting something you were aiming at</div><ul class=\"examples\"><li><strong><em>wide of</strong>: His shot was just wide of the goal.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>the (big) wide world</strong> <em>especially spoken</em> places outside the small familiar place where you live:</div><ul class=\"examples\"><li><em>Soon you’ll leave school and go out into the big wide world.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>nationwide/city-wide etc</strong> affecting all the people in a nation, city etc:</div><ul class=\"examples\"><li><em>a country-wide revolt against the government</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3 S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>wide open/awake/apart</strong> completely open, awake, or apart:</div><ul class=\"examples\"><li><em>Someone left the back door wide open.</em></li><li><em>At 2 a.m. I was still wide awake.</em></li><li><em>Sandy stood with his back to the fire, legs wide apart.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> opening or spreading as much as possible</div><ul class=\"examples\"><li><strong><em>open/spread (something) wide</strong>: Spiro spread his arms wide in a welcoming gesture. / Leonora’s eyes opened wide in horror. / The windows had been opened wide and she could feel a slight breeze.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>wide open</strong> if a competition, election etc is wide open, it is possible for anyone to succeed:</div><ul class=\"examples\"><li><em>Most experts agree that the election is wide open at this point.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> not hitting something you were aiming at, and missing it by a large distance:</div><ul class=\"examples\"><li><em>His throw to first base went wide.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>wide of the mark</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> not correct about something, by a large amount:</div><ul class=\"examples\"><li><em>The opinion polls were hopelessly wide of the mark.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> not hitting something you were aiming at, and missing it by a large distance:</div><ul class=\"examples\"><li><em>One of the bombs fell wide of the mark.</em></li></ul></div></div>","7709":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌwide-ˈranging</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">including a wide variety of subjects, things, or people:</div><ul class=\"examples\"><li><em>a wide-ranging discussion</em></li><li><em>wide-ranging proposals to improve the rail network</em></li></ul></div>","7710":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wide‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwaɪdli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in a lot of different places or by a lot of people:</div><ul class=\"examples\"><li><em>Organic food is now widely available.</em></li><li><em>an author who had travelled widely in the Far East</em></li><li><em>a widely used method</em></li><li><em>These laws were widely regarded as too strict.</em></li><li><em>This view was not widely held.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to a large degree – used when talking about differences:</div><ul class=\"examples\"><li><em>The quality of the applicants varies widely.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>widely read</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> read by a lot of people:</div><ul class=\"examples\"><li><em>a widely read magazine</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> having read many different books</div></div>","7711":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wid‧en</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwaɪdn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to become wider, or to make something wider <em>OPP narrow</em>:</div><ul class=\"examples\"><li><em>They’re widening the road.</em></li><li><em>The river widens and splits.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to become larger in degree or range, or to make something do this <em>OPP narrow</em>:</div><ul class=\"examples\"><li><em>The gap between income and expenditure has widened to 11%.</em></li><li><em>They are trying to widen the discussion to include environmental issues.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> if your eyes widen, they open more, especially because you are surprised or frightened <em>OPP narrow</em></div></div>","7712":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wide‧spread</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwaɪdspred/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\">existing or happening in many places or situations, or among many people: ► see thesaurus at common</div><ul class=\"examples\"><li><em>the widespread use of chemicals in agriculture</em></li><li><strong><em>widespread support/acceptance/criticism/condemnation etc</strong>: There was widespread support for the war. / The storm caused widespread damage.</em></li></ul></div>","7713":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wid‧ow</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪdəʊ $ -doʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a woman whose husband has died and who has not married again: ► see thesaurus at married</div><ul class=\"examples\"><li><em>an elderly widow who was attacked and robbed last month</em></li><li><em>a wealthy widow</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>football/golf etc widow</strong> a woman whose husband spends all his free time watching football, playing golf etc – used humorously</div></div>","7714":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɪdθ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the distance from one side of something to the other → breadth, length</div><ul class=\"examples\"><li><strong><em>width of</strong>: What’s the width of the desk?</em></li><li><strong><em>three feet/two metres etc in width</strong>: It’s about six metres in width.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>run/extend the (full) width of something</strong> to exist from one side of something to the other:</div><ul class=\"examples\"><li><em>a covered terrace extending the full width of the house</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> the distance from one side of a swimming pool to the other:</div><ul class=\"examples\"><li><em>I swam ten widths.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> a piece of cloth that has been measured and cut</div><ul class=\"examples\"><li><strong><em>width of</strong>: four widths of curtain material</em></li></ul></div>","7715":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wiːld/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>wield power/influence/authority etc</strong> to have a lot of power or influence, and to use it:</div><ul class=\"examples\"><li><em>The Church wields immense power in Ireland.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to hold a weapon or tool that you are going to use:</div><ul class=\"examples\"><li><em>She had her car windows smashed by a gang wielding baseball bats.</em></li></ul></div>","7716":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /waɪf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural wives /waɪvz/)</span></div><div class=\"entry-body\"><div class=\"sense\">the woman that a man is married to → husband, spouse: ► see thesaurus at married</div><ul class=\"examples\"><li><em>Have you met my wife?</em></li><li><em>a refuge for battered wives</em></li><li><em>his second wife</em></li><li><strong><em>ex-wife/former wife</strong>: He threatened to kill his ex-wife’s boyfriend.</em></li></ul></div>","7717":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɪɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">artificial hair that you wear on your head → toupée</div></div>","7718":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /waɪld/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[plants/animals]</strong> <span class=\"gram\">[usually before noun]</span> living in a natural state, not changed or controlled by people <em>OPP tame</em>:</div><ul class=\"examples\"><li><em>wild animals</em></li><li><em>a field full of wild flowers</em></li><li><strong><em>wild horse/dog/pig etc</em></strong></li><li><em>animals both wild and domesticated</em></li><li><strong><em>wild mushroom/garlic/rose etc</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[land]</strong> not used by people for farming, building etc:</div><ul class=\"examples\"><li><em>Nepal is stunning, with its wild, untamed landscape.</em></li><li><em>the wild and lonely Scottish hills</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[emotions]</strong> feeling or expressing strong uncontrolled emotions, especially anger, happiness, or excitement:</div><ul class=\"examples\"><li><em>wild laughter</em></li><li><strong><em>wild with</strong>: He was wild with rage.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[behaviour]</strong> behaving in an uncontrolled, sometimes violent way:</div><ul class=\"examples\"><li><em>She was completely wild in high school.</em></li><li><em>Donny could be wild and crazy.</em></li><li><em>There was a wild look about her (=she seemed a little crazy).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>go wild</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to behave in a very excited uncontrolled way:</div><ul class=\"examples\"><li><em>The crowd went wild as soon as the singer stepped onto the stage.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to get very angry:</div><ul class=\"examples\"><li><em>When Tony heard how much it was going to cost, he just went wild.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[enjoyable]</strong> <em>informal</em> very enjoyable and exciting:</div><ul class=\"examples\"><li><em>‘How was the party?’ ‘It was wild!’</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>be wild about something/somebody</strong> <em>informal</em> to like something or someone very much:</div><ul class=\"examples\"><li><em>My son’s wild about football.</em></li><li><em>I’m not that wild about rap music, to be honest.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[without careful thought]</strong> done or said without much thought or care, or without knowing all the facts:</div><ul class=\"examples\"><li><em>wild accusations</em></li><li><em>I’m just making a wild guess here, so correct me if I’m wrong.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>beyond somebody’s wildest dreams</strong> beyond anything that someone imagined or hoped for:</div><ul class=\"examples\"><li><em>an invention that was to change our lives beyond our wildest dreams</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>not/never in your wildest dreams</strong> used to say that you did not expect or imagine that something would happen, especially after it has happened:</div><ul class=\"examples\"><li><em>Never in my wildest dreams did I expect to win first place.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[weather/sea]</strong> violent and strong:</div><ul class=\"examples\"><li><em>a wild and angry sea</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[card games]</strong> a card that is wild can be used to represent any other card in a game</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>wild horses would/could not...</strong> used to say that someone is determined not to go somewhere, do something etc:</div><ul class=\"examples\"><li><em>Wild horses would not have dragged him into a vegetarian restaurant.</em></li></ul></div>","7719":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wil‧der‧ness</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪldənəs $ -dər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable usually singular]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a large area of land that has never been developed or farmed: ► see thesaurus at country</div><ul class=\"examples\"><li><em>the Alaskan wilderness</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a place that seems no longer used or cared for by anyone:</div><ul class=\"examples\"><li><em>The garden was a wilderness.</em></li><li><em>The south side of the city had become a lawless wilderness.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in/from/out of the wilderness</strong> someone who is in the wilderness does not have power or is not involved in something in an important way at a particular time:</div><ul class=\"examples\"><li><em>the re-emergence of Richard Nixon from the political wilderness in 1968</em></li></ul></div>","7720":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wild‧life</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwaɪldlaɪf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">animals and plants growing in natural conditions:</div><ul class=\"examples\"><li><em>measures to protect the area’s wildlife</em></li><li><em>the destruction of wildlife habitats</em></li></ul></div>","7721":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wild‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwaɪldli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in a very uncontrolled or excited way:</div><ul class=\"examples\"><li><em>The audience cheered wildly.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> extremely:</div><ul class=\"examples\"><li><em>The band is wildly popular in Cuba.</em></li><li><em>wildly inaccurate statements</em></li></ul></div>","7722":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">modal verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[future]</strong> used to make future tenses:</div><ul class=\"examples\"><li><em>A meeting will be held next Tuesday at 3 p.m.</em></li><li><em>What time will she arrive?</em></li><li><em>I hope they won’t be late.</em></li><li><em>Maybe by then you will have changed your mind.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[willing to do something]</strong> used to show that someone is willing or ready to do something:</div><ul class=\"examples\"><li><em>Dr Weir will see you now.</em></li><li><em>The baby won’t eat anything.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[requesting]</strong> <em>spoken</em> used to ask someone to do something:</div><ul class=\"examples\"><li><em>Will you phone me later?</em></li><li><em>Shut the door, will you?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[what generally happens]</strong> used to say what always happens in a particular situation or what is generally true:</div><ul class=\"examples\"><li><em>Oil will float on water.</em></li><li><em>Accidents will happen.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[possibility]</strong> used like ‘can’ to show what is possible:</div><ul class=\"examples\"><li><em>This car will hold five people comfortably.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[belief]</strong> used to say that you think something is true:</div><ul class=\"examples\"><li><em>That will be Tim coming home now.</em></li><li><em>As you will have noticed, there are some gaps in the data.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[giving orders]</strong> <em>spoken</em> used to give an order or to state a rule:</div><ul class=\"examples\"><li><em>Will you be quiet!</em></li><li><em>You will do as I say.</em></li><li><em>Every employee will carry an identity card at all times.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[offering/inviting]</strong> <em>spoken</em> used to offer something to someone or to invite them to do something:</div><ul class=\"examples\"><li><em>Will you have some more tea?</em></li><li><em>Won’t you have a seat?</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[annoying habit]</strong> <em>spoken</em> used to describe someone’s habits, especially when you think they are annoying:</div><ul class=\"examples\"><li><em>Trish will keep asking silly questions.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[determination]</strong> <span class=\"gram\">[countable, uncountable]</span> determination to do something that you have decided to do, even if this is difficult: → strong-willed, weak-willed</div><ul class=\"examples\"><li><em>Children sometimes have strong wills.</em></li><li><strong><em>the will to do something</strong>: Even though she was in terrible pain, Mary never lost the will to live.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[legal document]</strong> <span class=\"gram\">[countable]</span> a legal document that says who you want your money and property to be given to after you die:</div><ul class=\"examples\"><li><em>Have you made a will yet?</em></li><li><strong><em>in somebody’s will</strong>: My grandfather left me some money in his will.</em></li><li><em>the senator’s last will and testament</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[what somebody wants]</strong> <span class=\"gram\">[singular]</span> what someone wants to happen in a particular situation: → free will</div><ul class=\"examples\"><li><em>He accused her of trying to impose her will on others.</em></li><li><strong><em>against your will</strong>: Collier claims the police forced him to sign a confession against his will.</em></li><li><strong><em>will of</strong>: the will of the people</em></li><li><em>obedience to God’s will</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>with the best will in the world</strong> <em>British English</em> <em>spoken</em> used to say that something is not possible, even if you very much want to do it:</div><ul class=\"examples\"><li><em>With the best will in the world, I don’t see what more I can do.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>where there’s a will there’s a way</strong> <em>spoken</em> used to say that if you really want to do something, you will find a way to succeed</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>at will</strong> whenever you want and in whatever way you want:</div><ul class=\"examples\"><li><em>He can’t just fire people at will, can he?</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>with a will</strong> <em>written</em> in an eager and determined way</div></div></div>","7723":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> will‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪlɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[not before noun]</span> prepared to do something, or having no reason to not want to do it</div><ul class=\"examples\"><li><strong><em>willing to do something</strong>: How much are they willing to pay?</em></li><li><strong><em>quite/perfectly willing</strong>: I told them I was perfectly willing to help.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>willing helper/volunteer/partner etc</strong> someone who is eager to help etc and does not have to be persuaded:</div><ul class=\"examples\"><li><em>I soon had an army of willing helpers.</em></li></ul></div>","7724":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> will‧ing‧ness</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪlɪŋnəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the state of being prepared to do something:</div><ul class=\"examples\"><li><em>He has shown no willingness to compromise.</em></li></ul></div>","7725":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense and past participle won /wʌn/, present participle winning)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[competition/race]</strong> <span class=\"gram\">[intransitive, transitive]</span> to be the best or most successful in a competition, game, election etc <em>OPP lose</em></div><ul class=\"examples\"><li><strong><em>win a race/a game/an election etc</strong>: Who do you think will win the next election? / He won the Tour de France last year.</em></li><li><strong><em>win a war/battle</strong>: the young pilots who won the Battle of Britain</em></li><li><em>Who’s winning (=who is most successful at this point in the game)?</em></li><li><strong><em>win at</strong>: I never win at cards.</em></li><li><strong><em>win by 10 points/70 metres etc</strong>: We won by just one point.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[prize]</strong> <span class=\"gram\">[transitive]</span> to get something as a prize for winning in a competition or game:</div><ul class=\"examples\"><li><em>How does it feel to have won the gold medal?</em></li><li><em>She won £160 on the lottery.</em></li><li><strong><em>win something for somebody</strong>: the man who helped win the Cup for Arsenal</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[get/achieve]</strong> <span class=\"gram\">[transitive]</span> to get something that you want because of your efforts or abilities <em>SYN gain</em></div><ul class=\"examples\"><li><strong><em>win somebody’s approval/support/trust etc</strong>: The proposal has won the approval of the city council. / Kramer has certainly won the respect of his peers.</em></li><li><strong><em>win somebody’s heart</strong> (=make them love you or feel sympathy for you)</em></li><li><em>The company has won a contract to build a new power plant outside Houston.</em></li><li><strong><em>win something from somebody</strong>: Davis hopes to win financial backing from a London investment firm.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[make somebody win something]</strong> <span class=\"gram\">[transitive]</span> if something, usually something that you do, wins you something, you win it or get it because of that thing</div><ul class=\"examples\"><li><strong><em>win somebody something</strong>: That performance won Hanks an Oscar. / That kind of behaviour won’t win you any friends.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>you win</strong> <em>spoken</em> used to agree to what someone wants after you have tried to persuade them to do something else:</div><ul class=\"examples\"><li><em>OK, you win – we’ll go to the movies.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>you can’t win</strong> <em>spoken</em> used to say that there is no satisfactory way of dealing with a particular situation:</div><ul class=\"examples\"><li><em>You can’t win, can you? You either work late and upset your family, or go home early and risk your job.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>you can’t win them all</strong> (also you win some, you lose some) <em>spoken</em> used to show sympathy when someone has had a disappointing experience</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>win or lose</strong> <em>informal</em> no matter whether you win or lose:</div><ul class=\"examples\"><li><em>Win or lose, I love competitive sports.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>win the day</strong> to finally be successful in a discussion or argument <em>SYN triumph</em>:</div><ul class=\"examples\"><li><em>Common sense won the day, and the plans were dropped.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a success or victory, especially in sport <em>OPP defeat</em>: ► see thesaurus at victory</div><ul class=\"examples\"><li><em>We’ve had two wins so far this season.</em></li><li><strong><em>win over</strong>: In the under-16 event England had their first win over Germany.</em></li></ul></div></div>","7726":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɪnd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[air]</strong> (also the wind) <span class=\"gram\">[countable, uncountable]</span> moving air, especially when it moves strongly or quickly in a current → windy: → crosswind, downwind, headwind, tailwind, trade wind, upwind</div><ul class=\"examples\"><li><em>The wind blew from the northeast.</em></li><li><em>Planes were unable to take off because of high winds.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>get/have wind of something</strong> <em>informal</em> to hear or find out about something secret or private:</div><ul class=\"examples\"><li><em>You’d better hope the press doesn’t get wind of this.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[breath]</strong> <span class=\"gram\">[uncountable]</span> your ability to breathe normally → second wind at second1(12), → windpipe</div><ul class=\"examples\"><li><strong><em>get your wind (back)</strong> (=be able to breathe normally again, for example after running)</em></li><li><strong><em>knock the wind out of somebody</strong> (=hit someone in the stomach so that they cannot breathe for a moment)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[in your stomach]</strong> <span class=\"gram\">[uncountable]</span> <em>British English</em> the condition of having air or gas in your stomach or intestines, or the air or gas itself SYN gas<em>American English</em>:</div><ul class=\"examples\"><li><em>I can’t drink beer – it gives me wind.</em></li><li><em>‘What’s wrong with the baby?’ ‘Just a little wind.’</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>take the wind out of somebody’s sails</strong> <em>informal</em> to make someone lose their confidence, especially by saying or doing something unexpected</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>see which way the wind is blowing</strong> to find out what the situation is before you do something or make a decision</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>something is in the wind</strong> used to say that something is happening or going to happen, but the details are not clear:</div><ul class=\"examples\"><li><em>If there was a merger in the wind, I’m sure we’d hear about it.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>winds of change/freedom/public opinion etc</strong> used to refer to things that have important effects, and that cannot be stopped:</div><ul class=\"examples\"><li><em>The winds of change are blowing through the entire organization.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>put the wind up somebody/get the wind up</strong> <em>British English</em> <em>informal</em> if you put the wind up someone, you make them feel anxious or frightened. If you get the wind up, you become anxious or frightened:</div><ul class=\"examples\"><li><em>The threat of legal action will be enough to put the wind up them.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[music]</strong> <strong>the winds/the wind section</strong> the people in an orchestra or band who play musical instruments that you blow through, such as a flute</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>like the wind</strong> if someone or something moves or runs like the wind, they move or run very quickly:</div><ul class=\"examples\"><li><em>She ran like the wind down the stairs to escape.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[talk]</strong> <span class=\"gram\">[uncountable]</span> <em>British English</em> <em>informal</em> talk that does not mean anything</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /waɪnd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\">(past tense and past participle wound /waʊnd/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive always + adverb/preposition]</span> to turn or twist something several times around something else</div><ul class=\"examples\"><li><strong><em>wind something around/round something</strong>: The hair is divided into sections and wound around heated rods.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> (also wind up) to turn part of a machine around several times, in order to make it move or start working:</div><ul class=\"examples\"><li><em>Did you remember to wind the clock?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> if a road, river etc winds somewhere, it has many smooth bends and is usually very long</div><ul class=\"examples\"><li><strong><em>wind (its way) through/along etc something</strong>: Highway 99 winds its way along the coast.</em></li><li><em>a winding path</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> to make a tape move in a machine</div><ul class=\"examples\"><li><strong><em>wind something forward/back</strong>: Can you wind the video back a little way – I want to see that bit again.</em></li></ul></div></div>","7727":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> win‧dow</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪndəʊ $ -doʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a space or an area of glass in the wall of a building or vehicle that lets in light → bay window, dormer, French windows, picture window, sash window</div><ul class=\"examples\"><li><strong><em>open/close/shut a window</strong>: Do you mind if I open the window?</em></li><li><strong><em>out of/from/through the window</strong>: She looked out of the window to see if it was raining. / The sun was shining through the windows.</em></li><li><strong><em>in the window</strong> (=just inside a window): We were looking at the Christmas displays in the shop windows.</em></li><li><strong><em>bedroom/kitchen etc window</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> one of the separate areas on a computer screen where different programs are operating</div><div class=\"sense\"><span class=\"snum\">3</span> (also window of opportunity) a short period of time that is available for a particular activity:</div><ul class=\"examples\"><li><em>Delay might open a window of opportunity for their rivals.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> an area on an envelope with clear plastic in it which lets you see the address written on the letter inside the envelope</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>a window on/to the world</strong> something that makes it possible to see and learn about what is happening in other parts of the world:</div><ul class=\"examples\"><li><em>Television provides us with a useful window on the world.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>go out (of) the window</strong> <em>informal</em> to disappear completely or no longer have any effect:</div><ul class=\"examples\"><li><em>One glass of wine, and all my good intentions went out the window.</em></li></ul></div>","7728":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wind‧screen</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪndskriːn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>British English</em> the large window at the front of a car, bus etc SYN windshield<em>American English</em></div></div>","7729":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wind‧shield</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪndʃiːld/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>American English</em> a windscreen</div><div class=\"sense\"><span class=\"snum\">2</span> a piece of glass or clear plastic fixed at the front of a motorcycle that protects the rider from wind</div></div>","7730":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wind‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪndi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\">(comparative windier, superlative windiest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if it is windy, there is a lot of wind:</div><ul class=\"examples\"><li><em>It’s too windy for a picnic.</em></li><li><em>a cold, windy day</em></li><li><em>a windy hillside</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> windy talk is full of words that sound impressive but do not mean much:</div><ul class=\"examples\"><li><em>politicians’ windy generalizations</em></li></ul></div>","7731":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /waɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an alcoholic drink made from grapes, or a type of this drink:</div><ul class=\"examples\"><li><em>a glass of wine</em></li><li><strong><em>red/white wine</strong>: a bottle of red wine</em></li><li><strong><em>dry/sweet/sparkling wine</strong>: a dry white wine</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an alcoholic drink made from another fruit or plant:</div><ul class=\"examples\"><li><em>damson wine</em></li></ul></div>","7732":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[bird/insect]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> one of the parts of a bird’s or insect’s body that it uses for flying:</div><ul class=\"examples\"><li><em>a butterfly with beautiful markings on its wings</em></li><li><em>The pheasant flapped its wings vigorously.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the meat on the wing bone of a chicken, duck etc, eaten as food:</div><ul class=\"examples\"><li><em>spicy chicken wings</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[plane]</strong> one of the large flat parts that stick out from the side of a plane and help to keep it in the air</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>[building]</strong> one of the parts of a large building, especially one that sticks out from the main part</div><ul class=\"examples\"><li><strong><em>north/east etc wing</strong>: the east wing of the palace</em></li><li><em>She works in the hospital’s maternity wing.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[politics]</strong> a group of people within a political party or other organization who have a particular opinion or aim: → left-wing, right-wing</div><ul class=\"examples\"><li><em>the moderate wing of the Republican Party</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[sport]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a winger</div><div class=\"subsense\"><span class=\"subnum\">b)</span> the far left or right part of a sports field</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[car]</strong> <em>British English</em> the part of a car that is above a wheel SYN fender<em>American English</em></div><div class=\"sense\"><span class=\"snum\">7</span> <strong>take somebody under your wing</strong> to help and protect someone who is younger or less experienced than you are</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>(waiting/lurking) in the wings</strong> ready to do something or be used when the time is right:</div><ul class=\"examples\"><li><em>Several junior managers are waiting in the wings for promotion.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[theatre]</strong> <strong>the wings</strong> <span class=\"gram\">[plural]</span> the parts at each side of a stage where actors are hidden from people who are watching the play</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>on a wing and a prayer</strong> if you do something on a wing and a prayer, you do not have much chance of succeeding</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>be on the wing</strong> <em>literary</em> if a bird is on the wing, it is flying</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>take wing</strong> <em>literary</em> to fly away</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>get your wings</strong> to pass the examinations you need to become a pilot → clip somebody’s wings at clip2(6), → spread your wings at spread1(10)</div></div>","7733":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɪŋk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to close and open one eye quickly to communicate something or show that something is a secret or joke</div><ul class=\"examples\"><li><strong><em>wink at</strong>: He winked mischievously at Erica.</em></li><li><em>He winked an eye at his companion.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> to shine with a light that flashes on and off <em>SYN blink</em>:</div><ul class=\"examples\"><li><em>a Christmas tree with lights winking on and off</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a quick action of closing and opening one eye, usually as a signal to someone else:</div><ul class=\"examples\"><li><em>He gave her a wink.</em></li><li><em>‘You look tired,’ he said with a knowing wink.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>not get a wink of sleep/not sleep a wink</strong> not be able to sleep at all:</div><ul class=\"examples\"><li><em>I didn’t get a wink of sleep last night.</em></li></ul></div></div>","7734":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> win‧ner</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪnə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a person or animal that has won something <em>OPP loser</em></div><ul class=\"examples\"><li><strong><em>winner of</strong>: the winner of the Ladies’ Championship</em></li><li><em>Five lucky winners will each receive a signed copy of the album.</em></li><li><em>As a jockey he rode 10 winners.</em></li><li><strong><em>prize/award/medal etc winner</strong>: a Nobel prize winner</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> <em>informal</em> someone or something that is or is likely to be very popular and successful:</div><ul class=\"examples\"><li><em>The book has proved to be a winner with young children.</em></li><li><em>The company seems to be onto a winner (=doing something that is likely to be successful).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[singular]</span> a goal or point that makes someone win a game such as football or tennis:</div><ul class=\"examples\"><li><em>Moran scored the winner with only two minutes left.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable usually plural]</span> the person who gets most of the advantages from a situation <em>OPP loser</em>:</div><ul class=\"examples\"><li><em>In a capitalist society there will always be winners and losers.</em></li><li><em>The real winners this summer have been the sun cream manufacturers.</em></li></ul></div>","7735":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> win‧ning</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪnɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the winning person or thing is the one that wins or makes you win a competition or game:</div><ul class=\"examples\"><li><em>the winning team</em></li><li><em>The winning design came from an architect in Glasgow.</em></li><li><em>Beckham scored the winning goal.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> making you very successful or likely to be successful:</div><ul class=\"examples\"><li><em>a winning combination</em></li><li><em>As a business, they have found a winning formula.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a winning quality or way of doing something is one that makes other people like you <em>SYN attractive</em>:</div><ul class=\"examples\"><li><em>a winning smile</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>a winning streak</strong> a period of time when you win every game or competition:</div><ul class=\"examples\"><li><em>The team are on a winning streak.</em></li></ul></div>","7736":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> win‧ter</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪntə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the season after autumn and before spring, when the weather is coldest → summer:</div><ul class=\"examples\"><li><em>Soon it will be winter.</em></li><li><strong><em>in (the) winter</strong>: It usually snows here in the winter.</em></li><li><strong><em>this/last/next winter</strong>: Fuel supplies could be seriously disrupted this winter.</em></li></ul></div>","7737":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /waɪp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[clean/rub]</strong> <span class=\"gram\">[transitive]</span> ► see thesaurus at clean</div><ul class=\"examples\"><li><strong><em>wipe something on something</strong>: He wiped his mouth on the back of his hand.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">a)</span> to rub a surface with something in order to remove dirt, liquid etc</div><ul class=\"examples\"><li><strong><em>wipe something with something</strong>: Wipe the table with a damp cloth.</em></li><li><em>Bill wiped his eyes (=wiped the tears from his face) and apologized.</em></li><li><em>He pulled a handkerchief from his pocket and wiped his nose.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to clean something by rubbing it against a surface</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>[remove dirt]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to remove liquid, dirt, or marks by wiping</div><ul class=\"examples\"><li><strong><em>wipe something off/from etc something</strong>: Kim wiped the sweat from her face.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[computer/tape]</strong> <span class=\"gram\">[transitive]</span> to remove all the information that is stored on a tape, video, or computer disk</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>wipe something from your mind/memory</strong> to try to forget an unpleasant experience</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>wipe the floor with somebody</strong> <em>informal</em> to defeat someone completely in a competition or argument</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>wipe the slate clean</strong> to agree to forget about mistakes or arguments that happened in the past</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>wipe the smile/grin off somebody’s face</strong> <em>informal</em> to make someone feel less happy or confident, especially someone who is annoying because they think they are clever:</div><ul class=\"examples\"><li><em>Tell him how much it’ll cost – that should wipe the smile off his face!</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>wipe something off the face of the earth/wipe something off the map</strong> to destroy something completely:</div><ul class=\"examples\"><li><em>Another few years and this species could be wiped off the face of the earth.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[plates/cups etc]</strong> <span class=\"gram\">[intransitive, transitive]</span> to dry plates, cups etc that have been washed <em>SYN dry</em>:</div><ul class=\"examples\"><li><em>You wash, I’ll wipe.</em></li></ul></div>","7738":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /waɪə $ waɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> thin metal in the form of a thread, or a piece of this: → barbed wire, high wire, tripwire</div><ul class=\"examples\"><li><em>copper wire</em></li><li><em>a wire fence</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a piece of metal like this, used for carrying electrical currents or signals:</div><ul class=\"examples\"><li><em>a telephone wire</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>get your wires crossed</strong> to become confused about what someone is saying because you think they are talking about something else</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>go/come/be down to the wire</strong> <em>informal</em> <em>especially American English</em> to be finished or achieved with very little time left:</div><ul class=\"examples\"><li><em>The game was very close and went right down to the wire.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> <em>American English</em> a piece of electronic recording equipment, usually worn secretly on someone’s clothes</div><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[countable]</span> <em>American English</em> a telegram</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (also wire up)</div><div class=\"subsense\"><span class=\"subnum\">a)</span> to connect wires inside a building or piece of equipment so that electricity can pass through:</div><ul class=\"examples\"><li><em>Check that the plug has been wired up properly.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to connect electrical equipment to the electrical system using wires</div><ul class=\"examples\"><li><strong><em>wire something to something</strong>: The CD player had been wired up to the car’s cigarette lighter.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to send money electronically</div><div class=\"sense\"><span class=\"snum\">3</span> to attach a piece of recording equipment to a person or room, especially secretly</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>be wired for something</strong> to have all the necessary wires and connections for an electrical system to work:</div><ul class=\"examples\"><li><em>All the rooms have been wired for cable TV.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>American English</em> to send a telegram to someone</div><div class=\"sense\"><span class=\"snum\">6</span> to fasten two or more things together using wire</div><ul class=\"examples\"><li><strong><em>wire something together</strong>: The poles had all been wired together.</em></li></ul></div></div>","7739":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wire‧less</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwaɪələs $ ˈwaɪr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">relating to a system of communications that does not use electrical or telephone wires:</div><ul class=\"examples\"><li><em>wireless Internet connections</em></li></ul></div>","7740":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wis‧dom</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪzdəm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> good sense and judgment, based especially on your experience of life: → pearls of wisdom at pearl(3)</div><ul class=\"examples\"><li><em>a man of great wisdom</em></li><li><strong><em>question/doubt the wisdom of (doing) something</strong>: Local people are questioning the wisdom of spending so much money on a new road.</em></li><li><em>You can always expect a few words of wisdom from Dave.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> knowledge gained over a long period of time through learning or experience: ► see thesaurus at knowledge</div><ul class=\"examples\"><li><em>the collected wisdom of many centuries</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>(the) conventional/received/traditional etc wisdom</strong> a belief or opinion that most people have:</div><ul class=\"examples\"><li><em>The conventional wisdom is that boys mature more slowly than girls.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>in somebody’s (infinite) wisdom</strong> <em>humorous</em> used to say that you do not understand why someone has decided to do something:</div><ul class=\"examples\"><li><em>The boss, in her infinite wisdom, has decided to reorganize the whole office yet again.</em></li></ul></div>","7741":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /waɪz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[decision/idea etc]</strong> wise decisions and actions are sensible and based on good judgment <em>SYN sensible</em></div><ul class=\"examples\"><li><strong><em>it is wise to do something</strong>: It’s wise to check whether the flight times have changed before you leave for the airport.</em></li><li><strong><em>be wise to do something</strong>: I think you were wise to leave when you did.</em></li><li><em>a wise precaution</em></li><li><em>I don’t think that would be a very wise move (=not be a sensible thing to do).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[person]</strong> someone who is wise makes good decisions, gives good advice etc, especially because they have a lot of experience of life: ► see thesaurus at intelligent</div><ul class=\"examples\"><li><em>a wise old man</em></li><li><em>At the time I thought he was wonderful, but I’m older and wiser now.</em></li><li><em>As a manager, Sanford was wise in the ways of (=knew a lot about) company politics.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be none the wiser/not be any the wiser</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to not understand something even after it has been explained to you:</div><ul class=\"examples\"><li><em>Charlie explained how the system works, but I’m still none the wiser.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used for saying that no one will find out about something bad that someone has done:</div><ul class=\"examples\"><li><em>He could easily have taken the money and no one would have been any the wiser.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>get/be wise to somebody/something</strong> <em>informal</em> to realize that someone is being dishonest: → wise up at wise2</div><ul class=\"examples\"><li><em>Teachers quickly get wise to students who are cheating.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>wise guy</strong> <em>informal especially</em> <em>American English</em> an annoying person who thinks they know more than they really do:</div><ul class=\"examples\"><li><em>OK, wise guy, shut up and listen!</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be wise after the event</strong> to realize what you should have done in a situation after it has happened:</div><ul class=\"examples\"><li><em>It’s easy to be wise after the event.</em></li></ul></div>","7742":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɪʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> <em>formal</em> if you wish to do something or you wish to have it done for you, you want to do it or want to have it done <em>SYN like</em> RegisterIn everyday English, people usually say want rather than wish:· I want to see the manager.· You can go, if you want.</div><ul class=\"examples\"><li><strong><em>wish to do something</strong>: I wish to make a complaint. / If you wish to discuss this matter further please do not hesitate to contact me.</em></li><li><em>You may leave now, if you wish.</em></li><li><strong><em>(just) as you wish</strong> (=used in formal situations to tell someone you will do what they want): ‘I’d like it to be ready by six.’ ‘Just as you wish, sir.’</em></li><li><em>The cook will prepare whatever you wish.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to want something to be true although you know it is either impossible or unlikely → if only GRAMMAR: Patterns with wish• You wish that you could do something: · I wish I could speak Spanish. ✗Don’t say: I wish I can speak Spanish.• You wish that something would happen: · I wish it would stop raining.· I wish you wouldn’t do that.• You wish that you had done something: · I wish I had paid more attention in class.· She wished she hadn’t said that she was bored.• You wish that you could have done something: · I wish I could have seen his face!• In everyday spoken English, you say I wish I was: · I wish I was back home in Hong Kong.• In more formal English, especially in American English, you use I wish I were: · I wish I were back home in Hong Kong.• I wish I were is often used when talking about things that are impossible: · I wish I were you!· I wish I were younger.Grammar guide ‒ VERBS</div><ul class=\"examples\"><li><strong><em>wish (that)</strong>: I wish I didn’t have to go to work today. / I wish that I could afford a new car. / He wished Emily were with him. / Sometimes I wish I had never been born.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to say that you hope someone will have good luck, a happy life etc</div><ul class=\"examples\"><li><strong><em>wish somebody something</strong>: We wish you a Merry Christmas and a Happy New Year! / We wish them every happiness in their new home. / He shook my hand and wished me luck.</em></li><li><strong><em>wish somebody well</strong> (=say that you hope that good things will happen to someone): My friends wished me well in my new job.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>I couldn’t wish for a nicer/better etc...</strong> (also the nicest/best etc... I could have wished for) used to emphasize that you are very happy with what you have and cannot imagine anyone or anything better:</div><ul class=\"examples\"><li><em>I couldn’t wish for a better husband.</em></li><li><em>It’s the best birthday present I could have wished for.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>I wish (that) somebody would do something</strong> <em>spoken</em> used to say that you find someone’s behaviour annoying and want them to change:</div><ul class=\"examples\"><li><em>I wish you’d stop treating me like a child!</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[intransitive]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to want something to happen or to want to have something, especially when it seems unlikely or impossible → long for</div><ul class=\"examples\"><li><strong><em>wish for</strong>: It was no use wishing for the impossible. / She was like the sister I never had but always wished for.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to silently ask for something you want and hope that it will happen by magic or good luck – used especially in children’s stories</div><ul class=\"examples\"><li><strong><em>wish for</strong>: One day she found a magic ring that brought her whatever she wished for.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>I wish!</strong> <em>spoken</em> used to say that something is not true, but you wish it was:</div><ul class=\"examples\"><li><em>‘I think he really likes you.’ ‘I wish!’</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>you wish!</strong> <em>spoken</em> used to tell someone that what they want to happen or be true will definitely not happen or become true:</div><ul class=\"examples\"><li><em>‘I’m going to be famous one day.’ ‘You wish!’</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>wouldn’t wish something on/upon somebody</strong> <em>spoken</em> used to say that something is very unpleasant and that you would not like anyone to have to experience it:</div><ul class=\"examples\"><li><em>Having your house broken into is terrible. I wouldn’t wish it on anybody.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>I don’t wish to interfere/be nosy etc</strong> <em>British English</em> <em>spoken</em> <em>formal</em> used to show you are sorry if what you are going to say upsets or annoys someone:</div><ul class=\"examples\"><li><em>I don’t wish to seem ungrateful, but it’s not quite what I expected.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>I (only) wish I knew</strong> <em>British English</em> <em>spoken</em> used to emphasize that you do not know something, and you wish you did know:</div><ul class=\"examples\"><li><em>‘Where on earth have they gone?’ ‘I wish I knew!’</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a desire to do something, to have something, or to have something happen → death wish</div><ul class=\"examples\"><li><strong><em>wish of</strong>: It’s important to listen to the wishes of the patient.</em></li><li><strong><em>wish to do something</strong>: Despite her wish to continue working, she was forced to retire at the age of 62.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a silent request for something to happen as if by magic:</div><ul class=\"examples\"><li><em>Close your eyes and make a wish.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>against somebody’s wishes</strong> if you do something against someone’s wishes, you do it even though you know they do not want you to:</div><ul class=\"examples\"><li><em>She’d left school against her mother’s wishes.</em></li><li><strong><em>go against somebody’s wishes</strong> (=do something against their wishes)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>best/good/warmest etc wishes</strong> used, especially in cards and letters, to say that you hope someone will be happy, successful, or healthy</div><ul class=\"examples\"><li><strong><em>wish for</strong>: Best wishes for a long and happy retirement!</em></li><li><em>She asked me to pass on her good wishes to all her friends and colleagues.</em></li><li><strong><em>(With) best wishes</strong> (=used at the end of a letter before you sign your name): With best wishes, Celia.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>have no wish to do something</strong> <em>formal</em> used to emphasize that you do not want or intend to do something:</div><ul class=\"examples\"><li><em>I have no wish to speak to her ever again.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>your wish is my command</strong> used humorously to say that you will do whatever someone asks you to do</div></div></div>","7743":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[amusing]</strong> <span class=\"gram\">[uncountable]</span> the ability to say things that are clever and amusing:</div><ul class=\"examples\"><li><em>a woman of great wit and charm</em></li><li><strong><em>quick/dry/sharp etc wit</strong>: His sharp wit had them all smiling.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[amusing person]</strong> <span class=\"gram\">[countable]</span> someone who is able to say clever and amusing things</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>wits</strong> <span class=\"gram\">[plural]</span> your ability to think quickly and make the right decisions:</div><ul class=\"examples\"><li><em>Alone and penniless, I was forced to live on my wits.</em></li><li><strong><em>keep/have your wits about you</strong> (=be ready to think quickly and do what is necessary in a difficult situation)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>frighten/scare/terrify somebody out of their wits</strong> <em>informal</em> to frighten someone very much:</div><ul class=\"examples\"><li><em>I was terrified out of my wits at the very idea.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>gather/collect/recover etc your wits</strong> to make yourself think about what you are going to do next after you have been surprised by something:</div><ul class=\"examples\"><li><em>I felt helpless, but tried to gather my wits.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>pit your wits against somebody</strong> to compete against someone in a test of knowledge or intelligence</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>be at your wits’ end</strong> to be very upset and not know what to do, because you have tried everything possible to solve a problem</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>have the wit to do something</strong> <em>formal</em> to be clever enough to know the right thing to do:</div><ul class=\"examples\"><li><em>Thankfully, Reid had the wit to see what was wrong with the plan.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>not be beyond the wit of somebody</strong> <em>formal</em> not be too difficult for someone to do:</div><ul class=\"examples\"><li><em>It’s surely not beyond the wit of man to come up with a solution.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>to wit</strong> <em>old use or</em> <em>formal</em> used to introduce additional information which makes it clear exactly who or what you are talking about <em>SYN namely</em>:</div><ul class=\"examples\"><li><em>This does not stop me giving you a little treat. To wit, an invitation to dine at Brown’s.</em></li></ul></div>","7744":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɪtʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a woman who is supposed to have magic powers, especially to do bad things → wizard</div><div class=\"sense\"><span class=\"snum\">2</span> <em>informal</em> an insulting word for a woman who is old or unpleasant</div></div>","7745":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɪð, wɪθ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to say that two or more people or things are together in the same place:</div><ul class=\"examples\"><li><em>I saw Bob in town with his girlfriend.</em></li><li><em>Put this bag with the others.</em></li><li><em>I always wear these shoes with this dress.</em></li><li><em>Mix the powder with boiling water.</em></li><li><strong><em>have/bring/take somebody/something with you</strong>: She had her husband with her. / You’d better bring your passport with you.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> having, possessing, or carrying something:</div><ul class=\"examples\"><li><em>a tall gentleman with a beard</em></li><li><em>a book with a green cover</em></li><li><em>a man with a gun</em></li><li><em>We need someone with new ideas.</em></li><li><em>Only people with plenty of money can afford to shop here.</em></li><li><em>She came back with a letter in her hand.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> using something or by means of something:</div><ul class=\"examples\"><li><em>Chop the onions with a sharp knife.</em></li><li><em>What will you buy with the money?</em></li><li><em>I amused myself with crossword puzzles.</em></li><li><em>a hat decorated with brightly coloured feathers</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> because of a particular feeling or physical state:</div><ul class=\"examples\"><li><em>They were trembling with fear.</em></li><li><em>Jack beamed with pleasure when he heard the news.</em></li><li><em>I was too weak with hunger to cry.</em></li><li><em>Mother became seriously ill with pneumonia.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> including:</div><ul class=\"examples\"><li><em>Two nights’ accommodation with breakfast and evening meal cost us just over £250.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> used to say what covers or fills something:</div><ul class=\"examples\"><li><em>Her boots were covered with mud.</em></li><li><em>Fill the bowl with sugar.</em></li><li><em>In summer Venice is crammed with tourists.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> used to say what an action or situation is related to:</div><ul class=\"examples\"><li><em>We have a problem with parking in this area.</em></li><li><em>Be careful with that glass.</em></li><li><em>Is there something wrong with your phone?</em></li><li><em>How are you getting on with your studies, David?</em></li><li><em>Compared with other children of the same age, Robert is very tall.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> used to say which person or thing someone has a particular feeling or attitude towards:</div><ul class=\"examples\"><li><em>I hope you’re not angry with me.</em></li><li><em>He thinks he’s in love with Diana.</em></li><li><em>She’s delighted with her new car.</em></li><li><em>Don’t get too friendly with your students.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> supporting someone or sharing their opinion → for:</div><ul class=\"examples\"><li><em>Some opposition MPs voted with the Government.</em></li><li><em>You’re either with me or against me.</em></li><li><em>I’m with Harry all the way on this one.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> used when talking about an action or activity to say which other person, group, or country is involved:</div><ul class=\"examples\"><li><em>Stop fighting with your brother!</em></li><li><em>I used to play chess with him.</em></li><li><em>It’s a good idea to discuss the problem with a sympathetic teacher.</em></li><li><em>We’re competing with foreign businesses.</em></li><li><em>Britain’s trade with Japan</em></li><li><em>She left home after an argument with her parents.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> used to say how someone does something or how something happens:</div><ul class=\"examples\"><li><em>He prepared everything with great care.</em></li><li><em>A rocket exploded with a blinding flash.</em></li><li><em>‘Oh, I’m not in a hurry,’ I said with a smile.</em></li><li><em>The day starts with a great American breakfast.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> used to say what position or state someone or something is in, or what is happening, when someone does something:</div><ul class=\"examples\"><li><em>She stood with her back to me.</em></li><li><em>We lay in bed with the window open.</em></li><li><em>She was knitting, with the television on.</em></li><li><strong><em>with somebody/something doing something</strong>: We jumped into the water with bullets whizzing past our ears.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> at the same rate as something else and because of it:</div><ul class=\"examples\"><li><em>a skill which improves with practice</em></li><li><em>The risk of cancer increases with the number of cigarettes you smoke.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> because of a situation that exists:</div><ul class=\"examples\"><li><em>With John away there’s more room in the house.</em></li><li><strong><em>with something doing something</strong>: I can’t do my homework with all this noise going on.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> employed by someone:</div><ul class=\"examples\"><li><em>The manager is Stuart Walker, who has been with the company since 1970.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> used to say who is looking after something:</div><ul class=\"examples\"><li><em>I left your keys with the janitor.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> used to say who or what someone becomes separated from:</div><ul class=\"examples\"><li><em>Joan doesn’t want to part with the money.</em></li><li><em>a complete break with tradition</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> in the same direction as something:</div><ul class=\"examples\"><li><em>We sailed with the wind.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> in spite of:</div><ul class=\"examples\"><li><em>With all his faults, I still like him.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> used to show who or what a strong wish or order concerns:</div><ul class=\"examples\"><li><em>Down with school!</em></li><li><em>Off to bed with you!</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>be with you/me</strong> to understand what someone is telling you or explaining to you:</div><ul class=\"examples\"><li><em>Sorry, I’m not with you – which room do you mean?</em></li><li><em>So that’s how the system works. Are you with me?</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>with it</strong> <em>informal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> wearing fashionable clothes and knowing about new ideas <em>SYN trendy</em></div><div class=\"subsense\"><span class=\"subnum\">b)</span> able to understand clearly what is happening around you: → with-it</div><ul class=\"examples\"><li><em>I’m sorry, I’m not feeling very with it today.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>with that</strong> immediately after doing or saying something:</div><ul class=\"examples\"><li><em>He gave a little wave and with that he was gone.</em></li></ul></div>","7746":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> with‧draw</span><span class=\"meta-item\"><strong>IPA:</strong> /wɪðˈdrɔː, wɪθ- $ -ˈdrɒː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2</span><span class=\"meta-item\">(past tense withdrew /-ˈdruː/, past participle withdrawn /-ˈdrɔːn $ -ˈdrɒːn/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[not take part]</strong> RegisterIn everyday English, people usually say that someone pulls out of something such as a competition or organization rather than withdraws:· She pulled out with a knee injury.</div><ul class=\"examples\"><li><span class=\"gram\">[intransitive, transitive]</span> to stop taking part in an activity, belonging to an organization etc, or to make someone do this</li><li><strong><em>withdraw from</strong>: A knee injury forced her to withdraw from the competition. / calls for Britain to withdraw from the European Union</em></li><li><strong><em>withdraw something/somebody from something</strong>: Parents have the right to withdraw their children from religious education lessons if they wish.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[stop supporting]</strong> <span class=\"gram\">[transitive]</span> to stop giving support or money to someone or something, especially as the result of an official decision:</div><ul class=\"examples\"><li><em>One of the minority parties had withdrawn its support for Chancellor Kohl.</em></li><li><em>Union members will vote on whether to withdraw their labour (=stop working).</em></li><li><em>a government decision to withdraw funding</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[change your mind]</strong> <span class=\"gram\">[transitive]</span> if you withdraw a threat, offer, request etc, you say that you no longer will do what you said:</div><ul class=\"examples\"><li><em>After much persuasion he agreed to withdraw his resignation.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[say something is not true]</strong> <span class=\"gram\">[transitive]</span> <em>formal</em> if you withdraw a remark, criticism, statement etc, you say that what you said earlier was completely untrue <em>SYN retract</em>:</div><ul class=\"examples\"><li><em>He refused to withdraw his remarks and was expelled from the Party.</em></li><li><em>The newspaper has agreed to withdraw its allegations.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[product/service]</strong> <span class=\"gram\">[transitive]</span> if a product or service is withdrawn, it is no longer offered for sale or use</div><ul class=\"examples\"><li><strong><em>withdraw something from sale/from the market</strong>: The drug has been withdrawn from the market for further tests.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[leave a place]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[intransitive, transitive]</span> if an army withdraws, or if it is withdrawn, it leaves a place <em>SYN pull out</em>:</div><ul class=\"examples\"><li><em>the USA’s decision to withdraw 40,000 troops from western Europe</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[intransitive]</span> to leave a place, especially in order to be alone or go somewhere quiet</div><ul class=\"examples\"><li><strong><em>withdraw to</strong>: We withdrew to the garden for a private talk.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[money]</strong> <span class=\"gram\">[transitive]</span> to take money out of a bank account <em>SYN take out</em> RegisterIn everyday English, people often say that someone takes or gets money out rather than withdraws it:· Can we stop off at the bank? I need to get some money out.</div><ul class=\"examples\"><li><strong><em>withdraw something from something</strong>: I’d like to withdraw £500 from my current account.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[move]</strong> <span class=\"gram\">[transitive]</span> if you withdraw your hand, arm, finger etc from somewhere, you move it from there to where it was before:</div><ul class=\"examples\"><li><em>Claudia withdrew her hand from his.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[take out]</strong> <span class=\"gram\">[transitive]</span> <em>literary</em> to take an object out from inside something</div><ul class=\"examples\"><li><strong><em>withdraw something from something</strong>: She withdrew a document from her briefcase.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[stop communicating]</strong> <span class=\"gram\">[intransitive]</span> to become quieter, less friendly, and only concerned about your own thoughts → withdrawn</div><ul class=\"examples\"><li><strong><em>withdraw into/from</strong>: Ralph has withdrawn from the other kids.</em></li><li><em>Many depressed people just withdraw into themselves.</em></li></ul></div>","7747":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> with‧draw‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /wɪðˈdrɔːəl, wɪθ- $ -ˈdrɒːəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[army]</strong> <span class=\"gram\">[countable, uncountable]</span> the act of moving an army, weapons etc away from the area where they were fighting</div><ul class=\"examples\"><li><strong><em>withdrawal of</strong>: the withdrawal of UN forces</em></li><li><strong><em>withdrawal from</strong>: the Russian withdrawal from Afghanistan</em></li><li><em>large-scale troop withdrawals</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[removal/ending]</strong> <span class=\"gram\">[uncountable]</span> the removal or stopping of something such as support, an offer, or a service</div><ul class=\"examples\"><li><strong><em>withdrawal of</strong>: withdrawal of government aid</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[money]</strong> <span class=\"gram\">[countable, uncountable]</span> the act of taking money from a bank account, or the amount you take out:</div><ul class=\"examples\"><li><em>Customers can use the machine to make withdrawals of up to £250 a day.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[stop taking part]</strong> <span class=\"gram\">[uncountable]</span> the act of no longer taking part in an activity or being a member of an organization</div><ul class=\"examples\"><li><strong><em>withdrawal from</strong>: Germany’s withdrawal from the talks</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[drugs]</strong> <span class=\"gram\">[uncountable]</span> the period after someone has given up a drug that they were dependent on, and the unpleasant mental and physical effects that this causes</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[statement]</strong> <span class=\"gram\">[uncountable]</span> the act of saying that something you previously said was in fact untrue <em>SYN retraction</em></div><ul class=\"examples\"><li><strong><em>withdrawal of</strong>: the withdrawal of all allegations</em></li></ul></div>","7748":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> with‧hold</span><span class=\"meta-item\"><strong>IPA:</strong> /wɪðˈhəʊld, wɪθ- $ -ˈhoʊld/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle withheld /-ˈheld/)</span></div><div class=\"entry-body\"><div class=\"sense\">to refuse to give someone something:</div><ul class=\"examples\"><li><em>I withheld payment until they had completed the work.</em></li><li><em>Ian was accused of withholding vital information from the police.</em></li></ul></div>","7749":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> with‧in</span><span class=\"meta-item\"><strong>IPA:</strong> /wɪðˈɪn $ wɪðˈɪn, wɪθˈɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> ► see thesaurus at after, during</div><div class=\"subsense\"><span class=\"subnum\">a)</span> before a certain period of time has passed:</div><ul class=\"examples\"><li><em>We should have the test results back within 24 hours.</em></li><li><em>He fell sick and died within a matter of weeks.</em></li><li><em>Within an hour of our arrival Caroline was starting to complain.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> during a certain period of time:</div><ul class=\"examples\"><li><em>the enormous success of televised sport within the last twenty years</em></li><li><em>Within the space of a year, three of the town’s factories have closed down.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> less than a certain distance from a particular place:</div><ul class=\"examples\"><li><em>The invading troops came within 50 miles of Paris.</em></li><li><em>Within a five mile radius of Ollerton there are several pubs and restaurants.</em></li><li><em>We live within easy reach of (=close to) the shops.</em></li><li><em>Adjust the driver’s seat so that all the controls are within reach (=close enough to touch).</em></li><li><strong><em>within sight/earshot (of something)</strong> (=close enough to see or hear): As she came within sight of the house, she saw two men getting out of a car.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> inside a particular building or area <em>OPP outside</em>:</div><ul class=\"examples\"><li><em>Prisoners who died were buried within the walls of the prison.</em></li><li><em>public footpaths within the national park</em></li><li><em>The rooms within were richly furnished.</em></li><li><strong><em>apply/enquire within</strong> (=used on notices on the outside of buildings): Baby rabbits for sale. Enquire within.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> inside a society, organization, or group of people <em>OPP outside</em>:</div><ul class=\"examples\"><li><em>There have been a lot of changes within the department since I joined.</em></li><li><em>an attempt to reform the system from within</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> if something stays within a particular limit or set of rules, it does not go beyond that limit:</div><ul class=\"examples\"><li><em>We have to operate within a very tight budget.</em></li><li><em>Security firms have to work strictly within the law.</em></li><li><em>You can go anywhere you want within reason (=within reasonable limits).</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <em>literary</em> or <em>formal</em> inside a person’s body or mind <em>OPP outside</em>:</div><ul class=\"examples\"><li><em>Elaine felt a pain deep within her.</em></li><li><em>I’m feeling more relaxed within myself.</em></li></ul></div>","7750":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> with‧out</span><span class=\"meta-item\"><strong>IPA:</strong> /wɪðˈaʊt $ wɪðˈaut, wɪθˈaʊt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not having something, especially something that is basic or necessary: → do without at do2, → go without at go1</div><ul class=\"examples\"><li><em>After the storm we were without electricity for five days.</em></li><li><em>a house without a garden</em></li><li><em>We passed two ruined abbeys, one with a tower and one without.</em></li><li><em>I’m getting used to managing without a car.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to say that a particular thing has not happened when someone does something:</div><ul class=\"examples\"><li><em>Suddenly and without any warning, the army opened fire.</em></li><li><em>He had gone out without his parents’ permission.</em></li><li><em>I accepted his offer without a moment’s hesitation.</em></li><li><em>I got to my destination without too much difficulty.</em></li><li><strong><em>without doing something</strong>: ‘What do you expect?’ he said, without looking at her.</em></li><li><em>Without so much as a word of thanks, Ben turned and went back into the office (=he did not even say thank you as he should have done).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> not feeling or showing that you feel a particular emotion:</div><ul class=\"examples\"><li><em>He told his story without anger or bitterness.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> not being with someone, or not having them to help you, especially someone you like or need:</div><ul class=\"examples\"><li><em>I don’t know what I’d do without you.</em></li><li><em>Won’t you be lonely without her?</em></li><li><em>The rest of the group set off without him.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>without wanting/wishing to do something</strong> used before a criticism, complaint, or other statement to make it less strong:</div><ul class=\"examples\"><li><em>Without wanting to sound too boastful, I think we have the best television programmes in the world.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <em>old use</em> outside</div></div>","7751":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> with‧stand</span><span class=\"meta-item\"><strong>IPA:</strong> /wɪðˈstænd, wɪθ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle withstood /-ˈstʊd/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to be strong enough to remain unharmed by something such as great heat, cold, pressure etc <em>SYN resist</em> <em>, stand up to</em>:</div><ul class=\"examples\"><li><em>This fabric can withstand steam and high temperatures.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to defend yourself successfully against people who attack, criticize, or oppose you <em>SYN stand up to</em>:</div><ul class=\"examples\"><li><em>The Chancellor has withstood the criticism and held firm.</em></li></ul></div>","7752":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wit‧ness</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪtnəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[crime/accident]</strong> <span class=\"gram\">[countable]</span> someone who sees a crime or an accident and can describe what happened: → eyewitness</div><ul class=\"examples\"><li><em>Police have appealed for witnesses to come forward.</em></li><li><strong><em>witness to</strong>: One witness to the accident said the driver appeared to be drunk.</em></li><li><em>an eye witness (=someone who sees an event) to the robbery</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[in a court of law]</strong> <span class=\"gram\">[countable]</span> someone who appears in a court of law to say what they know about a crime or other event → testify → expert witness</div><ul class=\"examples\"><li><strong><em>key/star/principal witness</strong>: the key witness in the case against the brothers</em></li><li><em>The defence is expected to call them as witnesses.</em></li><li><strong><em>witness for the prosecution/defence</strong> (also<strong>prosecution/defence witness)</strong> (=someone the prosecution or defence lawyers choose as a witness in order to help prove their case)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[signing a document]</strong> <span class=\"gram\">[countable]</span> someone who is present when an official document is signed, and who signs it too, to say that they saw it being signed</div><ul class=\"examples\"><li><strong><em>witness to</strong>: a witness to a will</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be witness to something</strong> <em>formal</em> to be present when something happens, and watch it happening:</div><ul class=\"examples\"><li><em>We were witness to the worst excesses of the military.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[christian belief]</strong> <span class=\"gram\">[countable, uncountable]</span> <em>American English</em> a public statement of strong Christian belief, or someone who makes such a statement</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[crime/accident]</strong> <span class=\"gram\">[transitive]</span> to see something happen, especially a crime or accident: ► see thesaurus at notice, see</div><ul class=\"examples\"><li><em>Several residents claim to have witnessed the attack.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[experience something]</strong> <span class=\"gram\">[transitive]</span> to experience important events or changes:</div><ul class=\"examples\"><li><em>Priests have witnessed an increase in religious intolerance.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[time/place]</strong> <span class=\"gram\">[transitive]</span> if a time or place witnesses an event, the event happens during that time or in that place:</div><ul class=\"examples\"><li><em>Recent years have witnessed the collapse of the steel industry.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[official document]</strong> <span class=\"gram\">[transitive]</span> if you witness the signing of an official document, you are there when it is signed, and sign it yourself to prove this:</div><ul class=\"examples\"><li><em>Will you witness my signature?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>witness something</strong> (also..., as witnessed by something) used to introduce an example that proves something you have just mentioned:</div><ul class=\"examples\"><li><em>Bad economic times can result in political dictatorships. Witness Germany in the 1930s.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[religion]</strong> <span class=\"gram\">[intransitive]</span> to speak publicly about your Christian beliefs → testify</div></div></div>","7753":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wit‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">using words in a clever and amusing way: ► see thesaurus at funny</div><ul class=\"examples\"><li><em>witty remarks</em></li><li><em>Laura’s very witty.</em></li></ul></div>","7754":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wiz‧ard</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɪzəd $ -ərd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a man who is supposed to have magic powers → witch</div><div class=\"sense\"><span class=\"snum\">2</span> someone who is very good at something:</div><ul class=\"examples\"><li><em>a financial wizard</em></li><li><strong><em>wizard at</strong>: Ben’s a real wizard at chess.</em></li></ul></div>","7755":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wəʊ $ woʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>woes</strong> <span class=\"gram\">[plural]</span> <em>formal</em> the problems and troubles affecting someone:</div><ul class=\"examples\"><li><em>the country’s economic woes</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> <em>literary</em> great sadness</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>woe is me</strong> <em>spoken</em> <em>humorous</em> used to say that you are extremely unhappy or in a difficult situation</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>woe betide somebody</strong> <em>British English</em> used to warn someone that there will be trouble if they do something – especially used humorously:</div><ul class=\"examples\"><li><em>Woe betide anyone who smokes in our house!</em></li></ul></div>","7756":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wʊlf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural wolves /wʊlvz/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a wild animal that looks like a large dog and lives and hunts in groups:</div><ul class=\"examples\"><li><em>a pack of wolves</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>a wolf in sheep’s clothing</strong> someone who seems to be friendly or harmless but is in fact dangerous, dishonest etc</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>keep the wolf from the door</strong> to earn just enough money to buy the basic things you need:</div><ul class=\"examples\"><li><em>I work part-time in a coffee shop just to keep the wolf from the door.</em></li></ul></div>","7757":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wom‧an</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwʊmən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(plural women /ˈwɪmɪn/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[female person]</strong> <span class=\"gram\">[countable]</span> an adult female person:</div><ul class=\"examples\"><li><em>I was talking to a woman I met on the flight.</em></li><li><em>married women</em></li><li><em>a popular women’s magazine</em></li><li><em>When a woman is pregnant, the levels of hormones in her body change.</em></li><li><strong><em>woman priest/doctor etc</strong> (=a priest etc who is a woman): Ireland’s first woman president / women artists</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[any woman]</strong> <span class=\"gram\">[singular]</span> <em>formal</em> women in general:</div><ul class=\"examples\"><li><em>A woman’s work is never done (=used to say that women have a lot to do).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>businesswoman/spokeswoman etc</strong> a woman who has a particular kind of job:</div><ul class=\"examples\"><li><em>Congresswoman Ellen Tauscher</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>another woman/the other woman</strong> <em>informal</em> a woman that a man is having a sexual relationship with, even though he is married to someone else:</div><ul class=\"examples\"><li><em>I’m sure he’s got another woman.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be your own woman</strong> to make your own decisions and be in charge of your own life, without depending on anyone else</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[partner]</strong> <span class=\"gram\">[singular]</span> <em>spoken</em> a word meaning a wife or girlfriend, which many women find offensive: → kept woman</div><ul class=\"examples\"><li><em>Did he bring his new woman with him?</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[form of address]</strong> <span class=\"gram\">[uncountable]</span> <em>old-fashioned</em> <em>not polite</em> a rude way of speaking to a woman when you are angry, annoyed etc</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>[servant]</strong> <span class=\"gram\">[countable]</span> a female servant or person who does cleaning work for you in your house → cleaner, daily help</div></div>","7758":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wuːm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the part of a woman’s or female animal’s body where her baby grows before it is born <em>SYN uterus</em></div></div>","7759":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> won‧der</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwʌndə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to think about something that you are not sure about and try to guess what is true, what will happen etc</div><ul class=\"examples\"><li><strong><em>wonder who/what/how etc</strong>: I wonder how James is getting on. / What are they going to do now, I wonder?</em></li><li><strong><em>wonder if/whether</strong>: I wonder if I’ll recognize Philip after all these years.</em></li><li><em>He’s been leaving work early a lot – it makes you wonder, doesn’t it?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>I wonder if/whether</strong> <em>spoken</em> used to ask politely for something <em>SYN may I</em>:</div><ul class=\"examples\"><li><em>I wonder if I might have a drink?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>I was wondering if/whether</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>spoken</em> used to ask someone politely to help you:</div><ul class=\"examples\"><li><em>I was wondering if I could borrow your car?</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to ask someone politely if they would like to do something:</div><ul class=\"examples\"><li><em>I was wondering if you’d like to come to dinner.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> to feel surprised and unable to believe something</div><ul class=\"examples\"><li><strong><em>wonder about/at</strong>: Sometimes I wonder about his behaviour.</em></li><li><strong><em>wonder how</strong>: I wonder how he dares to show his face!</em></li><li><strong><em>I don’t wonder<em>British English</em></strong> (=I am not surprised): I don’t wonder you’re tired.</em></li><li><strong><em>I shouldn’t wonder<em>British English</em></strong> (=I would not be surprised about something): He’ll come back soon enough, I shouldn’t wonder.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> to doubt or question whether something is true:</div><ul class=\"examples\"><li><em>‘Is she serious?’ ‘I wonder.’</em></li><li><strong><em>wonder if/whether</strong>: Sometimes I wonder if he’s got any sense at all!</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[admiration]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[uncountable]</span> a feeling of surprise and admiration for something very beautiful or new to you <em>SYN awe</em>:</div><ul class=\"examples\"><li><em>The sight of the Taj Mahal filled us with wonder.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[countable]</span> something that makes you feel surprise and admiration:</div><ul class=\"examples\"><li><em>technological wonders</em></li><li><em>the Seven Wonders of the World</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>(it’s) no/small/little wonder (that)</strong> <em>especially spoken</em> used to say that you are not surprised by something:</div><ul class=\"examples\"><li><em>No wonder you’ve got a headache, the amount you drank last night.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[surprising]</strong> <strong>it’s a wonder (that)</strong> <em>especially spoken</em> used to say that something is very surprising:</div><ul class=\"examples\"><li><em>It’s a wonder no one got hurt.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>do/work wonders</strong> to be very effective in solving a problem</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>wonders will never cease</strong> <em>spoken</em> used humorously to show you are surprised and pleased about something</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[clever person]</strong> <span class=\"gram\">[singular]</span> <em>British English</em> someone who is good at doing difficult things</div></div></div>","7760":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> won‧der‧ful</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwʌndəfəl $ -dər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> making you feel very happy <em>SYN great</em>: ► see thesaurus at good, nice</div><ul class=\"examples\"><li><em>We had a wonderful time in Spain.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> making you admire someone or something very much <em>SYN amazing</em>:</div><ul class=\"examples\"><li><em>It’s wonderful what doctors can do nowadays.</em></li></ul></div>","7761":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> won‧der‧ful‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwʌndəfəli $ -dər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">very well or to a very great degree, in a way that makes you feel happy:</div><ul class=\"examples\"><li><em>All of the performers played wonderfully.</em></li><li><em>a wonderfully rich sauce</em></li></ul></div>","7762":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wʊd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the material that trees are made of → wooden, woody: → hardwood, softwood</div><ul class=\"examples\"><li><em>Put some more wood on the fire.</em></li><li><em>a polished wood floor</em></li><li><em>Her house was made of wood.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> (also the woods) a small forest:</div><ul class=\"examples\"><li><em>a walk in the woods</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>touch wood</strong> <em>British English</em>, knock on wood<em>American English</em> said just after you have said that things are going well for you, when you want your good luck to continue</div><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> one of a set of four golf clubs with wooden heads</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>not be out of the wood(s) yet</strong> <em>informal</em> used to say that there are likely to be more difficulties before things improve</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>not see the wood for the trees</strong> to not notice what is important about something because you give too much of your attention to small details</div></div>","7763":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wood‧en</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwʊdn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> made of wood:</div><ul class=\"examples\"><li><em>a wooden bench</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> not showing enough expression, emotion, or movement, especially when performing in public</div></div>","7764":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wood‧land</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwʊdlənd, -lænd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">an area of land covered with trees → wood, forest ► see thesaurus at forest</div></div>","7765":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wʊl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the soft thick hair that sheep and some goats have on their body → lambswool</div><div class=\"sense\"><span class=\"snum\">2</span> material made from wool:</div><ul class=\"examples\"><li><em>a pure wool skirt</em></li><li><em>a mix of 80% wool and 20% man-made fibres</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> thread made from wool that you use to knit clothes SYN yarn<em>American English</em>:</div><ul class=\"examples\"><li><em>a ball of wool</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>pull the wool over somebody’s eyes</strong> to deceive someone by not telling the truth</div></div>","7766":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɜːd $ wɜːrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[group of letters]</strong> <span class=\"gram\">[countable]</span> a single group of letters that are used together with a particular meaning: → buzzword, four-letter word, swear word</div><ul class=\"examples\"><li><em>Write an essay of about five hundred words.</em></li><li><em>What does that word mean?</em></li><li><em>&#x27;Vater&#x27; is the German word for (=that means) &#x27;father&#x27;.</em></li><li><em>Perhaps &#x27;lucky&#x27; is not exactly the right word.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>somebody’s words</strong> the things that someone says or writes:</div><ul class=\"examples\"><li><em>Those are his words, not mine.</em></li><li><strong><em>in somebody’s words</strong>: Jones was, in the judge’s words, ‘an evil man’. / In your own words, explain the term ‘personal service’.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the words</strong> the words that are sung as part of a song:</div><ul class=\"examples\"><li><em>I know the tune, but I&#x27;ve forgotten the words.</em></li><li><strong><em>word to</strong>: Many people don&#x27;t know the words to the country&#x27;s national anthem.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>have a word</strong> <em>especially spoken</em> to talk to someone quickly, especially because you need their advice about something or you want to tell them to do something:</div><ul class=\"examples\"><li><em>Could I have a word?</em></li><li><strong><em>word with</strong>: I’ll have a word with him and see if he’ll help.</em></li><li><strong><em>have a quick/brief word</strong>: I was hoping to have a quick word with you.</em></li><li><strong><em>have/exchange a few words</strong>: Could I have a few words with you?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>want a word</strong> <em>spoken</em> to want to talk to someone, especially in order to criticize them</div><ul class=\"examples\"><li><strong><em>word with</strong>: Wait a minute! I want a word with you!</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>not hear/understand/believe a word</strong> used to emphasize that you cannot hear, understand etc what someone says or writes:</div><ul class=\"examples\"><li><em>No one could hear a word because someone had cut the amplifier cable.</em></li><li><strong><em>word of</strong>: I can’t understand a word of Russian.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>without (saying) a word</strong> if you do something without a word, you do not say anything while you do it:</div><ul class=\"examples\"><li><em>He left without a word.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>say a word/say a few words</strong> to make a short speech about something:</div><ul class=\"examples\"><li><em>I’d like to say a few words about the plans.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>a word of warning/caution/advice/thanks etc</strong> something you say that warns someone, thanks them etc:</div><ul class=\"examples\"><li><em>It’s a beautiful city, but a word of warning: street robberies are very common.</em></li><li><em>He left without a word of apology.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>not say a word</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> (also not breathe a word) to not say anything about something because it is a secret:</div><ul class=\"examples\"><li><em>Promise you won’t say a word to anyone?</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to not say anything:</div><ul class=\"examples\"><li><em>What’s wrong? You haven’t said a word since you got here.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>put your feelings/thoughts etc into words</strong> to express what you want to say clearly:</div><ul class=\"examples\"><li><em>He found it difficult to put ideas into words.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>have/exchange words (with somebody)</strong> to argue – use this when you do not want to make the argument seem serious:</div><ul class=\"examples\"><li><em>I was in a bad mood and he kept pestering me, so we had words.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>a harsh/a cross/an angry etc word</strong> something you say that shows you are angry or want to criticize someone:</div><ul class=\"examples\"><li><em>Mountain rescue teams have harsh words to say to people who climb without proper equipment.</em></li><li><em>They were married for 50 years and she says there was never an angry word between them.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>[news/information]</strong> <span class=\"gram\">[singular, uncountable]</span> a piece of news or a message:</div><ul class=\"examples\"><li><em>Word came that our duties would be changed.</em></li><li><em>‘Have you heard from Ann?’ ‘No, not a word.’</em></li><li><em>There was still no word from John.</em></li><li><strong><em>word gets out/around</strong> (=people hear about something): It’s a very small town and if you do something bad, word gets around.</em></li><li><strong><em>the word is (that)/word has it (that)</strong> (=people are saying that): The word is that the two companies are planning a merger.</em></li><li><strong><em>spread/pass the word</strong> (=tell other people some information or news): Health officials are encouraging people to spread the word about the benefits of exercise.</em></li><li><strong><em>send/bring word<em>old-fashioned</em></strong> </em>formal<em> (=send or bring a message): The mayor sent word he’d be late.</em></li><li><em>Word of mouth (=information you get by someone telling you) is one of the best ways of getting business.</em></li><li><strong><em>by word of mouth</strong>: Much of this information is picked up by word of mouth from previous students.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>the last/final word</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the power to decide whether or how to do something</div><ul class=\"examples\"><li><strong><em>word on</strong>: The final word on policy determination belongs to the committee.</em></li><li><em>She has the final word on whether policies are put into action or not.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the last statement or speech in a discussion or argument:</div><ul class=\"examples\"><li><em>The last word must go to Nick, who has organized the whole project.</em></li><li><em>Why must you always have the last word in any argument?</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> in sports, the last hit or kick in a game, especially when it is successful:</div><ul class=\"examples\"><li><em>Adams had the final word with a last-minute goal.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>my/his/your etc word</strong> a sincere promise to do something, or a promise that what you say is true:</div><ul class=\"examples\"><li><em>I trust him to keep his word.</em></li><li><em>I give you my word (=I promise) that it won’t happen again.</em></li><li><em>They had given their word of honour that they would not attempt to escape.</em></li><li><em>We only have his word for it that he has already paid.</em></li><li><em>Delors claimed that Johnson had gone back on his word (=not done what he had promised to do).</em></li><li><em>The business is doing very well. You can take my word for it (=accept that what I say is true).</em></li><li><em>I never know whether to take him at his word (=believe what he says).</em></li><li><em>His word is his bond (=he always does what he promises to do).</em></li><li><strong><em>be true to your word/be as good as your word</strong> (=do what you promise to do)</em></li><li><strong><em>a man of his word/a woman of her word</strong> (=a man or woman who does what they have promised to do)</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>word for word</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> in exactly the same words:</div><ul class=\"examples\"><li><em>The newspaper printed his speech more or less word for word.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> (also word by word) if you translate a piece of writing word for word, you translate the meaning of each single word rather than the meaning of a whole phrase or sentence</div><div class=\"sense\"><span class=\"snum\">18</span> <strong>in a word</strong> used before giving a very simple answer or explanation:</div><ul class=\"examples\"><li><em>We are, in a word, busy. Ridiculously busy.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>in words of one syllable</strong> saying something in a way that is very easy to understand, especially because the person you are talking to is stupid:</div><ul class=\"examples\"><li><em>You have to put everything in words of one syllable for her.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>in so many words</strong> (also in as many words) <span class=\"gram\">[usually negative]</span> in a direct way, or in a way that makes it very clear what you mean:</div><ul class=\"examples\"><li><em>Aunt Fay wasn’t happy and said so in as many words.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>take the words (right) out of somebody’s mouth</strong> <em>spoken</em> if someone takes the words out of your mouth, they have just said what you were going to say</div><div class=\"sense\"><span class=\"snum\">22</span> <strong>put words into somebody’s mouth</strong> <em>spoken</em> to tell someone what you think they are trying to say, in a way that annoys them:</div><ul class=\"examples\"><li><em>Will you stop putting words into my mouth – I never said I disliked the job.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>[an order]</strong> <span class=\"gram\">[singular]</span> an order to do something:</div><ul class=\"examples\"><li><em>On the word ‘go’ everyone has to run to the end of the room and back.</em></li><li><em>When I give the word, grab him.</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>(right) from the word go</strong> <em>spoken</em> from the beginning of something:</div><ul class=\"examples\"><li><em>The marriage was a disaster from the word go.</em></li></ul><div class=\"sense\"><span class=\"snum\">25</span> <strong>too silly/complicated/ridiculous etc for words</strong> <em>spoken</em> extremely silly, complicated etc:</div><ul class=\"examples\"><li><em>His behaviour has been too pathetic for words.</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> <strong>(have/drop) a word in somebody’s ear</strong> to say something to someone privately, especially to give them advice or a warning:</div><ul class=\"examples\"><li><em>If I were you, I’d have a word in his ear before it’s too late.</em></li></ul><div class=\"sense\"><span class=\"snum\">27</span> <strong>get a word in (edgeways)</strong> to get a chance to say something:</div><ul class=\"examples\"><li><em>Once George starts talking it’s difficult to get a word in edgeways.</em></li></ul><div class=\"sense\"><span class=\"snum\">28</span> <strong>put in a (good) word for somebody</strong> to try to help someone get or achieve something by saying good things about them to someone else:</div><ul class=\"examples\"><li><em>I got the job because Paul put in a good word for me.</em></li></ul><div class=\"sense\"><span class=\"snum\">29</span> <strong>words fail me</strong> <em>spoken</em> used to say that you are so surprised, angry, or shocked that you do not know what to say:</div><ul class=\"examples\"><li><em>I... words fail me.</em></li></ul><div class=\"sense\"><span class=\"snum\">30</span> <strong>word!</strong> <em>American English</em> <em>informal</em> used to say that you understand or agree with what someone has just said</div><div class=\"sense\"><span class=\"snum\">31</span> <strong>(Upon) my word!</strong> <em>spoken</em> <em>old-fashioned</em> used when you are very surprised:</div><ul class=\"examples\"><li><em>My word! Hasn’t she grown?</em></li></ul><div class=\"sense\"><span class=\"snum\">32</span> <strong>surprised/angry/pleased etc isn’t the word for it</strong> <em>spoken</em> used to say that you are extremely surprised, angry etc</div><div class=\"sense\"><span class=\"snum\">33</span> <strong>a man/woman etc of few words</strong> someone who does not say very much:</div><ul class=\"examples\"><li><em>My father was a man of few words.</em></li></ul><div class=\"sense\"><span class=\"snum\">34</span> <strong>the Word (of God)</strong> the religious ideas and messages in the Bible</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to use words that are carefully chosen in order to express something <em>SYN phrase</em>:</div><ul class=\"examples\"><li><em>How can we word the letter so as not to offend the parents?</em></li></ul></div></div>","7767":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> word‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɜːdɪŋ $ ˈwɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the words and phrases used to express something <em>SYN phrasing</em></div><ul class=\"examples\"><li><strong><em>wording of</strong>: the exact wording of the contract</em></li></ul></div>","7768":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɜːk $ wɜːrk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[do a job for money]</strong> <span class=\"gram\">[intransitive]</span> to do a job that you are paid for: GRAMMAR: Prepositions with work• You work in a city or area: · He works in Manhattan.• You work in a type of place such as a bank, shop, or factory: · She works in a library.• You work at a particular place or organization: · She works at the Library of Congress.• You work for a person, company, or organization that employs you: · He works for his father.· We both work for the same company.• You work in an industry or a type of job, for example education, advertising, or IT: · He works in advertising.• You work as a waiter, cashier, accountant etc: · She works as a cook. ✗Don’t say: She works as cook.• You work on a project or task: · Several people worked on the report.</div><ul class=\"examples\"><li><em>Where do you work?</em></li><li><em>Many young people in the area have never worked.</em></li><li><em>The injury means he’ll probably never work again.</em></li><li><strong><em>work for</strong>: He works for a law firm.</em></li><li><strong><em>work at/in</strong>: I work at the university.</em></li><li><strong><em>work as</strong>: She works as a consultant for a design company.</em></li><li><strong><em>work in industry/education/publishing etc</strong>: The studies were undertaken by people working in education.</em></li><li><strong><em>work part-time/full-time</strong>: I work part-time in a library.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[do your job]</strong> <span class=\"gram\">[intransitive, transitive]</span> to do the activities and duties that are part of your job:</div><ul class=\"examples\"><li><em>Sally isn’t working tomorrow.</em></li><li><em>Staff will have to get used to a new way of working.</em></li><li><strong><em>work with</strong>: One of the women I work with is getting married this weekend.</em></li><li><strong><em>work under somebody</strong> (=have someone who is in charge of you): Each site has a fully trained team who work under a site manager.</em></li><li><strong><em>work days/nights/weekends etc</strong>: I get paid more if I work nights. / We’re sometimes expected to work twelve-hour days.</em></li><li><em>Are you working late (=working after the time you usually finish) again tonight?</em></li><li><em>Forty police officers are working round the clock (=working day and night without stopping) to find Murray’s killer.</em></li><li><em>Nowadays, many people are able to work from home.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[help]</strong> <span class=\"gram\">[intransitive]</span> if you work with someone or a group of people, your job involves trying to help them</div><ul class=\"examples\"><li><strong><em>work with/among</strong>: She’s just retired after 38 years working with children. / He has worked among some of the world’s poorest people.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[do an activity]</strong> <span class=\"gram\">[intransitive]</span> to spend time and effort doing something:</div><ul class=\"examples\"><li><em>I’ve been working in the garden all afternoon.</em></li><li><em>I’m going to have to work really hard to pass these exams.</em></li><li><em>We’re working together to develop a new system.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[try to achieve something]</strong> <span class=\"gram\">[intransitive]</span> to try continuously to achieve a particular thing</div><ul class=\"examples\"><li><strong><em>work towards</strong>: They are working towards a solution to their problems.</em></li><li><strong><em>work for</strong>: We will work for the release of the hostages.</em></li><li><strong><em>work to do something</strong>: The police are working to provide more help for victims of crime.</em></li><li><em>The company is working hard to improve its image.</em></li><li><em>He worked tirelessly (=worked very hard in a determined way) for the charity throughout his life.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[machine/equipment]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[intransitive]</span> if a machine or piece of equipment works, it does what it is supposed to do:</div><ul class=\"examples\"><li><em>You should check that the smoke alarm is working properly.</em></li><li><em>The delete key doesn’t work.</em></li><li><strong><em>get something to work</strong>: I can’t get the heater to work.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[transitive]</span> to make a machine or piece of equipment do what it is supposed to do:</div><ul class=\"examples\"><li><em>My parents can’t even work the video.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[be effective/successful]</strong> <span class=\"gram\">[intransitive]</span> to be effective or successful:</div><ul class=\"examples\"><li><em>Making a marriage work can take a lot of effort.</em></li><li><em>I’ve never found a diet that works.</em></li><li><em>The recipe works just as well if you use margarine instead of butter.</em></li><li><em>The cream works immediately to relieve sore skin.</em></li><li><strong><em>work for</strong>: You need to find which method works best for you.</em></li><li><strong><em>work against</strong>: a drug that works against some types of cancer</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[have an effect]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> if something such as a fact, situation, or system works in a particular way, it has a particular effect on someone or something:</div><ul class=\"examples\"><li><em>The arrangement works well for everyone involved.</em></li><li><em>The French team are the heavier crew, which should work in their favour (=help them).</em></li><li><em>Sexism still works against (=harms or causes problems for) women in many professions.</em></li><li><em>Loyalty works both ways (=involves two opposite or matching effects): we are loyal to our employees and, in turn, they are loyal to us.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[art/style/literature]</strong> <span class=\"gram\">[intransitive]</span> if a painting, design, piece of writing etc works, it is successful because it has the effect on you that the painter, writer etc intended:</div><ul class=\"examples\"><li><em>I don’t think the scene with the horses really works, do you?</em></li><li><strong><em>work for</strong>: The colour combination just doesn’t work for me.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[shape/cut something]</strong> <span class=\"gram\">[transitive]</span> if you work a material such as metal, leather, or clay, you cut, sew, or shape it in order to make something</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>[use a substance]</strong> <span class=\"gram\">[intransitive]</span> to use a particular material or substance in order to make something such as a picture, design, jewellery etc</div><ul class=\"examples\"><li><strong><em>work in/with</strong>: a sculptor who works in steel / a jeweller who works with silver</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>work your way to/through etc something</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to move somewhere slowly and with difficulty:</div><ul class=\"examples\"><li><em>From here, we worked our way carefully across the rock base.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to achieve something gradually by working:</div><ul class=\"examples\"><li><em>He had worked his way up to head of department.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>work your way through school/college/university etc</strong> to do a job while you are a student because you need the money to pay for your courses, books etc</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>[move gradually]</strong> <span class=\"gram\">[intransitive, transitive always + adverb/preposition]</span> to move into a particular state or position very gradually, either in a series of small movements or after a long time:</div><ul class=\"examples\"><li><em>Slowly he worked the screwdriver into the crack.</em></li><li><strong><em>work (its way) loose</strong>: One of the screws must have worked loose.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>[exercise]</strong> <span class=\"gram\">[transitive]</span> to use and exercise a muscle or part of your body:</div><ul class=\"examples\"><li><em>Swimming is a form of exercise that works every muscle in your body.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>[move]</strong> <span class=\"gram\">[intransitive, transitive]</span> <em>formal</em> if a part of your body works or you work it, it moves:</div><ul class=\"examples\"><li><em>She was trembling and her mouth was working.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>[work in an area]</strong> <span class=\"gram\">[transitive]</span> <em>especially American English</em> if you work a particular area or type of place, you travel around the area for your job, or work in that type of place:</div><ul class=\"examples\"><li><em>Markowitz works the Tri-State area.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>work the door</strong> to take tickets from people as they enter a club, theatre etc:</div><ul class=\"examples\"><li><em>Binns worked the door at various Manhattan clubs.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>[entertain a crowd]</strong> <span class=\"gram\">[transitive]</span> if an entertainer or politician works a crowd of people, they entertain them and get their interest or support:</div><ul class=\"examples\"><li><em>She really knew how to work a crowd.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>[land/soil]</strong> <span class=\"gram\">[transitive]</span> if you work the land, soil etc, you do all the work necessary to grow crops on it:</div><ul class=\"examples\"><li><em>He was left to work the farm alone.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>[mine]</strong> <span class=\"gram\">[transitive]</span> to remove a substance such as coal, gold, or oil from under the ground</div><div class=\"sense\"><span class=\"snum\">22</span> <strong>work like magic/work like a charm</strong> (also work a treat<em>British English</em>) to be very effective:</div><ul class=\"examples\"><li><em>a polish that works a treat on windows</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>[mind/brain]</strong> <span class=\"gram\">[intransitive]</span> if your mind or brain is working, you are thinking or trying to solve a problem</div><div class=\"sense\"><span class=\"snum\">24</span> <strong>work on the principle/assumption/basis etc that</strong> to base ideas, plans etc on a particular fact that you think is true:</div><ul class=\"examples\"><li><em>We’re working on the assumption that the conference will take place in Canada, as planned.</em></li></ul><div class=\"sense\"><span class=\"snum\">25</span> <strong>work yourself into a frenzy/panic/state etc</strong> to make yourself become very nervous, angry etc:</div><ul class=\"examples\"><li><em>He seemed to be working himself into a rage.</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> <strong>work it/things</strong> <em>spoken</em> to make arrangements for something to happen, especially by behaving in a clever or skilful way:</div><ul class=\"examples\"><li><em>We should try and work it so that we can all go together.</em></li></ul><div class=\"sense\"><span class=\"snum\">27</span> <strong>work the system</strong> to understand how a system works so that you can get advantages for yourself, often in a slightly dishonest way:</div><ul class=\"examples\"><li><em>Lynn could show the rest of us how to work the system.</em></li></ul><div class=\"sense\"><span class=\"snum\">28</span> <strong>work somebody hard</strong> (also work somebody into the ground<em>informal</em>) to make someone work very hard:</div><ul class=\"examples\"><li><em>The coach has been working us really hard this week.</em></li><li><em>People have complained that they are being worked into the ground.</em></li><li><strong><em>work yourself into the ground</strong>: I’ve worked myself into the ground setting up this interview.</em></li></ul><div class=\"sense\"><span class=\"snum\">29</span> <strong>work your fingers to the bone</strong> (also work your socks off<em>informal</em>) to work very hard</div><div class=\"sense\"><span class=\"snum\">30</span> <strong>work your butt/ass/arse off</strong> <em>not polite</em> to work very hard</div><div class=\"sense\"><span class=\"snum\">31</span> <strong>[calculate]</strong> <span class=\"gram\">[transitive]</span> <em>American English</em> <em>formal</em> to calculate the answer to a mathematical problem</div><div class=\"sense\"><span class=\"snum\">32</span> <strong>work to rule</strong> <em>British English</em> to protest about a situation at work by doing your job slowly, with the excuse that you must obey all the rules exactly</div><div class=\"sense\"><span class=\"snum\">33</span> <strong>(it) works for me/you etc</strong> <em>spoken</em> used to say that something is very suitable for someone and does exactly what they wanted or expected:</div><ul class=\"examples\"><li><em>I meditate and do Yoga every day. It works for me and I think it could work for you too.</em></li></ul><div class=\"sense\"><span class=\"snum\">34</span> <strong>work a trend/look etc</strong> to wear something fashionable – used especially in magazines:</div><ul class=\"examples\"><li><em>Gemma looks great as she works the nautical look.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[job]</strong> <span class=\"gram\">[uncountable]</span> a job or activity that you do regularly, especially in order to earn money → employment: ► see thesaurus at job GRAMMAR: Comparisonwork• In this meaning, work is always an uncountable noun.• You say: · It may be hard for older people to find work. ✗Don’t say: find a workjob• Job is a countable noun.• You say: · I applied for a job as a reporter. ✗Don’t say: I applied for a work.• You say: · Her first job was in London. ✗Don’t say: Her first work was in London.</div><ul class=\"examples\"><li><em>There isn’t a lot of work at this time of the year.</em></li><li><em>He’s been out of work (=without a job) for two years.</em></li><li><em>More people are in work (=have a job) than ten years ago.</em></li><li><strong><em>before/after work</strong> (=before a day of work or at the end of a day of work): Do you want to go for a drink after work?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[place]</strong> <span class=\"gram\">[uncountable]</span> a place where you do your job, which is not your home:</div><ul class=\"examples\"><li><em>I had an accident on the way to work.</em></li><li><em>He left work at the usual time.</em></li><li><em>I went out with the girls from work last night.</em></li><li><strong><em>at work</strong>: Dad’s at work right now.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[duties]</strong> <span class=\"gram\">[uncountable]</span> the duties and activities that are part of your job:</div><ul class=\"examples\"><li><em>A large part of the work we do involves using computers.</em></li><li><em>He starts work at 4 am.</em></li><li><em>He’s started a business doing gardening and roofing work.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[result]</strong> <span class=\"gram\">[uncountable]</span> something that you produce as a result of doing your job or doing an activity:</div><ul class=\"examples\"><li><em>Send a résumé and examples of your work.</em></li><li><em>The building is the work of architect Rafael Moneo.</em></li><li><em>The teacher should make sure that each child has a piece of work displayed on the wall.</em></li><li><em>The standard of work has declined.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[papers etc]</strong> <span class=\"gram\">[uncountable]</span> the papers and other materials you need for doing work:</div><ul class=\"examples\"><li><em>Can you move some of your work off the kitchen table?</em></li><li><em>I often have to take work home with me.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[book/painting/music]</strong> <span class=\"gram\">[countable]</span> something such as a painting, play, piece of music etc that is produced by a painter, writer, or musician: → work of art ► see thesaurus at music</div><ul class=\"examples\"><li><em>the Collected Works of Shakespeare</em></li><li><em>It is another accomplished work by the artist.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[activity]</strong> <span class=\"gram\">[uncountable]</span> when you use physical or mental effort in order to achieve something</div><ul class=\"examples\"><li><strong><em>work on</strong>: Work will start next month on a new swimming pool in the centre of the city.</em></li><li><em>Looking after children can be hard work.</em></li><li><strong><em>carry out/do work</strong>: You should not allow unqualified people to carry out work on your house.</em></li><li><strong><em>set to work/get down to work</strong> (=start work): He set to work immediately.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[study]</strong> <span class=\"gram\">[uncountable]</span> study or research, especially for a particular purpose</div><ul class=\"examples\"><li><strong><em>carry out/do work</strong>: The centre carries out work to monitor trends in housing management. / He did his postgraduate work in Sociology.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>at work</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> doing your job or a particular activity:</div><ul class=\"examples\"><li><em>He spent most of his time watching the fishermen at work.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> having a particular influence or effect:</div><ul class=\"examples\"><li><em>Volcanoes display some of nature’s most powerful forces at work.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>the (whole) works</strong> <em>spoken</em> used after mentioning several things, to emphasize that someone or something has everything you can think of:</div><ul class=\"examples\"><li><em>The hotel had everything – sauna, swimming pool, the works.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>nice work/quick work</strong> <em>spoken</em> used to praise someone for doing something well or quickly:</div><ul class=\"examples\"><li><em>That was quick work!</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>something is in the works/pipeline</strong> <em>informal</em> used to say that something is being planned or developed:</div><ul class=\"examples\"><li><em>Upgrades to the existing software are in the works.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>works</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[plural]</span> activities involved in building or repairing things such as roads, bridges etc → public works</div><ul class=\"examples\"><li><strong><em>engineering works/irrigation works/roadworks</strong>: the official in charge of the engineering works</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[countable]</span> (plural works) a building or group of buildings in which goods are produced in large quantities or an industrial process happens</div><ul class=\"examples\"><li><strong><em>ironworks/gasworks/cement etc works</strong>: The brick works closed last year.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>the works</strong> the moving parts of a machine <em>SYN mechanism</em></div><div class=\"sense\"><span class=\"snum\">15</span> <strong>[operation]</strong> <span class=\"gram\">[uncountable]</span> an operation to make you look younger or more attractive <em>SYN cosmetic surgery</em>:</div><ul class=\"examples\"><li><em>All these celebrities have had work done.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>have your work cut out (for you)</strong> <em>informal</em> used to say that it will be very difficult to do something:</div><ul class=\"examples\"><li><em>The team will have their work cut out if they are to win the competition.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>make short/light work of something</strong> to do something very quickly and easily:</div><ul class=\"examples\"><li><em>A microwave oven can make light work of the cooking.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>make heavy/hard work of something</strong> to do something with difficulty:</div><ul class=\"examples\"><li><em>They made hard work of what should have been an easy game.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>be a work in progress</strong> to not be finished or perfect yet:</div><ul class=\"examples\"><li><em>The garden is still very much a work in progress.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>all work and no play (makes Jack a dull boy)</strong> used to say that you should not spend all your time working, but should spend some of your time relaxing</div><div class=\"sense\"><span class=\"snum\">21</span> <strong>[force]</strong> <span class=\"gram\">[uncountable]</span> <em>technical</em> force multiplied by distance</div></div></div>","7769":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌwork of ˈart</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural works of art)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a painting, sculpture etc of high quality</div><div class=\"sense\"><span class=\"snum\">2</span> something that is very attractive and skilfully made – often used humorously:</div><ul class=\"examples\"><li><em>That cake’s a real work of art!</em></li></ul></div>","7770":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> work‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɜːkə $ ˈwɜːrkər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who does a job, especially a particular type of job: → guest worker, social worker</div><ul class=\"examples\"><li><em>workers in the tourist industry</em></li><li><em>reports from local aid workers</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[usually plural]</span> someone who works in an organization and who is not a manager:</div><ul class=\"examples\"><li><em>conflicts between workers and management</em></li><li><em>attacks on workers’ rights</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a good/hard/quick etc worker</strong> someone who works very well or quickly</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>the workers</strong> <span class=\"gram\">[plural]</span> the members of the working class:</div><ul class=\"examples\"><li><em>the workers’ revolution</em></li></ul></div>","7771":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> work‧force</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɜːkfɔːs $ ˈwɜːrkfɔːrs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[singular]</span></span></div><div class=\"entry-body\"><div class=\"sense\">all the people who work in a particular industry or company, or are available to work in a particular country or area → staff:</div><ul class=\"examples\"><li><em>Women now represent almost 50% of the workforce.</em></li><li><em>The company is cutting its workforce.</em></li><li><strong><em>skilled/educated/flexible etc workforce</em></strong></li></ul></div>","7772":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> work‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɜːkɪŋ $ ˈwɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> having a job that you are paid for → employed:</div><ul class=\"examples\"><li><em>a working mother</em></li><li><em>Many working women rely on relatives for childcare.</em></li><li><em>A smaller working population will have to support a growing number of retired people.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>old-fashioned</em> having a physical or practical job</div><ul class=\"examples\"><li><strong><em>working man/people/folk</strong>: the ordinary working man</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>working hours/day/week</strong> the time that people spend doing their job:</div><ul class=\"examples\"><li><em>In a normal working day, I see around 6 or 7 clients.</em></li><li><strong><em>during/outside working hours</strong>: Telephone at any time during normal working hours.</em></li><li><em>Many mothers prefer flexible working hours.</em></li><li><em>We do a 37-hour working week.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>working day</strong> a day of the week when most people work. In Britain and the US this is usually Monday to Friday <em>SYN workday</em>:</div><ul class=\"examples\"><li><em>It will be returned within three working days (=three days, not including weekends or public holidays).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>working conditions/environment etc</strong> the situation in which you work, especially the physical things such as pay or safety:</div><ul class=\"examples\"><li><em>improvements in working conditions</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>working practices/methods</strong> the way in which you do your job:</div><ul class=\"examples\"><li><em>training in up-to-date working practices</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>working life</strong> the part of your adult life when you have a paid job:</div><ul class=\"examples\"><li><em>He spent all his working life in a factory.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>(in) working order</strong> working properly and not broken</div><ul class=\"examples\"><li><strong><em>be in good/perfect/full etc working order</strong>: The car was old, but the engine was still in good working order.</em></li><li><em>the amount of exercise needed to keep your body in working order</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>working relationship</strong> the way that people work together</div><ul class=\"examples\"><li><strong><em>working with/between</strong>: They want to establish a better working relationship between medical and nursing staff.</em></li><li><strong><em>good/close/effective etc working relationship</strong>: We have a close working relationship with other voluntary groups.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>a working knowledge of something</strong> enough knowledge of a system, subject, language etc to be able to use it or to do a particular job:</div><ul class=\"examples\"><li><em>A good working knowledge of the building regulations is necessary for the job.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>working clothes</strong> (also work clothes) clothes which you wear for work or are designed for people to work in</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>working model</strong> a model that has parts that move</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>working parts</strong> the parts of a machine that move</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>working definition/theory/title</strong> a definition, idea etc that may not be exactly right but is good enough to use when you start working on something</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>working majority</strong> <em>British English</em> enough support in parliament for a government to continue making laws and ruling a country</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>working breakfast/lunch/dinner</strong> a breakfast, lunch etc which is also a business meeting</div><div class=\"sense\"><span class=\"snum\">16</span> <strong>working memory</strong> <em>technical</em> the part of a person’s or computer’s memory which stores information about the thing being worked on now</div></div>","7773":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌworking ˈclass</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[singular]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the group of people in society who traditionally do physical work and do not have much money or power:</div><ul class=\"examples\"><li><em>Marx wrote about the political struggles of the working class.</em></li></ul></div>","7774":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> work‧load</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɜːkləʊd $ ˈwɜːrkloʊd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the amount of work that a person or organization has to do:</div><ul class=\"examples\"><li><em>She’s struggling to cope with the heavy workload.</em></li><li><strong><em>increase/reduce/add to etc somebody’s workload</strong>: We’ve got to find ways of reducing Gail’s workload next year.</em></li></ul></div>","7775":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> work‧man</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɜːkmən $ ˈwɜːrk-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural workmen /-mən/)</span></div><div class=\"entry-body\"><div class=\"sense\">someone who does physical work such as building, repairing things etc</div></div>","7776":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> work‧place</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɜːkpleɪs $ ˈwɜːrk-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the room, building etc where you work</div><ul class=\"examples\"><li><strong><em>in the workplace</strong>: a report into discrimination in the workplace</em></li></ul></div>","7777":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> work‧shop</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɜːkʃɒp $ ˈwɜːrkʃɑːp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a room or building where tools and machines are used for making or repairing things</div><div class=\"sense\"><span class=\"snum\">2</span> a meeting at which people try to improve their skills by discussing their experiences and doing practical exercises</div><ul class=\"examples\"><li><strong><em>writers’/drama/music etc workshop</strong>: They held a number of music workshops and seminars.</em></li></ul></div>","7778":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> work‧sta‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɜːkˌsteɪʃən $ ˈwɜːrk-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a computer that is part of an office computer system</div><div class=\"sense\"><span class=\"snum\">2</span> the desk where an office worker works</div></div>","7779":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɜːld $ wɜːrld/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[our planet/everyone on it]</strong> <strong>the world</strong> the planet we live on, and all the people, cities, and countries on it → earth: GRAMMARYou say in the world: · the fastest sports car in the world ✗Don’t say: the fastest sports car in world | the fastest sport car on the worldGrammar guide ‒ NOUNS</div><ul class=\"examples\"><li><em>Tuberculosis is still common in some parts of the world.</em></li><li><em>At that time China was the most powerful country in the world.</em></li><li><em>the world’s tallest building</em></li><li><em>The Taj Mahal attracts visitors from around the world.</em></li><li><em>Students from all over the world come to study at Oxford.</em></li><li><em>Children are the same the world over.</em></li><li><em>The book has been published throughout the world.</em></li><li><em>There is nothing quite like it anywhere in the world.</em></li><li><em>Europe’s relationship with the rest of the world</em></li><li><em>I decided to take a year off to travel the world.</em></li><li><em>a crime that shocked the world</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>in the world</strong> used to emphasize what you are saying</div><ul class=\"examples\"><li><strong><em>the happiest/most exciting etc... in the world</strong>: I’m the luckiest man in the world! / Bali is my favourite place in the whole world.</em></li><li><em>Off he went, without a care in the world (=not worried about anything at all).</em></li><li><em>Nothing in the world (=nothing at all) can save them now.</em></li><li><em>Don’t worry, we’ve got all the time in the world (=plenty of time so you do not need to hurry).</em></li><li><strong><em>what/who/where/how etc in the world...?</strong> (=used when you are very surprised or annoyed): What in the world are you doing here at seven in the morning?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[the society we live in]</strong> <span class=\"gram\">[singular]</span> the society that we live in, the way people behave, and the kind of life we have:</div><ul class=\"examples\"><li><em>Parents want a better world for their children.</em></li><li><strong><em>the world</strong>: The world is being transformed by information technology. / You had to go into politics if you wanted to change the world.</em></li><li><strong><em>in an ideal/perfect world</strong> (=used to say how you would like things to be): In an ideal world, we would be able to recycle everything.</em></li><li><strong><em>the real world</strong> (=the way life really is, not how people would like it to be or imagine it): In the real world, things are never quite so simple.</em></li><li><strong><em>what is the world coming to?</strong> (=used to say that you do not like the way society is changing): Five pounds just to park your car! I don’t know what the world’s coming to.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[group of countries]</strong> <span class=\"gram\">[singular]</span> a particular group of countries</div><ul class=\"examples\"><li><strong><em>the Western/Arab etc world</strong>: the highest unemployment rate in the Western world</em></li><li><em>the English-speaking world</em></li><li><em>agricultural practices in the developing world</em></li><li><em>the economies of the industrialized world</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[time in history]</strong> <span class=\"gram\">[singular]</span> a particular period in history</div><ul class=\"examples\"><li><strong><em>the modern/ancient world</strong>: the peoples of the ancient world</em></li><li><strong><em>the world of...</strong>: the world of the ancient Greeks</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[somebody’s life and experiences]</strong> <span class=\"gram\">[countable]</span> the life and experiences of a particular person or group of people</div><ul class=\"examples\"><li><strong><em>world of</strong>: the world of children</em></li><li><em>The diary gives us an insight into Hemingway’s world.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[area of activity/work]</strong> <span class=\"gram\">[countable usually singular]</span> a particular area of activity or work, and the people who are involved in it</div><ul class=\"examples\"><li><strong><em>the world of politics/business/work etc</strong>: She knew little about the world of politics.</em></li><li><strong><em>the art/business/academic etc world</strong>: personalities from the sporting world</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[nature/animals/plants]</strong> <strong>the natural/animal/plant world</strong> all of nature, or all animals or plants considered as a group:</div><ul class=\"examples\"><li><em>the wonders of the natural world</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[place/situation]</strong> <span class=\"gram\">[countable usually singular]</span> a particular kind of place or situation, especially one that someone describes or which you imagine</div><ul class=\"examples\"><li><strong><em>world of</strong>: the nightmare world of Orwell’s novel ‘1984’ / a world of lies and secrecy</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[another planet]</strong> <span class=\"gram\">[countable]</span> a place like the Earth in another part of the universe where other things may live:</div><ul class=\"examples\"><li><em>strange creatures from another world</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[something is very different]</strong> <span class=\"gram\">[countable]</span> used in the following phrases to emphasize that something is very different:</div><ul class=\"examples\"><li><em>There’s a world of difference between the US and Europe.</em></li><li><em>I realized we were still worlds apart (=very different, especially concerning your ideas, opinions etc).</em></li><li><em>It was a world away from (=completely different from) the grand hotels she was used to.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>the outside world</strong> the people who live outside a particular place or country – used when the people of that place or country do not often meet other people:</div><ul class=\"examples\"><li><em>Prisoners have little contact with the outside world.</em></li><li><strong><em>be cut off from/closed to/isolated from the outside world</strong>: Parts of the country have been virtually closed to the outside world for 20 years.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>the material world</strong> real things, rather than ideas and beliefs:</div><ul class=\"examples\"><li><em>Is the material world all that exists?</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>for all the world as if/as though/like</strong> <em>literary</em> exactly as if or exactly like:</div><ul class=\"examples\"><li><em>She sat reading her paper, looking for all the world as if nothing had happened.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>out of this world</strong> <em>informal</em> extremely good, enjoyable etc:</div><ul class=\"examples\"><li><em>The graphics and sounds are out of this world.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>do somebody a/the world of good</strong> to be very good for someone’s health or mental state:</div><ul class=\"examples\"><li><em>A bit of fresh air and exercise will do her a world of good.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>in a world of your own/in your own little world</strong> used to say that someone seems to spend a lot of time thinking or imagining things, and does not seem to notice what is happening around them:</div><ul class=\"examples\"><li><em>She was a shy child who seemed to live in a world of her own.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>mean the world to somebody/think the world of somebody</strong> if someone or something means the world to you, or if you think the world of them, they are very important to you and you love or respect them very much:</div><ul class=\"examples\"><li><em>Lee thinks the world of that dog.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>somebody would give the world to do something</strong> used to say that someone would like to do something very much:</div><ul class=\"examples\"><li><em>He would give the world to see her again.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>be/feel on top of the world</strong> <em>informal</em> to feel extremely happy</div><div class=\"sense\"><span class=\"snum\">21</span> <strong>be a man/woman of the world</strong> to be someone who has had many experiences and is not easily shocked</div><div class=\"sense\"><span class=\"snum\">22</span> <strong>not for the world</strong> used to emphasize that you would not do something:</div><ul class=\"examples\"><li><em>I wouldn’t hurt her for the world.</em></li><li><em>I wouldn’t have missed it for the world.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>the world is your oyster</strong> there is no limit to the opportunities that someone has:</div><ul class=\"examples\"><li><em>If you’ve got a good education, the world is your oyster.</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>have the world at your feet</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to be very famous, popular, or successful:</div><ul class=\"examples\"><li><em>In those days the band had the world at their feet.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to be in a position where you have the chance to become very successful:</div><ul class=\"examples\"><li><em>a bright young lad with the world at his feet</em></li></ul><div class=\"sense\"><span class=\"snum\">25</span> <strong>go up/come down in the world</strong> to move to a higher or lower position in society:</div><ul class=\"examples\"><li><em>He’s gone up in the world a bit since I knew him at college.</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> <strong>set the world on fire/alight</strong> <em>spoken</em> to have a big effect or be very successful:</div><ul class=\"examples\"><li><em>Her last film didn’t exactly set the world on fire.</em></li></ul><div class=\"sense\"><span class=\"snum\">27</span> <strong>set/put the world to rights</strong> to discuss or say how the world should be changed to make people’s lives better:</div><ul class=\"examples\"><li><em>We were having a few beers and generally putting the world to rights.</em></li></ul><div class=\"sense\"><span class=\"snum\">28</span> <strong>the Michael Jacksons/Mother Teresas/Microsofts etc of this world</strong> <em>spoken</em> used to talk about a particular kind of person or group, by using one person or group as an example:</div><ul class=\"examples\"><li><em>The US team is new to the soccer scene, and can’t expect to beat the Brazils of this world.</em></li></ul><div class=\"sense\"><span class=\"snum\">29</span> <strong>think the world owes you a living</strong> to think that you should not have to work and that other people will provide you with everything you need – used to show disapproval</div><div class=\"sense\"><span class=\"snum\">30</span> <strong>think (that) the world revolves around you</strong> to think that you are the most important person and everyone else should only be interested in making sure that you have what you want – used to show disapproval</div><div class=\"sense\"><span class=\"snum\">31</span> <strong>the world and his wife</strong> <em>British English</em> everyone or anybody – used when you want to emphasize that a lot of people do something or anyone can do something:</div><ul class=\"examples\"><li><em>It seemed that the world and his wife had come to Madrid.</em></li></ul><div class=\"sense\"><span class=\"snum\">32</span> <strong>come into the world</strong> <em>literary</em> to be born</div><div class=\"sense\"><span class=\"snum\">33</span> <strong>bring a child into the world</strong> <em>literary</em> to have a baby, or help a baby to be born</div><div class=\"sense\"><span class=\"snum\">34</span> <strong>somebody is not long for this world</strong> <em>literary</em> used to say that someone is likely to die soon</div><div class=\"sense\"><span class=\"snum\">35</span> <strong>[normal life]</strong> <strong>the world</strong> normal life in society, as opposed to a religious way of life, especially in a monastery etc:</div><ul class=\"examples\"><li><em>She renounced the world and entered a convent.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> existing in, involving, or affecting all or most countries in the world → world war</div><ul class=\"examples\"><li><strong><em>the World Cup/Championships etc</strong> (=a competition involving people from many countries): He won the world title in 2001.</em></li><li><em>the reigning Formula One world champion</em></li><li><strong><em>world trade/economy etc</strong>: the impact of the crisis on the world economy</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a world figure is one of the most important people in the world: → world power</div><ul class=\"examples\"><li><em>a meeting of world leaders</em></li><li><em>a world authority on climate change</em></li></ul></div></div>","7780":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌworld-ˈclass</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">among the best in the world:</div><ul class=\"examples\"><li><em>a world-class tennis champion</em></li><li><em>world-class research facilities</em></li></ul></div>","7781":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> world‧wide</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌwɜːldˈwaɪd◂ $ ˌwɜːrld-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">everywhere in the world → globally:</div><ul class=\"examples\"><li><em>We have offices in over 56 countries worldwide.</em></li><li><em>cars with a worldwide reputation for reliability</em></li></ul></div>","7782":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɜːm $ wɜːrm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a long thin creature with no bones and no legs that lives in soil → earthworm, lugworm</div><div class=\"sense\"><span class=\"snum\">2</span> the young form of an insect, which looks like a short worm → glow-worm, silkworm, woodworm</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>have worms</strong> if a person or animal has worms, they have legless parasites (=small creatures that eat their food or their blood) in their body → roundworm, tapeworm</div><div class=\"sense\"><span class=\"snum\">4</span> someone who you do not like or respect</div><div class=\"sense\"><span class=\"snum\">5</span> a type of computer virus that can make copies of itself and destroy information on computers that are connected to each other</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>the worm turns</strong> <em>literary</em> used to say that someone who normally obeys someone without complaining suddenly refuses to do this</div></div>","7783":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a worn object is old and damaged, especially because it has been used a lot:</div><ul class=\"examples\"><li><em>a worn patch on the carpet</em></li><li><em>well worn stone steps</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who looks worn seems tired</div></div>","7784":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wor‧ried</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwʌrid $ ˈwɜːrid/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> unhappy because you keep thinking about a problem, or about something bad that might happen:</div><ul class=\"examples\"><li><em>She gave me a worried look.</em></li><li><strong><em>worried about</strong>: I’m really worried about my brother.</em></li><li><strong><em>worried by</strong>: Local people are worried by the rise in crime.</em></li><li><strong><em>worried (that)</strong>: I was worried we wouldn’t have enough money.</em></li><li><em>His parents must be worried sick (=extremely worried).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>you had me worried</strong> <em>spoken</em> used to say that someone made you feel anxious because you did not properly understand what they said, or did not realize that it was a joke:</div><ul class=\"examples\"><li><em>You had me worried there for a minute!</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the worried well</strong> healthy people who are worried that they might be ill or become ill:</div><ul class=\"examples\"><li><em>Health tests for the worried well should be strictly regulated.</em></li></ul></div>","7785":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wor‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwʌri $ ˈwɜːri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\">(past tense and past participle worried, present participle worrying, third person singular worries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[be anxious]</strong> <span class=\"gram\">[intransitive]</span> to be anxious or unhappy about someone or something, so that you think about them a lot GRAMMAR: Prepositions with worry• You worry about someone or something: · Don’t worry about me.· They worry about the cost.• If you worry over something, you spend a lot of time worrying about it: · She worries over how to help him. ✗Don’t say: worry for something</div><ul class=\"examples\"><li><strong><em>worry about</strong>: I worry about my daughter. / You’ve really got no need to worry about your weight.</em></li><li><strong><em>worry (that)</strong>: She worried that she wasn’t doing enough to help.</em></li><li><strong><em>worry over</strong>: Dad worries over the slightest thing.</em></li><li><em>Don’t tell Mum about this – she’s got enough to worry about (=she already has a lot of problems or is very busy).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>don’t worry</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used when you are trying to make someone feel less anxious:</div><ul class=\"examples\"><li><em>Don’t worry, darling, Daddy’s here.</em></li><li><strong><em>worry if</strong>: Don’t worry if you can’t finish all the questions.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to tell someone that they do not need to do something</div><ul class=\"examples\"><li><strong><em>worry about</strong>: Don’t worry about sorting them out – I’ll do it later.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> used to tell someone that you will definitely do something:</div><ul class=\"examples\"><li><em>Don’t you worry, I’ll make sure he does his fair share.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[make somebody anxious]</strong> <span class=\"gram\">[transitive]</span> to make someone feel anxious about something:</div><ul class=\"examples\"><li><em>The recent changes in the Earth’s climate are beginning to worry scientists.</em></li><li><em>I didn’t tell Mum and Dad – I didn’t want to worry them.</em></li><li><strong><em>what worries me is.../the (only) thing that worries me is...</strong>: The only thing that worries me is the food. I don’t want to get food poisoning.</em></li><li><strong><em>it worries somebody that/how/when</strong>: Doesn’t it worry you that Sarah spends so much time away from home?</em></li><li><strong><em>worry yourself</strong> (=feel anxious, especially when there is no need to): You’re worrying yourself unnecessarily.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>not to worry</strong> <em>British English</em> <em>spoken</em> used to say that something is not important:</div><ul class=\"examples\"><li><em>Not to worry, we can always go another time.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>nothing to worry about</strong> <em>spoken</em> used to tell someone that something is not as serious or difficult as they think:</div><ul class=\"examples\"><li><em>It’s just a check-up – nothing to worry about.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[annoy]</strong> <span class=\"gram\">[transitive]</span> to annoy someone <em>SYN bother</em>:</div><ul class=\"examples\"><li><em>The heat didn’t seem to worry him.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[animal]</strong> <span class=\"gram\">[transitive]</span> if a dog worries sheep, it tries to bite or kill them</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\">(plural worries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a problem that you are anxious about or are not sure how to deal with RegisterIn written English, people often prefer to use concern rather than worry, because it sounds more formal:· One of voters’ key concerns is crime.</div><ul class=\"examples\"><li><strong><em>somebody’s main/biggest/real etc worry</strong>: My main worry is finding somewhere to live.</em></li><li><em>I had a lot of financial worries.</em></li><li><strong><em>be a worry to/for somebody</strong>: Money was always a big worry for us.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> the feeling of being anxious about something</div><ul class=\"examples\"><li><strong><em>be frantic/sick/desperate etc with worry</strong> (=feel extremely anxious): His mother was desperate with worry.</em></li><li><em>He’s been a constant source of worry.</em></li><li><strong><em>worry about</strong>: We had no worries about safety.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>no worries</strong> <em>British English</em> <em>spoken</em> used to agree to what someone wants and to say that it will be no problem:</div><ul class=\"examples\"><li><em>‘Can you deliver on Thursday?’ ‘Yeah, no worries, mate.’</em></li></ul></div></div>","7786":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wor‧ry‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwʌri-ɪŋ $ ˈwɜː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\">something that is worrying makes you feel anxious or worried:</div><ul class=\"examples\"><li><em>The situation is extremely worrying.</em></li><li><em>This is a worrying development for small businesses.</em></li><li><em>It’s been a worrying few weeks for us all.</em></li></ul></div>","7787":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɜːs $ wɜːrs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[the comparative of bad]</span> more unpleasant, bad, or severe → better</div><ul class=\"examples\"><li><strong><em>worse than</strong>: The violence was worse than we expected.</em></li><li><em>The traffic is much worse after five o&#x27;clock.</em></li><li><em>The weather was a lot worse this year.</em></li><li><em>Conditions will get worse as the winter continues.</em></li><li><em>High inflation will make unemployment worse.</em></li><li><em>Don’t say anything, you’ll only make matters worse.</em></li><li><em>The bullying got worse and worse until finally he had to leave the school.</em></li><li><em>There’s nothing worse than being robbed while you’re on holiday.</em></li><li><em>The school’s not perfect, but I suppose it could be worse.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> more ill than before:</div><ul class=\"examples\"><li><em>If she’s worse in the morning, I’ll call the doctor.</em></li><li><em>I was worried because he seemed to be getting worse rather than better.</em></li><li><em>The tablets seemed to make him worse.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be none the worse for something</strong> to not have been harmed by something:</div><ul class=\"examples\"><li><em>She seemed none the worse for her night out in the cold.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>worse luck</strong> <em>spoken</em> used to say that you are disappointed or annoyed by something:</div><ul class=\"examples\"><li><em>I’ve got one more year of college, worse luck!</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>somebody could do worse than do something</strong> <em>spoken</em> used to say that you think that someone should do something:</div><ul class=\"examples\"><li><em>He could do worse than marry Eleanor.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>go from bad to worse</strong> to continue getting worse:</div><ul class=\"examples\"><li><em>Things went from bad to worse, and in the end she lost her job.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>the worse for wear</strong> (also the worse for drink<em>British English</em>) <em>informal</em> drunk</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[the comparative of badly]</span></span></div><div class=\"entry-body\"><div class=\"sense\">in a more severe or serious way than before → better</div><ul class=\"examples\"><li><strong><em>worse than</strong>: By lunch time it was raining worse than ever.</em></li><li><em><span class=\"gram\">[sentence adverb]</span>: The business could become less profitable or, even worse, could close down. / Suppose Rose, or worse still, Peter had seen the photograph?</em></li></ul></div></div>","7788":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wors‧en</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɜːsən $ ˈwɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to become worse, or make something worse <em>OPP improve</em> → deteriorate:</div><ul class=\"examples\"><li><em>A lot of teachers expect the situation to worsen over the next few years.</em></li><li><em>Interfering now could worsen the problem.</em></li></ul></div>","7789":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wor‧ship</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɜːʃɪp $ ˈwɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle worshipped, present participle worshipping also worshiped, worshiping American English)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to show respect and love for a god, especially by praying in a religious building:</div><ul class=\"examples\"><li><em>They all worship the same god.</em></li><li><em>a church where people have worshipped for hundreds of years</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to admire and love someone very much:</div><ul class=\"examples\"><li><em>He absolutely worships her.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>worship the ground somebody walks on</strong> to admire or love someone so much that you cannot see their faults</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the activity of praying or singing in a religious building in order to show respect and love for a god</div><ul class=\"examples\"><li><strong><em>in worship</strong>: They bowed their heads in worship.</em></li><li><strong><em>worship of</strong>: Worship of the old gods still continues in remote areas of the country.</em></li><li><em>The ceremony must take place in a recognized place of worship.</em></li><li><em>We were invited to join in their act of worship (=religious ceremony).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>Your/His Worship</strong> <em>British English</em> <em>formal</em> used to talk to or about a public official such as a mayor or magistrate</div></div></div>","7790":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɜːst $ wɜːrst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[the superlative of bad]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[only before noun]</span> worse than anything or anyone else → best:</div><ul class=\"examples\"><li><em>This is the worst recession for fifty years.</em></li><li><em>My worst fear was that we would run out of food.</em></li><li><em>What is the worst possible thing that can happen?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be your own worst enemy</strong> to cause a lot of problems for yourself because of your own behaviour</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>come off worst</strong> to lose a fight or argument</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>the worst</strong> the person or thing that is worse than all others → the best</div><ul class=\"examples\"><li><strong><em>worst (that)</strong>: This year’s harvest is the worst that people can remember. / Last year was by far the worst (=much worse than any other) for road accidents.</em></li><li><em>I think the worst is over now.</em></li><li><em>The worst of it is (=the worst part of the situation is), I can’t tell anyone what’s happening.</em></li><li><strong><em>at its/his etc worst</strong>: You saw the garden at its worst, I’m afraid (=when it is worse than at any other time).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the worst of something</strong> most of something, or the most unpleasant or difficult part of it:</div><ul class=\"examples\"><li><em>The worst of the storm seemed to be over.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>expect/fear the worst</strong> to expect or fear that something will not be successful or something bad will happen:</div><ul class=\"examples\"><li><em>When it got so late and they still weren’t home, I began to fear the worst.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>get/have the worst of it</strong> <em>spoken</em> to lose a fight or argument</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>at (the) worst</strong> if things are as bad as they can be:</div><ul class=\"examples\"><li><em>Choosing the right software can be time-consuming at best and confusing or frustrating at worst.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>do your/his/her/their worst</strong> used to say that someone can try to harm you but they will not be able to:</div><ul class=\"examples\"><li><em>They can do their worst now, because I’m leaving in three weeks.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>if the worst comes to the worst</strong> <em>especially British English</em>, if worst comes to worst<em>especially American English</em> if the situation develops in the worst possible way:</div><ul class=\"examples\"><li><em>If the worst comes to the worst, we’ll sell the car.</em></li></ul></div></div>","7791":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wɜːθ $ wɜːrθ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>be worth something</strong> ► Worth is not a verb. Do not say that something ‘worths’ something.</div><div class=\"subsense\"><span class=\"subnum\">a)</span> to have a value in money:</div><ul class=\"examples\"><li><em>The house must be worth quite a lot of money now.</em></li><li><em>One of the pictures is worth £50,000.</em></li><li><em>Do you know how much the ring is worth?</em></li><li><em>This art collection is worth a fortune (=worth a very large amount of money).</em></li><li><strong><em>be worth nothing/not be worth anything</strong>: It’s a very old machine so I shouldn’t think it’s worth anything.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to have money or possessions that have value:</div><ul class=\"examples\"><li><em>I’ve heard that he’s worth over $2 million.</em></li><li><em>The man who founded the company must be worth a fortune.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be worth (doing) something</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to say that something is interesting, useful, or helpful:</div><ul class=\"examples\"><li><em>A lot of the small towns in the area are definitely worth visiting.</em></li><li><em>The film is well worth seeing.</em></li><li><strong><em>worth a trip/visit etc</strong>: The local museum is worth a visit.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to say that someone should do something because they will gain something from it</div><ul class=\"examples\"><li><strong><em>be worth doing something</strong>: It’s worth checking the details of the contract before you sign it. / It’s well worth getting there early if you want a good seat.</em></li><li><strong><em>be worth the time/effort/work</strong>: It was a great evening, and definitely worth all the hard work.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be worth it</strong> <em>informal</em> used to say that you gain something from an action:</div><ul class=\"examples\"><li><em>It was a lot of hard work, but it was worth it.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be not worth it</strong> <em>informal</em> used to say that you do not gain anything from an action:</div><ul class=\"examples\"><li><em>I thought about trying to talk to him about it, but decided it wasn’t worth it.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be worth somebody’s while (to do/doing something)</strong> <em>spoken</em> used to say that someone should spend time or money on something because they will gain something from it:</div><ul class=\"examples\"><li><em>It might be worth your while to talk to the head of department.</em></li><li><em>Some people feel it’s not worth their while working if they can get money from the state.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>make it worth somebody’s while</strong> <em>spoken</em> to offer something to someone so that they will do something for you:</div><ul class=\"examples\"><li><em>He promised to make it worth our while.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>what’s it worth (to you)?</strong> <em>spoken</em> used humorously to ask someone how they will reward you if you do something for them</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>for what it’s worth</strong> <em>spoken</em> used when you are giving someone information, to say that you are not sure how useful it is:</div><ul class=\"examples\"><li><em>Here’s the list of names, for what it’s worth.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>for all you are/he is etc worth</strong> with as much effort as possible:</div><ul class=\"examples\"><li><em>He was pulling the rope for all he was worth.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>worth his/her salt</strong> doing their job well or deserving respect:</div><ul class=\"examples\"><li><em>Any player worth his salt would love to play for his country.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>worth your/its etc weight in gold</strong> very useful:</div><ul class=\"examples\"><li><em>In these mountains, an experienced guide is worth his weight in gold.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>ten pounds’ worth/$500 worth etc of something</strong> an amount of something worth ten pounds, $500 etc:</div><ul class=\"examples\"><li><em>a chance to win £2,000 worth of computing equipment</em></li><li><em>The fire caused thousands of pounds’ worth of damage.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>ten minutes’ worth/a week’s worth etc of something</strong> something that takes ten minutes, a week etc to happen, do, or use:</div><ul class=\"examples\"><li><em>We had only three days’ worth of food left.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> how good or useful something is or how important it is to people <em>SYN value</em>:</div><ul class=\"examples\"><li><em>The new computer system has already proved its worth.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> how much money something is worth <em>SYN value</em>:</div><ul class=\"examples\"><li><em>It is difficult to estimate the current worth of the company.</em></li></ul></div></div>","7792":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> worth‧less</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɜːθləs $ ˈwɜːrθ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> something that is worthless has no value, importance, or use <em>OPP valuable</em>:</div><ul class=\"examples\"><li><em>The house was full of worthless junk.</em></li><li><em>The information was worthless to me.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a worthless person has no good qualities or useful skills <em>SYN useless</em>:</div><ul class=\"examples\"><li><em>His parents had made him feel worthless.</em></li></ul></div>","7793":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> worth‧while</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌwɜːθˈwaɪl◂ $ ˌwɜːrθ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">if something is worthwhile, it is important or useful, or you gain something from it: ► see thesaurus at useful</div><ul class=\"examples\"><li><em>He wanted to do a worthwhile job.</em></li><li><em>We decided to give the money to a worthwhile cause (=one that helps people).</em></li><li><strong><em>it is worthwhile to do something</strong>: I thought it was worthwhile to clarify the matter.</em></li><li><strong><em>it is worthwhile doing something</strong>: It wasn’t worthwhile continuing with the project.</em></li></ul></div>","7794":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wor‧thy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwɜːði $ ˈwɜːrði/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[only before noun]</span> deserving respect from people:</div><ul class=\"examples\"><li><em>Leeds United were worthy winners of the competition.</em></li><li><em>a worthy opponent</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be worthy of something</strong> to deserve to be thought about or treated in a particular way:</div><ul class=\"examples\"><li><em>A couple of other books are worthy of mention.</em></li><li><em>a teacher who is worthy of respect</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be worthy of somebody</strong> <em>informal</em> to be as good as something that a particular person would do:</div><ul class=\"examples\"><li><em>a goal that was worthy of any of the great footballers of the world</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>I’m/We’re not worthy</strong> <em>spoken</em> used humorously to say that you consider it a great honour to be with someone because they are famous, or much more skilful at doing something than you are</div><div class=\"sense\"><span class=\"snum\">5</span> <em>formal</em> trying to help other people:</div><ul class=\"examples\"><li><em>The money will go to a worthy cause.</em></li><li><em>I’m sure his motives were worthy.</em></li></ul></div>","7795":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wʊd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[past intentions/expectations]</strong> used to say what someone intended to do or expected to happen:</div><ul class=\"examples\"><li><em>They said they would meet us at 10.30 at the station.</em></li><li><em>She said she wouldn’t be coming to the library anymore.</em></li><li><em>Arnold knew he would be tired the next day.</em></li><li><em>It would soon be dark.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[imagined situations]</strong> GRAMMAR: Choosing the right tenseYou usually use would in the main clause, and a past tense in the ‘if’ clause: · I would be surprised if he agreed.· She would love it if you came. ✗Don’t say: I would be surprised if he would agree.Grammar guide ‒ VERBS</div><div class=\"subsense\"><span class=\"subnum\">a)</span> used when talking about the result of a possible or imagined situation or event, or describing one:</div><ul class=\"examples\"><li><em>What would you do if you won a million pounds?</em></li><li><em>I would be amazed if I got the job.</em></li><li><em>It would be lovely to see you.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used when talking about something that did not happen, or a situation that cannot exist:</div><ul class=\"examples\"><li><em>I would have phoned you, but there wasn’t time.</em></li><li><em>Alex would never have found out if you hadn’t told him.</em></li><li><em>What would have happened if I hadn’t been here?</em></li><li><em>Everything would be very different if your father were still alive.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> used to mention an unlikely situation or event that you want to happen:</div><ul class=\"examples\"><li><em>I wish they would come and visit us.</em></li><li><em>If only he would listen to me.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[past habits]</strong> used to say that something happened often or regularly in the past:</div><ul class=\"examples\"><li><em>When we worked in the same office, we would often have coffee together.</em></li><li><em>On summer evenings they would sit out in the garden.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[requesting]</strong> <em>spoken</em> used to ask someone politely to do something:</div><ul class=\"examples\"><li><em>Would you shut the window, please?</em></li><li><em>Would you mind waiting outside?</em></li><li><em>Would someone please tell me what is going on?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[offering/inviting]</strong> <em>spoken</em> used to offer something to someone or invite them somewhere politely:</div><ul class=\"examples\"><li><em>Would you like a coffee?</em></li><li><em>We’re going to the theatre this evening. Would you be interested in coming?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[what somebody wants]</strong> <em>spoken</em> used to say that someone wants something or wants to do something</div><ul class=\"examples\"><li><strong><em>would like/love/prefer</strong>: Yes, please, I’d love a coffee. / My parents would like to meet you. / Claudia would have liked to refuse (=wanted to refuse), but she didn’t dare.</em></li><li><em>I’d hate (=I do not want) to disappoint you.</em></li><li><strong><em>would rather/sooner</strong> (=used to say what someone prefers): I’d rather stay in this evening, if that’s all right with you.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[past purpose]</strong> used after ‘so that’ to show that someone was trying to make something happen or prevent something:</div><ul class=\"examples\"><li><em>We packed all the books in wooden boxes so that they wouldn’t get damaged.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>would not</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to say that someone refused to do something:</div><ul class=\"examples\"><li><em>He wouldn’t give us any money.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to say that something did not happen, even though someone was trying to make it happen:</div><ul class=\"examples\"><li><em>The door wouldn’t open, no matter how hard she pushed.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[advice]</strong> <em>spoken</em> used when giving or asking for advice:</div><ul class=\"examples\"><li><em>I’d try to get there early if you can.</em></li><li><em>I would talk to the doctor if I were you.</em></li><li><em>What would you do if you were in my position?</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>I would think/imagine/say</strong> <em>spoken</em> used to give your opinion about something when you are not very sure about it:</div><ul class=\"examples\"><li><em>I would think you’d be happier in a different school.</em></li><li><em>‘Will it cost a lot?’ ‘I would imagine so.’</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[typical behaviour]</strong> <em>spoken</em> used to say that an action is typical or expected – usually used to show disapproval:</div><ul class=\"examples\"><li><em>You would go and spoil it, wouldn’t you!</em></li><li><em>She insists that she did nothing wrong, but then she would say that, wouldn’t she?</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>would that...</strong> <em>literary</em> used to express a strong wish or desire <em>SYN if only</em>:</div><ul class=\"examples\"><li><em>Would that we had seen her before she died.</em></li></ul></div>","7796":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈwould-be</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><strong>would-be actor/murderer etc</strong> someone who hopes to have a particular job or intends to do a particular thing</div></div>","7797":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /wuːnd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an injury to your body that is made by a weapon such as a knife or a bullet: ► see thesaurus at injury</div><ul class=\"examples\"><li><em>A nurse cleaned and bandaged the wound.</em></li><li><em>It took several months for his wounds to heal.</em></li><li><strong><em>suffer/receive a wound</strong>: Several of the victims suffered severe stab wounds.</em></li><li><strong><em>head/leg etc wound</strong>: He was treated in hospital for head wounds.</em></li><li><strong><em>stab/knife/gunshot wound</strong>: He died of gunshot wounds.</em></li><li><em>The doctor said it was only a flesh wound (=one that does not cut the skin very deeply).</em></li><li><em>a gaping wound (=one that is wide and open) on his thigh</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a feeling of emotional or mental pain that you get when someone says or does something unpleasant to you:</div><ul class=\"examples\"><li><em>It will take much longer for the mental wounds to heal.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>open old wounds</strong> to remind someone of unpleasant things that happened in the past</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to injure someone with a knife, gun etc: ► see thesaurus at hurt</div><ul class=\"examples\"><li><em>Gunmen killed two people and wounded six others in an attack today.</em></li><li><strong><em>be badly/seriously/critically etc wounded</strong>: Five people were killed and many others were seriously wounded in the attack.</em></li><li><strong><em>be mortally/fatally wounded</strong> (=be wounded so badly that you die)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make someone feel unhappy or upset <em>SYN hurt</em>:</div><ul class=\"examples\"><li><em>I was deeply wounded by his comments.</em></li><li><em>He made some very wounding remarks.</em></li></ul></div></div>","7798":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wound‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈwuːndɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> injured by a weapon such as a gun or knife:</div><ul class=\"examples\"><li><em>a wounded soldier</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> very upset because of something that someone has said or done:</div><ul class=\"examples\"><li><em>It was only wounded pride that stopped him from apologizing.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the wounded</strong> <span class=\"gram\">[plural]</span> people who have been injured, especially in a war:</div><ul class=\"examples\"><li><em>providing medical care for the wounded</em></li><li><strong><em>the walking wounded</strong> (=people who have been injured but are well enough to walk)</em></li></ul></div>","7799":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /waʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">used when you think something is very impressive or surprising:</div><ul class=\"examples\"><li><em>Wow! Look at that!</em></li></ul></div>","7800":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ræp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle wrapped, present participle wrapping)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (also wrap up) to put paper or cloth over something to cover it</div><ul class=\"examples\"><li><strong><em>wrap something in something</strong>: The present was beautifully wrapped in gold paper.</em></li><li><strong><em>wrap something around somebody/something</strong>: Ella wrapped a thick coat around her shoulders. / He wrapped a bandage around my injured wrist. / I’ve still got a few Christmas presents to wrap up.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if you wrap your arms, legs, or fingers around something, you use them to hold it</div><ul class=\"examples\"><li><strong><em>wrap something around somebody/something</strong>: He wrapped his arms around her waist.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a piece of thick cloth that a woman wears around her shoulders → shawl</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> a type of thin clear plastic that is used to cover food <em>SYN clingfilm</em></div><div class=\"sense\"><span class=\"snum\">3</span> <strong>keep something under wraps</strong> to keep something secret:</div><ul class=\"examples\"><li><em>The project has been kept under wraps for years.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>take the wraps off something</strong> to show or tell people about something new or secret</div><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> a type of sandwich made with thin bread which is rolled around meat, vegetables etc</div><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[singular]</span> the end of a day’s filming:</div><ul class=\"examples\"><li><em>OK everybody, it’s a wrap!</em></li></ul></div></div>","7801":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /rek/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to completely spoil something so that it cannot continue in a successful way <em>SYN ruin</em>:</div><ul class=\"examples\"><li><em>Injury threatened to wreck his sporting career.</em></li><li><em>It was drink that wrecked their marriage.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to damage something such as a building or vehicle so badly that it cannot be repaired: ► see thesaurus at destroy</div><ul class=\"examples\"><li><em>The car was completely wrecked in the accident.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> if a ship is wrecked, it is badly damaged and sinks <em>SYN shipwreck</em>:</div><ul class=\"examples\"><li><em>The ship was wrecked off the coast of Africa.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[car/plane]</strong> a car, plane, or train that has been damaged very badly, especially in a crash: ► see thesaurus at accident</div><ul class=\"examples\"><li><em>He was still alive when they pulled him from the wreck.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[ship]</strong> a ship that has sunk <em>SYN shipwreck</em></div><ul class=\"examples\"><li><strong><em>wreck of</strong>: Divers discovered the wreck of an old German warship.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[person]</strong> <em>informal</em> someone who is very nervous, tired, or unhealthy:</div><ul class=\"examples\"><li><em>He looked a complete wreck.</em></li><li><strong><em>nervous/emotional wreck</strong>: The attack had left her an emotional wreck.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[accident]</strong> <em>American English</em> an accident involving cars or other vehicles <em>SYN crash</em></div><ul class=\"examples\"><li><strong><em>car/train/plane wreck</strong>: My father died in a car wreck.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[place]</strong> a place that is very untidy:</div><ul class=\"examples\"><li><em>When you’re here, this place is a wreck!</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[old car]</strong> <em>informal</em> an old car that is in a very bad condition</div></div></div>","7802":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wreck‧age</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈrekɪdʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[singular, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the parts of something such as a plane, ship, or building that are left after it has been destroyed in an accident:</div><ul class=\"examples\"><li><em>Firemen managed to pull some survivors from the wreckage.</em></li><li><strong><em>wreckage of</strong>: Accident investigators will examine the wreckage of the plane.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the parts of someone’s relationships, hopes, or plans that remain after they have been spoiled</div><ul class=\"examples\"><li><strong><em>wreckage of</strong>: She still hoped to salvage something from the wreckage of her marriage.</em></li></ul></div>","7803":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wres‧tle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈresəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to fight someone by holding them and pulling or pushing them</div><ul class=\"examples\"><li><strong><em>wrestle with</strong>: The two men wrestled with each other.</em></li><li><em>Police officers wrestled him to the ground.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to move something or try to move it when it is large, heavy, or difficult to move</div><ul class=\"examples\"><li><strong><em>wrestle with</strong>: Ray continued to wrestle with the wheel.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>wrestle with something</strong> to try to understand or find a solution to a difficult problem:</div><ul class=\"examples\"><li><em>I have been wrestling with this problem for quite some time.</em></li></ul></div>","7804":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /rɪst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the part of your body where your hand joins your arm → body</div><ul class=\"examples\"><li><strong><em>on/around your wrist</strong>: She had a gold watch on her wrist.</em></li></ul></div>","7805":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /raɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense wrote /rəʊt $ roʊt/, past participle written /ˈrɪtn/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[book/article/poem etc]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[intransitive, transitive]</span> to produce a new book, article, poem etc:</div><ul class=\"examples\"><li><em>He wrote some very famous books.</em></li><li><em>Who wrote ‘Harry Potter’?</em></li><li><em>I can’t come with you – I have an essay to write.</em></li><li><strong><em>write about</strong>: O&#x27;Brien often writes about her native Ireland.</em></li><li><strong><em>well/badly/poorly etc written</strong>: The article is very well written.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[intransitive]</span> someone who writes earns money by writing books, plays, articles etc:</div><ul class=\"examples\"><li><em>Sean decided he wanted to write, and quit his job.</em></li><li><strong><em>write for</strong>: Maureen Dowd writes for ‘The New York Times’.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[letter]</strong> <span class=\"gram\">[intransitive, transitive]</span> to put words in a letter to someone GRAMMAR: Patterns with write• You write to someone: · She writes to me every month.• In American English, you can also write someone: · She writes me every month.• You write someone a letter, note, story etc: · Please write me a letter soon. ✗Don’t say: Please write to me a letter soon.• You write to someone about a subject or an experience: · He wrote to me about his trip to France. ✗Don’t say: He wrote to me his trip to France.• Write is often used in the progressive: · I am writing to tell you something important.</div><ul class=\"examples\"><li><strong><em>write to</strong>: I’ve written to my MP, and to the city council.</em></li><li><strong><em>write somebody<em>American English</em></strong>: Chris hasn’t written me for a long time.</em></li><li><em>I wrote her several letters, but she didn’t reply.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[form words]</strong> <span class=\"gram\">[intransitive, transitive]</span> to form letters or numbers with a pen or pencil:</div><ul class=\"examples\"><li><em>Kerry could read and write when she was five.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[state something]</strong> <span class=\"gram\">[transitive]</span> to state something in a book, letter, advertisement etc, or on a label</div><ul class=\"examples\"><li><strong><em>write (that)</strong>: Isabella wrote that she was dying, and asked him to visit her for the last time.</em></li><li><strong><em>be written on something</strong>: The price is written on the label.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[music/song]</strong> <span class=\"gram\">[transitive]</span> to write a piece of music or a song:</div><ul class=\"examples\"><li><em>Mozart wrote the music.</em></li><li><em>The song was originally written by Leonard Cohen.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[computer program]</strong> <span class=\"gram\">[transitive]</span> to make a program for a computer to use:</div><ul class=\"examples\"><li><em>He writes software programs for financial institutions.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[a computer records something]</strong> <span class=\"gram\">[intransitive, transitive]</span> if a computer writes something, it records it on a disk or in its memory</div><ul class=\"examples\"><li><strong><em>write to/onto</strong>: data that had been written to disk</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[cheque/document etc]</strong> (also write out) <span class=\"gram\">[transitive]</span> to write information on a cheque, form etc:</div><ul class=\"examples\"><li><em>Wouldn’t it be easier if I just wrote a cheque for the lot?</em></li><li><em>The doctor wrote me a prescription for sleeping pills.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[pen]</strong> <span class=\"gram\">[intransitive]</span> if a pen writes, it works properly:</div><ul class=\"examples\"><li><em>Do any of these pens write?</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>have something/be written all over your face</strong> to show very clearly what you are feeling or thinking:</div><ul class=\"examples\"><li><em>He had guilt written all over his face.</em></li><li><em>I know you’re lying, Tyrell – it’s written all over your face.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>have something written all over it</strong> to show a particular quality or fact very clearly:</div><ul class=\"examples\"><li><em>This awful film has ‘career-killer’ written all over it for the actors involved.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>nothing to write home about</strong> <em>informal</em> not particularly good or special:</div><ul class=\"examples\"><li><em>The hotel was good, but the food was nothing to write home about.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>somebody wrote the book on something</strong> <em>spoken</em> used to say that someone knows a lot about a subject or is very good at an activity:</div><ul class=\"examples\"><li><em>Motorola wrote the book on quality control.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>that’s all she wrote</strong> <em>American English</em> <em>spoken</em> used to mean that you cannot stop what happens next in a situation, especially when it is bad</div></div>","7806":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> writ‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈraɪtə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who writes books, stories etc, especially as a job → author, playwright:</div><ul class=\"examples\"><li><em>She’s one of my favourite writers.</em></li><li><em>a science-fiction writer</em></li><li><strong><em>writer on</strong>: a well-known writer on American music</em></li><li><strong><em>writer of</strong>: a writer of children’s stories</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who has written something or who writes in a particular way:</div><ul class=\"examples\"><li><em>He’s always been a sloppy writer.</em></li><li><strong><em>writer of</strong>: the writer of the previous message on this topic</em></li></ul></div>","7807":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> writ‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈraɪtɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> words that have been written or printed:</div><ul class=\"examples\"><li><em>What does the writing on the back say?</em></li><li><em>a T-shirt with Japanese writing on it</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> books, poems, articles etc, especially those by a particular writer or about a particular subject:</div><ul class=\"examples\"><li><em>Some of his most powerful writing is based on his childhood experiences.</em></li><li><strong><em>travel/feminist/scientific etc writing</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> the activity of writing books, stories etc:</div><ul class=\"examples\"><li><em>In 1991 she retired from politics and took up writing as a career.</em></li><li><em>a short story that stands out as a brilliant piece of writing</em></li><li><em>a class in creative writing (=a subject studied at school or college, where you write your own stories, poems etc)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> the particular way that someone writes with a pen or pencil <em>SYN handwriting</em>:</div><ul class=\"examples\"><li><em>Your writing is very neat.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[uncountable]</span> the skill of writing:</div><ul class=\"examples\"><li><em>At this age we concentrate on the children’s reading and writing skills.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>in writing</strong> if you get something in writing, it is official proof of an agreement, promise etc:</div><ul class=\"examples\"><li><em>Could you put that in writing, please?</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>writings</strong> <span class=\"gram\">[plural]</span> the books, stories etc that an important writer has written:</div><ul class=\"examples\"><li><em>Darwin’s scientific writings</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>the writing is on the wall</strong> (also see/read the writing on the wall) used to say that it seems very likely that something will not exist much longer or someone will fail</div><ul class=\"examples\"><li><strong><em>writing for</strong>: The writing is on the wall for old manufacturing industries.</em></li></ul></div>","7808":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> recorded in writing:</div><ul class=\"examples\"><li><em>the development of written language</em></li><li><strong><em>written agreement/reply/statement/report etc</strong>: Please send a cheque with written confirmation of your booking.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>written test/exam</strong> a test etc in which you have to write the answers → oral</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>the written word</strong> <em>formal</em> writing as a way of expressing ideas, emotions etc, as opposed to speaking</div></div>","7809":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /rɒŋ $ rɒːŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[not correct]</strong> not correct, and not based on true facts <em>OPP right</em>:</div><ul class=\"examples\"><li><em>Your calculations must be wrong.</em></li><li><em>I think I got question 3 wrong.</em></li><li><strong><em>it is wrong to do something</strong>: It is wrong to assume that technological advance brings a higher quality of life.</em></li><li><em>I wish you’d stop trying to prove me wrong (=show that I am wrong) all the time.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be wrong (about somebody/something)</strong> to not be right in what you think or believe about someone or something <em>SYN mistaken</em> <em>OPP right</em>:</div><ul class=\"examples\"><li><em>No, you’re wrong. Brett wouldn’t do a thing like that.</em></li><li><em>I was wrong about the new guy – he’s not Belgian, he’s French.</em></li><li><em>That’s where you’re wrong! We never slept together.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[problems]</strong> used to describe a situation where there are problems, or when someone is ill or unhappy</div><ul class=\"examples\"><li><strong><em>there is something wrong/something is wrong</strong>: When he didn’t come back that night, I knew that something was wrong.</em></li><li><strong><em>wrong with</strong>: What is wrong with our society? People just don’t seem to care anymore.</em></li><li><em>Is anything wrong? You haven’t said more than two words since you got here.</em></li><li><em>Dave’s got something wrong with his foot.</em></li><li><em>Don’t worry, there’s nothing wrong.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[not the right one]</strong> not the one that you intended or the one that you really want <em>OPP right</em>:</div><ul class=\"examples\"><li><em>The letter was delivered to the wrong address.</em></li><li><em>driving on the wrong side of the road</em></li><li><em>You’ve got the wrong man. I didn’t kill her.</em></li><li><em>I think we went the wrong way at that last turning.</em></li><li><em>There’s no one called Julia here. You must have the wrong number (=wrong telephone number).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[not morally right]</strong> not morally right or acceptable <em>OPP right</em></div><ul class=\"examples\"><li><strong><em>it is wrong that</strong>: It’s wrong that people should have to sleep on the streets.</em></li><li><strong><em>it is wrong to do something</strong>: We all accept that it is wrong to torture people.</em></li><li><em>We weren’t doing anything wrong!</em></li><li><strong><em>wrong with</strong>: There’s nothing wrong with making a profit, provided you don’t cheat anyone.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[not suitable]</strong> not suitable for a particular purpose, situation, or person <em>OPP right</em>:</div><ul class=\"examples\"><li><em>It’s the wrong time of year to be planning a holiday.</em></li><li><strong><em>wrong for</strong>: Anna and I were wrong for each other in dozens of ways (=not suited for a romantic relationship with each other).</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[not working]</strong> if something is wrong with a vehicle or machine, it stops working properly → go wrong at wrong2(2)</div><ul class=\"examples\"><li><strong><em>wrong with</strong>: There’s something wrong with the car again.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[unpleasant]</strong> <em>informal</em> unpleasant and upsetting or offensive – often used humorously:</div><ul class=\"examples\"><li><em>That joke&#x27;s just wrong, man!</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>be the wrong way round/around</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to be in the wrong order:</div><ul class=\"examples\"><li><em>These two paragraphs are the wrong way round.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if something is the wrong way round, the back is where the front should be:</div><ul class=\"examples\"><li><em>You’ve got your T-shirt on the wrong way around.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>the wrong way up</strong> if something is the wrong way up, the top is where the bottom should be <em>SYN upside down</em>:</div><ul class=\"examples\"><li><em>The painting was hung the wrong way up.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>take something the wrong way</strong> to be offended by a remark because you have understood it wrongly:</div><ul class=\"examples\"><li><em>I like you. Don’t take this the wrong way, now. I mean as a friend.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>be in the wrong place at the wrong time</strong> <em>spoken</em> to get involved in trouble without intending to</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>get on the wrong side of somebody</strong> to do something that gives someone a bad opinion of you, so that they do not like or respect you in the future:</div><ul class=\"examples\"><li><em>I wouldn’t like to get on the wrong side of her.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>get on the wrong side of the law</strong> to get into trouble with the police</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>get off on the wrong foot</strong> to start a job, relationship etc badly by making a mistake that annoys people</div><div class=\"sense\"><span class=\"snum\">16</span> <strong>get the wrong end of the stick</strong> <em>British English</em> <em>informal</em> to understand a situation in completely the wrong way:</div><ul class=\"examples\"><li><em>Geoff had got the wrong end of the stick, and thought I was angry with him.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>be on the wrong track/tack</strong> to have the wrong idea about a situation so that you are unlikely to get the result you want</div><div class=\"sense\"><span class=\"snum\">18</span> <strong>be from the wrong side of the tracks</strong> <em>American English</em> to be from a poor part of a town or a poor part of society</div><div class=\"sense\"><span class=\"snum\">19</span> <strong>be the wrong side of thirty/forty etc</strong> <em>informal</em> to be older than 30 etc → get out of bed on the wrong side at bed1(8)</div><div class=\"sense\"><span class=\"snum\">20</span> <strong>correct me if I’m wrong</strong> used as a polite way of saying that you think what you are going to say is correct:</div><ul class=\"examples\"><li><em>Correct me if I’m wrong, but didn’t you say you were going to do it?</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>you’re not wrong</strong> <em>spoken</em> used to agree with someone:</div><ul class=\"examples\"><li><em>‘This government is ruining the country!’ ‘You’re not wrong there!’</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>fall/get into the wrong hands</strong> if something secret or dangerous falls into the wrong hands, it is discovered by someone who may use it to harm people</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not in the correct way <em>OPP right</em>:</div><ul class=\"examples\"><li><em>You’ve spelt my name wrong.</em></li><li><em>What? Have I done it wrong?</em></li><li><em>I asked him to sort those files, but he’s done it all wrong (=in completely the wrong way).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>go wrong</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to stop working properly:</div><ul class=\"examples\"><li><em>Something’s gone wrong with my watch.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to make a mistake during a process so that you do not get the right result:</div><ul class=\"examples\"><li><em>Follow these instructions and you can’t go wrong (=you are sure to succeed).</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> to do something that makes a plan, relationship etc fail:</div><ul class=\"examples\"><li><em>Thinking back on the marriage, I just don’t know where we went wrong.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>get something wrong</strong> to make a mistake in the way you write, judge, or understand something:</div><ul class=\"examples\"><li><em>This isn’t it. We must have got the address wrong.</em></li><li><strong><em>get/have it all wrong</strong> (=understand a situation in completely the wrong way): No, no – you’ve got it all wrong! We’re just friends!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>don’t get me wrong</strong> <em>spoken</em> used when you think someone may understand your remarks wrongly, or be offended by them:</div><ul class=\"examples\"><li><em>Don’t get me wrong – I like Jenny.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>you can’t go wrong (with something)</strong> <em>spoken</em> used to say that a particular object will always be suitable, satisfactory, or work well:</div><ul class=\"examples\"><li><em>You can’t go wrong with a little black dress, can you?</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> behaviour that is not morally right:</div><ul class=\"examples\"><li><em>He’s too young to know right from wrong.</em></li><li><em>Those who do wrong should be punished.</em></li><li><strong><em>somebody can do no wrong</strong> (=they are perfect): Nathan adored her, and she could do no wrong in his eyes.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> an action, judgment, or situation that is unfair:</div><ul class=\"examples\"><li><em>The black population suffered countless wrongs at the hands of a racist regime.</em></li><li><strong><em>right a wrong</strong> (=bring justice to an unfair situation)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be in the wrong</strong> to make a mistake or deserve the blame for something:</div><ul class=\"examples\"><li><em>Which driver was in the wrong?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>do somebody wrong</strong> to treat someone badly and unfairly – used humorously</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>two wrongs don’t make a right</strong> <em>spoken</em> used to say that if someone does something bad to you, you should not do something bad to them</div></div></div>","7810":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> wrong‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈrɒŋli $ ˈrɒːŋ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not correctly or in a way that is not based on facts <em>OPP rightly</em>:</div><ul class=\"examples\"><li><em>Matthew was wrongly diagnosed as having a brain tumour.</em></li><li><em>His name had been wrongly spelt.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in a way that is unfair or immoral <em>OPP rightly</em>:</div><ul class=\"examples\"><li><em>Human rights organizations maintain that the men have been wrongly convicted.</em></li></ul></div>"};